INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C1','sci',6,2,'u1',1,'계절에 따른 우리 주변의 모습 — 계절에 따라 동식물·옷차림·음식·즐기는 운동 등 우리 주변의 모습이 달라짐 · 봄에는 여러 가지 꽃이 피고, 여름에는 나뭇잎 색깔이 짙어지고 계곡·바다에서 물놀이를 하며, 가을에는 울긋불긋한 단풍이 들고, 겨울에는 나뭇잎이 떨어지고 눈이 내려 눈사람을 만들고 눈썰매를 탐 · 「다른 계절을 말하는 친구 찾기」 놀이: 한 장만 다른 계절을 쓰고, 계절 이름은 말하지 않고 모습으로 표현하며, 종이는 같은 모양으로 접어 내용이 보이지 않게 전달, 지목은 손 전체로, 의견이 다르면 많은 사람이 지목한 사람으로 · 친구 발표를 경청하고 공감',ARRAY['6과 계절의 변화 — 계절에 따른 태양의 남중 고도·낮의 길이·태양 에너지양 설명(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C2','sci',6,2,'u1',2,'태양 고도와 태양 고도 측정기 — 하루 동안 태양은 동쪽 하늘에서 남쪽 하늘을 지나 서쪽 하늘로 위치가 달라지며 높이도 달라짐 · 태양 고도는 태양의 높이를 태양이 지표면과 이루는 각으로 나타낸 것이고 각도기로 잼 · 수수깡과 실 측정기(우드록에 자를 붙이고 10 cm 정도 수수깡을 자의 0 위치에 수직으로 꽂아 끝에 실을 묶고 각도기 구멍에 끼움 → 실을 그림자 끝에 맞추어 그림자와 실이 이루는 각을 읽음), 기울이는 각도기 측정기(태양 빛에 평행하게 기울여 선이 만날 때의 각), 이쑤시개 측정기(그림자가 보이지 않게 조절한 때의 각) 등 여러 가지로 만들 수 있음 · 태양 빛은 거의 평행하게 들어오므로 막대기 길이가 달라져도 그림자 길이가 함께 달라질 뿐 태양 고도는 그대로 · 가위 안전, 자르기 쉬운 우드록, 다음 시간을 위해 잘 보관',ARRAY['6과 계절의 변화 — 하루 동안 태양 고도·그림자 길이·기온을 측정해 관계 찾기(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C3','sci',6,2,'u1',3,'하루 동안 태양 고도·그림자 길이·기온의 관계 — 하루 동안 태양 고도는 점점 높아졌다가 다시 낮아짐 · 태양 고도가 높아지면 그림자 길이는 짧아지고 기온은 높아지며, 낮아지면 그림자 길이는 길어지고 기온은 낮아짐 · 태양 고도 그래프와 기온 그래프는 모양이 비슷하고 그림자 길이 그래프는 반대 모양 · 태양 고도가 가장 높은 시각(12시 30분 무렵)과 기온이 가장 높은 시각(14시 30분 무렵)에는 차이가 있음(실험관찰 예시: 고도 최고 51.7° · 그림자 최소 7.9 cm @12:30, 기온 최고 27.0 °C @14:30)',ARRAY['6과 계절의 변화 — 하루 동안 태양 고도·그림자 길이·기온을 측정해 관계 찾기(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C4','sci',6,2,'u1',3,'태양의 남중과 남중 고도 — 태양이 정남쪽에 위치하는 것을 태양이 남중했다고 하고, 이때의 태양 고도를 태양의 남중 고도라고 함 · 하루 중 태양 고도가 가장 높을 때이며 그림자 길이가 가장 짧음 · 태양이 뜨고 지는 시각과 남중 고도가 매일 조금씩 달라지므로 매일 같은 시각에 재어도 태양 고도는 조금씩 다름',ARRAY['6과 계절의 변화 — 하루 동안 태양 고도·그림자 길이·기온을 측정해 관계 찾기(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C5','sci',6,2,'u1',3,'하루 동안의 측정과 꺾은선그래프 — 측정기를 태양 빛이 잘 드는 평평한 곳에 놓고 그림자가 자(눈금)와 평행하게 맞춤 · 기온은 그늘지고 지표면에서 1.5 m 정도 높이에서 온도계로 잼 · 오전 9시 30분부터 한 시간 간격으로, 남중하는 12시 30분을 포함해 일정한 간격으로 잼 · 꺾은선그래프는 시간에 따른 측정값의 변화를 나타내며 가로축에 측정 시각을 일정한 간격으로, 세 그래프는 다른 색으로 그리고 가로축을 맞춰 겹쳐 비교함 · 태양을 직접 보지 않고 모자 쓰기, 야외 활동 뒤 손 씻기',ARRAY['6과 계절의 변화 — 하루 동안 태양 고도·그림자 길이·기온을 측정해 관계 찾기(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C6','sci',6,2,'u1',4,'계절별 태양의 남중 고도와 낮의 길이 — 낮의 길이는 태양이 지평선 위로 떠 있는 시간 · 생활 천문관의 「태양 고도/방위각 계산」(남중 고도)과 「일출 일몰 시각 계산」(낮의 길이)으로 매월 21일을 조사해 꺾은선그래프로 나타냄 · 여름에 남중 고도가 가장 높고 낮의 길이가 가장 길며 겨울에 가장 낮고 짧음, 봄·가을은 중간 정도(서울 2024 예시: 6월 75.52°·14시간 45분, 12월 29.00°·9시간 33분) · 남중 고도가 높아질수록 낮의 길이가 길어짐, 두 그래프 모양이 비슷 · 낮의 길이는 월별로 뚝 끊기지 않고 연속적으로 달라짐 · 지역마다 값에 차이가 있어 사는 지역 중심으로 조사하고 지역·연도를 적음 · 계절별로 같은 시각 그림자는 겨울에서 여름으로 갈수록 짧아짐',ARRAY['6과 계절의 변화 — 계절에 따른 태양의 남중 고도·낮의 길이·태양 에너지양 설명(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C7','sci',6,2,'u1',5,'태양 고도와 태양 에너지양 — 손전등(태양)과 스마트 기기(지표면)가 이루는 각(태양 고도)을 바꾸며 빛의 세기 측정 애플리케이션으로 센서가 받는 에너지양(태양 에너지양)을 비교 · 빨판 달린 막대의 그림자가 짧을 때 각이 크고 빛의 세기가 셈(예 1,412), 길 때 각이 작고 약함(예 986) · 손전등과 스마트 기기 사이 거리는 약 20 cm로 일정하게, 주변 빛이 없게 교실을 어둡게, 빛을 눈에 비추지 않기 · 태양 고도가 높아질수록 일정한 면적의 지표면이 받는 태양 에너지양이 많아지고 낮아질수록 적어짐',ARRAY['6과 계절의 변화 — 계절에 따른 태양의 남중 고도·낮의 길이·태양 에너지양 설명(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C8','sci',6,2,'u1',5,'여름에 덥고 겨울에 추운 까닭 — 여름에는 태양의 남중 고도가 높아 일정한 면적의 지표면이 받는 태양 에너지양이 많아 덥고, 겨울에는 남중 고도가 낮아 태양 에너지양이 적어 추움 · 한옥 처마: 남중 고도가 높은 여름에는 태양 빛이 처마에 가려 집 안으로 들어오는 빛이 적고, 낮은 겨울에는 가려지지 않아 많이 들어옴',ARRAY['6과 계절의 변화 — 계절에 따른 태양의 남중 고도·낮의 길이·태양 에너지양 설명(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C9','sci',6,2,'u1',6,'계절 변화의 원인 — 자전축은 지구의 북극과 남극을 이은 가상의 직선, 공전은 지구가 태양을 중심으로 일 년에 한 바퀴씩 서쪽에서 동쪽으로 도는 것 · 지구본 우리나라 자리에 측정기를 붙이고 전등 중심 높이를 지구본 중심과 같게, 30 cm 거리에서 가·나·다·라로 공전시키며 그림자 길이를 잼(다르게 할 조건 = 자전축 기울기, 자전축은 늘 같은 방향) · 수직인 채 공전하면 그림자 길이가 같아(예 1.4 cm) 남중 고도가 달라지지 않아 계절 변화가 생기지 않고, 기울어진 채 공전하면 위치에 따라 그림자 길이가 달라짐(예 1.4·0.8·1.4·3.5 cm) · 지구의 자전축이 기울어진 채 공전하므로 위치에 따라 남중 고도·낮의 길이·태양 에너지양이 달라져 계절 변화가 생김 · 북반구가 태양 쪽으로 기울면 여름 · 태양과의 거리는 계절 변화에 거의 영향이 없음(북반구는 여름에 오히려 더 멂)',ARRAY['6과 계절의 변화 — 계절 변화의 원인을 자전축이 기울어진 채 공전하는 것으로 설명(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C10','sci',6,2,'u1',7,'계절 축제 안내 자료 만들기 — 계획하기(축제를 골라 그 시기의 태양의 남중 고도·낮의 길이·기온 조사, 준비물·옷차림·운영 시간, 추가 안내) → 해 보기(디자인 플랫폼으로 만들고 모둠별로 모으기) → 나누기(공유 플랫폼에 올리고 잘한 점을 댓글로 칭찬) · 예: 수박 축제(남중 고도가 높아 그늘막·색안경·자외선 차단제·시원한 옷, 낮이 길어 오전 10시~오후 7시), 단풍 축제(여름보다 낮이 짧아 해 지는 시각 확인), 눈꽃 축제(기온이 낮아 따뜻한 옷) · 평가는 꾸밈이 아니라 세 과학 정보를 설명했는지 · 다른 모둠 아이디어를 그대로 쓰지 않고 바르고 고운 말로 칭찬',ARRAY['6과 계절의 변화 — 계절에 따른 태양의 남중 고도·낮의 길이·태양 에너지양 설명(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC6-2-u1-C11','sci',6,2,'u1',8,'태양 에너지를 많이 받기 위한 과학 기술 — 태양 고도가 달라지면 일정한 면적의 지표면이 받는 태양 에너지양이 달라진다는 과학적 사실에서 기술이 나옴 · 추적형 태양광 발전기는 태양의 위치와 고도를 따라 방향·각도를 움직여 태양과 발전기 면이 이루는 각을 수직으로 유지해 고정형보다 전기를 더 많이 생산 · 햇빛 지도는 장소별로 일 년 동안 받을 수 있는 태양 에너지양을 알려 주어 설치 장소를 고르게 함 · 태양광 발전은 태양 빛을 이용한 재생 에너지 발전으로 태양 에너지를 전기 에너지로 바꾸며 지붕·외벽·유리의 태양 전지판으로 생산 · 거울로 빛 모으기, 태양 전지판 가방 · 직업: 태양광 발전 연구 및 개발자, 태양광 설치 전문가 · 안전하고 지속가능한 사회 · 최신·비쌈이 아니라 과학적 사실로 판단',ARRAY['6과 계절의 변화 — 계절에 따른 태양의 남중 고도·낮의 길이·태양 에너지양 설명(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X01','sci',6,'u1',ARRAY['SC6-2-u1-C1']::text[],'계절에 따른 우리 주변의 모습(동식물·옷차림·음식·운동)을 다른 계절과 바꾸어 짝짓거나 계절이 바뀌어도 주변 모습이 그대로라고 여긴다','꽃 · 짙은 잎과 물놀이 · 단풍 · 눈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X02','sci',6,'u1',ARRAY['SC6-2-u1-C1']::text[],'「다른 계절을 말하는 친구 찾기」 놀이의 규칙과 태도(한 장만 다른 계절, 계절 이름 말하지 않기, 손 전체로 지목, 경청)를 잘못 안다','계절 이름 대신 모습으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X03','sci',6,'u1',ARRAY['SC6-2-u1-C2']::text[],'태양 고도를 태양까지의 거리·떠 있는 시간·빛의 밝기·막대기 길이 등으로 여겨 「태양이 지표면과 이루는 각」임을 놓친다','지표면과 이루는 각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X04','sci',6,'u1',ARRAY['SC6-2-u1-C2']::text[],'막대기의 길이가 달라지면 태양 고도도 다르게 측정된다고 여긴다','태양 빛은 거의 평행 · 그림자도 함께 길어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X05','sci',6,'u1',ARRAY['SC6-2-u1-C2']::text[],'태양 고도 측정기를 만드는 순서·재료·안전이나 측정기마다 재는 방법을 잘못 안다(막대기를 기울여 꽂기, 실을 그림자 끝에 맞추지 않기 등)','수직으로 꽂기 · 실은 그림자 끝에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X06','sci',6,'u1',ARRAY['SC6-2-u1-C2','SC6-2-u1-C3']::text[],'하루 동안 태양 고도가 계속 높아지기만 하거나 그대로라고, 또는 위치만 바뀌고 높이는 그대로라고 여긴다','높아졌다가 다시 낮아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X07','sci',6,'u1',ARRAY['SC6-2-u1-C3','SC6-2-u1-C4']::text[],'태양 고도와 그림자 길이의 관계를 거꾸로 안다(태양 고도가 높아지면 그림자도 길어진다고)','높이 뜨면 그림자는 짧아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X08','sci',6,'u1',ARRAY['SC6-2-u1-C3']::text[],'태양 고도와 기온의 관계를 거꾸로 알거나 관계가 없다고 여긴다','태양 고도가 높아지면 기온도 높아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X09','sci',6,'u1',ARRAY['SC6-2-u1-C3']::text[],'하루 중 태양 고도가 가장 높을 때 기온도 가장 높다고 여긴다','두 시각에는 차이가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X10','sci',6,'u1',ARRAY['SC6-2-u1-C4']::text[],'태양의 남중·남중 고도의 뜻을 잘못 안다(뜨거나 지는 순간, 기온이 가장 높을 때의 고도라고 하는 등)','정남쪽 · 하루 중 가장 높을 때') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X11','sci',6,'u1',ARRAY['SC6-2-u1-C4']::text[],'매일 같은 시각에 태양 고도를 재면 항상 같은 값이 나온다고 여긴다','뜨고 지는 시각이 매일 조금씩 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X12','sci',6,'u1',ARRAY['SC6-2-u1-C5']::text[],'하루 동안 측정하고 꺾은선그래프로 나타내는 방법이나 안전을 잘못 안다(태양을 직접 보기, 햇빛 아래 땅바닥에서 기온 재기, 간격 마음대로, 가로축을 다르게 쓰기 등)','그늘 1.5 m · 일정한 간격 · 같은 가로축') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X13','sci',6,'u1',ARRAY['SC6-2-u1-C6','SC6-2-u1-C8']::text[],'계절별 태양의 남중 고도·낮의 길이를 거꾸로 안다(겨울에 남중 고도가 높거나 낮이 길다고 하는 등)','여름 높고 길게 · 겨울 낮고 짧게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X14','sci',6,'u1',ARRAY['SC6-2-u1-C6']::text[],'태양의 남중 고도와 낮의 길이의 관계를 거꾸로 알거나 서로 관계가 없다고 여긴다','남중 고도가 높아질수록 낮이 길어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X15','sci',6,'u1',ARRAY['SC6-2-u1-C6']::text[],'낮의 길이가 달이 바뀔 때만 뚝 끊겨 달라진다고 여긴다','연속적으로 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X16','sci',6,'u1',ARRAY['SC6-2-u1-C6']::text[],'같은 계절이면 어느 지역에서나 남중 고도·낮의 길이가 똑같다고 여기거나, 조사할 때 지역·연도를 적지 않는 등 조사 방법을 잘못 안다','지역마다 차이 · 지역과 연도 적기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X17','sci',6,'u1',ARRAY['SC6-2-u1-C7']::text[],'태양 고도와 태양 에너지양(빛의 세기)의 관계를 거꾸로 알거나 관계가 없다고 여긴다','높이 뜰수록 많이 받아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X18','sci',6,'u1',ARRAY['SC6-2-u1-C7']::text[],'손전등 모형실험의 조건과 대응을 잘못 안다(거리를 바꾸기, 손전등을 지표면이라 하기, 가까이 가져가면 각이 커진다고 하는 등)','거리는 그대로 · 각만 바꿔요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X19','sci',6,'u1',ARRAY['SC6-2-u1-C8']::text[],'여름에 덥고 겨울에 추운 까닭을 태양의 남중 고도·태양 에너지양과 잇지 못하거나 거꾸로 잇는다','남중 고도 → 태양 에너지양 → 기온') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X20','sci',6,'u1',ARRAY['SC6-2-u1-C9']::text[],'여름에는 지구가 태양과 가까워서 덥고 겨울에는 멀어서 춥다고 여긴다','거리는 계절에 거의 영향이 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X21','sci',6,'u1',ARRAY['SC6-2-u1-C9']::text[],'계절 변화의 원인을 잘못 안다(자전축이 수직이라서, 공전하지 않아서, 자전축이 기울어진 방향을 계절마다 바꿔서 등)','기울어진 채 공전') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X22','sci',6,'u1',ARRAY['SC6-2-u1-C9']::text[],'자전축 모형실험에서 다르게 할 조건·같게 할 조건이나 그 결과를 잘못 안다','기울기만 다르게 · 거리·높이·방향은 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X23','sci',6,'u1',ARRAY['SC6-2-u1-C10']::text[],'계절 축제 안내 자료에서 계절별 과학 정보(남중 고도·낮의 길이·기온)를 빼거나 계절과 맞지 않게 안내하고, 꾸미기·베끼기·지적하는 댓글처럼 활동 태도를 잘못 안다','세 과학 정보 · 나만의 생각 · 칭찬 댓글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC6-2-u1-X24','sci',6,'u1',ARRAY['SC6-2-u1-C11']::text[],'태양 에너지 기술을 신기함·값으로 판단하거나 기술이 하는 일과 그 바탕이 된 과학적 사실(태양 고도가 달라짐)을 놓친다','어떤 과학적 사실에서 나왔나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#1','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',1,'mc','auto','울긋불긋한 단풍을 볼 수 있는 계절은 언제인가요?',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"mc","stem":"울긋불긋한 단풍을 볼 수 있는 계절은 언제인가요?","options":[{"t":"가을","correct":true},{"t":"봄","mis":"SC6-2-u1-X01"},{"t":"여름","mis":"SC6-2-u1-X01"},{"t":"겨울","mis":"SC6-2-u1-X01"}],"explanation":["나뭇잎 색이 바뀌는 때예요.","빨갛고 노랗게 물들어요.","가을이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#2','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',1,'match','auto','계절과 그 계절의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"match","stem":"계절과 그 계절의 모습을 알맞게 이으세요.","pairs":[{"l":"봄","r":"여러 가지 꽃이 핀다"},{"l":"여름","r":"나뭇잎의 색깔이 짙어진다"},{"l":"가을","r":"알록달록한 단풍이 든다"},{"l":"겨울","r":"나뭇잎이 떨어지고 눈이 내린다"}],"mis":"SC6-2-u1-X01","explanation":["꽃은 봄이에요.","짙은 잎은 여름이에요.","단풍은 가을, 눈은 겨울이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#3','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',1,'ox','auto','계절이 바뀌어도 우리 주변의 모습은 그대로예요.',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"ox","stem":"계절이 바뀌어도 우리 주변의 모습은 그대로예요.","answer":"X","reason_options":[{"t":"계절에 따라 동식물·옷차림·음식 같은 주변 모습이 달라지기 때문에","correct":true},{"t":"계절은 달력의 이름만 바뀌는 것이기 때문에","mis":"SC6-2-u1-X01"}],"mis":"SC6-2-u1-X01","explanation":["옷차림을 떠올려요.","먹는 음식도 달라요.","그대로가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#4','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',1,'sa','auto','봄에는 여러 가지 □이 핍니다. □에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"sa","stem":"봄에는 여러 가지 □이 핍니다. □에 알맞은 한 글자를 쓰세요.","answer":["꽃"],"explanation":["봄의 모습이에요.","개나리·진달래 같은 것이에요.","꽃이에요."],"mis":"SC6-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#5','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',2,'mc','auto','놀이에서 모둠원이 네 명이면 종이에 계절을 어떻게 쓰나요?',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C1","difficulty":2,"kind":"mc","stem":"놀이에서 모둠원이 네 명이면 종이에 계절을 어떻게 쓰나요?","options":[{"t":"세 장에는 같은 계절을, 한 장에는 다른 계절을 쓴다","correct":true},{"t":"네 장 모두 같은 계절을 쓴다","mis":"SC6-2-u1-X02"},{"t":"네 장 모두 서로 다른 계절을 쓴다","mis":"SC6-2-u1-X02"},{"t":"계절 대신 자기 이름을 쓴다","mis":"SC6-2-u1-X02"}],"explanation":["한 사람만 달라요.","그 사람을 찾는 놀이예요.","세 장은 같고 한 장은 달라요."],"asset":{"type":"passage","lines":["① 모둠원 수만큼 종이를 준비한다.","② 한 장을 뺀 나머지에는 같은 계절을, 한 장에는 다른 계절을 쓴다.","③ 종이를 같은 모양으로 접어 내용이 보이지 않게 나누어 갖는다.","④ 계절 이름은 말하지 않고 그 계절의 모습을 이야기한다.","⑤ 다른 계절을 말하는 사람을 손 전체로 함께 지목한다."],"title":"다른 계절을 말하는 친구 찾기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#6','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',2,'mc','auto','놀이에서 이야기할 때 그대로 넣지 않는 것은 어느 것인가요?',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C1","difficulty":2,"kind":"mc","stem":"놀이에서 이야기할 때 그대로 넣지 않는 것은 어느 것인가요?","options":[{"t":"내 종이에 쓰인 계절 이름","correct":true},{"t":"계절에 볼 수 있는 동식물","mis":"SC6-2-u1-X02"},{"t":"계절에 따라 달라지는 옷차림","mis":"SC6-2-u1-X02"},{"t":"계절에 많이 먹는 음식","mis":"SC6-2-u1-X02"}],"explanation":["들키면 안 되는 것이 있어요.","모습으로만 표현해요.","계절 이름은 말하지 않아요."],"asset":{"type":"passage","lines":["① 모둠원 수만큼 종이를 준비한다.","② 한 장을 뺀 나머지에는 같은 계절을, 한 장에는 다른 계절을 쓴다.","③ 종이를 같은 모양으로 접어 내용이 보이지 않게 나누어 갖는다.","④ 계절 이름은 말하지 않고 그 계절의 모습을 이야기한다.","⑤ 다른 계절을 말하는 사람을 손 전체로 함께 지목한다."],"title":"다른 계절을 말하는 친구 찾기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#7','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',2,'ox','auto','다른 계절을 말하는 친구를 지목할 때는 손가락으로 콕 가리켜요.',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C1","difficulty":2,"kind":"ox","stem":"다른 계절을 말하는 친구를 지목할 때는 손가락으로 콕 가리켜요.","answer":"X","reason_options":[{"t":"손 전체로 가리켜 지목된 친구가 불쾌감을 느끼지 않게 하기 때문에","correct":true},{"t":"손가락으로 가리켜야 더 정확하기 때문에","mis":"SC6-2-u1-X02"}],"mis":"SC6-2-u1-X02","explanation":["지목받는 친구의 마음을 생각해요.","손 전체로 가리켜요.","손가락은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#8','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',2,'mc','auto','계절 이름을 말하지 않고 여름의 모습을 알맞게 표현한 이야기는 어느 것인가요?',ARRAY['SC6-2-u1-X02','SC6-2-u1-X01']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C1","difficulty":2,"kind":"mc","stem":"계절 이름을 말하지 않고 여름의 모습을 알맞게 표현한 이야기는 어느 것인가요?","options":[{"t":"이 계절에는 계곡이나 바다에서 물놀이를 많이 합니다","correct":true},{"t":"이 계절은 여름입니다","mis":"SC6-2-u1-X02"},{"t":"이 계절에는 눈썰매를 많이 탑니다","mis":"SC6-2-u1-X01"},{"t":"이 계절에는 단풍 구경을 갑니다","mis":"SC6-2-u1-X01"}],"explanation":["계절 이름은 빼요.","여름에 하는 일을 떠올려요.","물놀이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#9','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',2,'error','auto','계절의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C1","difficulty":2,"kind":"error","stem":"계절의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「겨울에는 나뭇잎의 색깔이 짙어져.」","correct":true,"mis_target":"SC6-2-u1-X01"},{"t":"준서 — 「봄에는 꽃이 피어 세상이 밝아져.」","mis":"SC6-2-u1-X01"},{"t":"하린 — 「가을에는 단풍이 들어.」","mis":"SC6-2-u1-X01"}],"explanation":["겨울에는 나뭇잎이 떨어져요.","잎이 짙어지는 건 여름이에요.","서윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_basic#10','sci',6,2,'u1','L01','g6_2_sci_u1_L01_basic','lesson_basic','SC6-2-u1-C1',3,'mc','auto','지목할 때 모둠원의 의견이 서로 다르면 어떻게 정하나요?',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C1","difficulty":3,"kind":"mc","stem":"지목할 때 모둠원의 의견이 서로 다르면 어떻게 정하나요?","options":[{"t":"많은 사람이 지목한 사람으로 정한다","correct":true},{"t":"가장 먼저 말한 사람의 의견으로 정한다","mis":"SC6-2-u1-X02"},{"t":"가위바위보로 정한다","mis":"SC6-2-u1-X02"},{"t":"아무도 지목하지 않고 끝낸다","mis":"SC6-2-u1-X02"}],"explanation":["모둠원 모두의 생각을 모아요.","여러 사람이 고른 쪽이에요.","많이 지목한 사람이에요."],"asset":{"type":"passage","lines":["① 모둠원 수만큼 종이를 준비한다.","② 한 장을 뺀 나머지에는 같은 계절을, 한 장에는 다른 계절을 쓴다.","③ 종이를 같은 모양으로 접어 내용이 보이지 않게 나누어 갖는다.","④ 계절 이름은 말하지 않고 그 계절의 모습을 이야기한다.","⑤ 다른 계절을 말하는 사람을 손 전체로 함께 지목한다."],"title":"다른 계절을 말하는 친구 찾기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#1','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',2,'mc','auto','놀이에서 이야기할 거리로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C1","difficulty":2,"kind":"mc","stem":"놀이에서 이야기할 거리로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구의 이야기가 재미없다는 말","correct":true},{"t":"계절에 따라 즐기는 운동","mis":"SC6-2-u1-X02"},{"t":"계절에 따라 달라지는 옷차림","mis":"SC6-2-u1-X02"},{"t":"계절에 따라 볼 수 있는 동식물","mis":"SC6-2-u1-X02"}],"explanation":["계절의 모습을 말해요.","친구를 존중해요.","흉보는 말은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#2','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',2,'sa','auto','봄·여름·가을·겨울처럼 한 해를 날씨와 모습에 따라 나눈 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C1","difficulty":2,"kind":"sa","stem":"봄·여름·가을·겨울처럼 한 해를 날씨와 모습에 따라 나눈 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["계절"],"explanation":["네 가지가 있어요.","봄도 그중 하나예요.","계절이에요."],"mis":"SC6-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#3','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',3,'mc','auto','친구가 「이 계절에는 두꺼운 외투와 장갑이 필요해.」라고 했어요. 이 친구가 말한 계절의 모습으로 함께 어울리는 것은 어느 것인가요?',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C1","difficulty":3,"kind":"mc","stem":"친구가 「이 계절에는 두꺼운 외투와 장갑이 필요해.」라고 했어요. 이 친구가 말한 계절의 모습으로 함께 어울리는 것은 어느 것인가요?","options":[{"t":"눈이 내려 눈사람을 만들고 눈썰매를 탄다","correct":true},{"t":"꽃이 피어 온 세상이 밝아진다","mis":"SC6-2-u1-X01"},{"t":"계곡에서 물놀이를 한다","mis":"SC6-2-u1-X01"},{"t":"나뭇잎이 울긋불긋 물든다","mis":"SC6-2-u1-X01"}],"explanation":["외투와 장갑은 추울 때예요.","추운 계절의 모습을 골라요.","눈사람과 눈썰매예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#4','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',3,'error','auto','놀이 규칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C1","difficulty":3,"kind":"error","stem":"놀이 규칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「종이에 적힌 내용이 잘 보이게 펼쳐서 건네자.」","correct":true,"mis_target":"SC6-2-u1-X02"},{"t":"예린 — 「종이는 모두 같은 모양으로 접자.」","mis":"SC6-2-u1-X02"},{"t":"도현 — 「다른 계절인 사람은 들키지 않게 표현하자.」","mis":"SC6-2-u1-X02"}],"explanation":["내용이 보이면 놀이가 안 돼요.","보이지 않게 건네요.","지호가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 모둠원 수만큼 종이를 준비한다.","② 한 장을 뺀 나머지에는 같은 계절을, 한 장에는 다른 계절을 쓴다.","③ 종이를 같은 모양으로 접어 내용이 보이지 않게 나누어 갖는다.","④ 계절 이름은 말하지 않고 그 계절의 모습을 이야기한다.","⑤ 다른 계절을 말하는 사람을 손 전체로 함께 지목한다."],"title":"다른 계절을 말하는 친구 찾기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#5','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',3,'mc','auto','놀이에서 계절 이름을 그대로 말하지 않는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C1","difficulty":3,"kind":"mc","stem":"놀이에서 계절 이름을 그대로 말하지 않는 까닭은 무엇인가요?","options":[{"t":"다른 사람들이 어느 계절인지 잘 알아채지 못하도록 하기 위해서","correct":true},{"t":"계절 이름은 너무 어려워서","mis":"SC6-2-u1-X02"},{"t":"계절 이름을 말하면 종이가 찢어져서","mis":"SC6-2-u1-X02"},{"t":"계절 이름은 네 개보다 많아야 해서","mis":"SC6-2-u1-X02"}],"explanation":["놀이의 목표를 떠올려요.","숨은 한 사람을 찾아요.","알아채지 못하게 하려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#6','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',3,'ox','auto','다른 계절 종이를 받은 사람도 자기 계절의 모습을 알맞게 표현해 이야기해야 해요.',ARRAY['SC6-2-u1-X02']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C1","difficulty":3,"kind":"ox","stem":"다른 계절 종이를 받은 사람도 자기 계절의 모습을 알맞게 표현해 이야기해야 해요.","answer":"O","reason_options":[{"t":"다른 사람들이 잘 알아채지 못하도록 계절의 모습을 알맞게 표현하는 놀이이기 때문에","correct":true},{"t":"다른 계절 종이를 받은 사람은 아무 말도 하지 않아야 하기 때문에","mis":"SC6-2-u1-X02"}],"mis":"SC6-2-u1-X02","explanation":["모두가 이야기해요.","들키지 않게 표현해요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#7','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',3,'match','auto','이야기 거리의 종류와 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u1-C1","difficulty":3,"kind":"match","stem":"이야기 거리의 종류와 그 예를 알맞게 이으세요.","pairs":[{"l":"동식물","r":"꽃이 피고 나비가 날아다녀요"},{"l":"옷차림","r":"두꺼운 외투를 입어요"},{"l":"음식","r":"시원한 수박을 먹어요"},{"l":"운동","r":"눈썰매를 타요"}],"mis":"SC6-2-u1-X01","explanation":["살아 있는 것은 동식물이에요.","입는 것은 옷차림이에요.","먹는 것과 하는 것을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#8','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',4,'mc','auto','오늘 활동을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X01','SC6-2-u1-X02']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C1","difficulty":4,"kind":"mc","stem":"오늘 활동을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"계절에 따라 우리 주변의 모습이 달라지며, 친구의 발표를 경청하고 공감하며 이야기를 나눈다","correct":true},{"t":"계절이 바뀌어도 주변 모습은 같고, 계절 이름을 크게 말해야 한다","mis":"SC6-2-u1-X01"},{"t":"계절의 모습은 옷차림 하나뿐이다","mis":"SC6-2-u1-X01"},{"t":"지목할 때는 손가락으로 빠르게 가리킨다","mis":"SC6-2-u1-X02"}],"explanation":["주변 모습이 달라져요.","이야기 거리가 다양해요.","경청하고 공감해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#9','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',4,'mc','auto','네 명 가운데 세 명은 「가을」, 한 명은 「봄」 종이를 받았어요. 봄 종이를 받은 친구가 들키지 않으려면 어떤 이야기가 가장 알맞을까요?',ARRAY['SC6-2-u1-X02','SC6-2-u1-X01']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C1","difficulty":4,"kind":"mc","stem":"네 명 가운데 세 명은 「가을」, 한 명은 「봄」 종이를 받았어요. 봄 종이를 받은 친구가 들키지 않으려면 어떤 이야기가 가장 알맞을까요?","options":[{"t":"이 계절에는 야외로 소풍을 많이 갑니다","correct":true},{"t":"이 계절에는 여러 가지 꽃이 핍니다","mis":"SC6-2-u1-X02"},{"t":"저는 봄 종이를 받았습니다","mis":"SC6-2-u1-X02"},{"t":"이 계절에는 눈사람을 만듭니다","mis":"SC6-2-u1-X01"}],"explanation":["가을인 친구들 사이에 숨어야 해요.","두 계절에 다 어울리는 말을 골라요.","소풍 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L01_challenge#10','sci',6,2,'u1','L01','g6_2_sci_u1_L01_challenge','lesson_challenge','SC6-2-u1-C1',4,'essay','teacher','계절 하나를 골라 계절 이름을 말하지 않고 그 계절의 모습을 동식물·옷차림·음식 가운데 두 가지로 이야기해 보고, 친구가 발표할 때 지킬 태도를 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C1","difficulty":4,"kind":"essay","stem":"계절 하나를 골라 계절 이름을 말하지 않고 그 계절의 모습을 동식물·옷차림·음식 가운데 두 가지로 이야기해 보고, 친구가 발표할 때 지킬 태도를 한 가지 쓰세요.","answer_guide":{"answer":"예: 이 계절에는 나뭇잎이 떨어지고 눈이 내립니다. 두꺼운 외투와 장갑을 끼고 따뜻한 군고구마를 먹습니다. 친구가 발표할 때는 끝까지 귀 기울여 듣고 고개를 끄덕이며 공감합니다.","scoring_points":["계절 이름 없이 그 계절의 모습을 썼는가","동식물·옷차림·음식 가운데 두 가지를 썼는가","경청·공감 같은 태도를 썼는가"]},"explanation":["계절 이름은 빼요.","두 가지 모습을 써요.","듣는 태도를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#1','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',1,'mc','auto','태양 고도는 무엇인가요?',ARRAY['SC6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"mc","stem":"태양 고도는 무엇인가요?","options":[{"t":"태양의 높이를 태양이 지표면과 이루는 각으로 나타낸 것","correct":true},{"t":"태양에서 지구까지의 거리","mis":"SC6-2-u1-X03"},{"t":"태양이 하늘에 떠 있는 시간","mis":"SC6-2-u1-X03"},{"t":"태양이 내보내는 빛의 밝기","mis":"SC6-2-u1-X03"}],"explanation":["높이를 각으로 나타내요.","지표면과 이루는 각이에요.","그것이 태양 고도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#2','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',1,'sa','auto','태양의 높이를 각도로 나타내려면 어떤 도구가 필요한가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"sa","stem":"태양의 높이를 각도로 나타내려면 어떤 도구가 필요한가요? 세 글자로 쓰세요.","answer":["각도기"],"explanation":["각을 재는 도구예요.","수학 시간에도 써요.","각도기예요."],"mis":"SC6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#3','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',1,'ox','auto','하루 동안 태양은 동쪽 하늘에서 남쪽 하늘을 지나 서쪽 하늘로 위치가 달라지면서 높이도 달라져요.',ARRAY['SC6-2-u1-X06']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"ox","stem":"하루 동안 태양은 동쪽 하늘에서 남쪽 하늘을 지나 서쪽 하늘로 위치가 달라지면서 높이도 달라져요.","answer":"O","reason_options":[{"t":"하루 동안 태양을 관찰하면 위치와 높이가 함께 달라지기 때문에","correct":true},{"t":"태양은 하루 내내 같은 자리에 머물러 있기 때문에","mis":"SC6-2-u1-X06"}],"mis":"SC6-2-u1-X06","explanation":["아침과 낮의 태양을 떠올려요.","위치가 바뀌어요.","높이도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#4','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',1,'mc','auto','수수깡과 실을 이용한 측정기에서 수수깡은 어느 정도 길이로 자르나요?',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"mc","stem":"수수깡과 실을 이용한 측정기에서 수수깡은 어느 정도 길이로 자르나요?","options":[{"t":"10 cm 정도","correct":true},{"t":"1 m 정도","mis":"SC6-2-u1-X05"},{"t":"1 mm 정도","mis":"SC6-2-u1-X05"},{"t":"휘어져도 아무 길이나","mis":"SC6-2-u1-X05"}],"explanation":["손바닥만 한 길이예요.","너무 길거나 짧지 않게요.","10 cm 정도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#5','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',2,'match','auto','수수깡과 실을 이용한 측정기의 준비물과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u1-C2","difficulty":2,"kind":"match","stem":"수수깡과 실을 이용한 측정기의 준비물과 하는 일을 알맞게 이으세요.","pairs":[{"l":"자","r":"우드록 한쪽에 양면테이프로 붙인다"},{"l":"수수깡","r":"자의 0 위치에 수직이 되도록 꽂는다"},{"l":"실","r":"수수깡의 끝부분에 묶는다"},{"l":"구멍 뚫린 각도기","r":"가운데 구멍에 실의 다른 쪽 끝을 끼운다"}],"mis":"SC6-2-u1-X05","explanation":["먼저 자를 붙여요.","수수깡은 수직으로 꽂아요.","실은 수수깡과 각도기를 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#6','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',2,'mc','auto','측정기를 만들 때 나무토막보다 우드록이 알맞은 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C2","difficulty":2,"kind":"mc","stem":"측정기를 만들 때 나무토막보다 우드록이 알맞은 까닭은 무엇인가요?","options":[{"t":"자르기 쉬워서","correct":true},{"t":"더 단단해서","mis":"SC6-2-u1-X05"},{"t":"더 무거워서","mis":"SC6-2-u1-X05"},{"t":"태양 빛을 막아 주어서","mis":"SC6-2-u1-X05"}],"explanation":["직접 잘라 만들어요.","가위로 다루기 쉬워야 해요.","자르기 쉬운 우드록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#7','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',2,'mc','auto','수수깡과 실을 이용한 측정기로 태양 고도를 재는 방법은 어느 것인가요?',ARRAY['SC6-2-u1-X03','SC6-2-u1-X05']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C2","difficulty":2,"kind":"mc","stem":"수수깡과 실을 이용한 측정기로 태양 고도를 재는 방법은 어느 것인가요?","options":[{"t":"실을 그림자 끝에 맞추고 그림자와 실이 이루는 각을 읽는다","correct":true},{"t":"막대기의 길이를 자로 잰다","mis":"SC6-2-u1-X03"},{"t":"태양을 직접 바라보며 각도기를 댄다","mis":"SC6-2-u1-X05"},{"t":"그림자 길이만 읽는다","mis":"SC6-2-u1-X03"}],"explanation":["실을 그림자 끝에 맞춰요.","그림자와 실이 각을 만들어요.","그 각을 읽어요."],"asset":{"type":"passage","lines":["㉮ 수수깡과 실 — 실을 그림자 끝에 맞추고 그림자와 실이 이루는 각을 읽는다.","㉯ 기울이는 각도기 — 태양 빛에 평행하게 기울여 선이 만날 때의 각을 읽는다.","㉰ 이쑤시개 — 막대기 그림자가 보이지 않게 종이를 조절한 때의 각을 읽는다."],"title":"태양 고도 측정기 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#8','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',2,'ox','auto','수수깡이 우드록에 기울어지게 꽂혀 있어도 태양 고도를 정확하게 잴 수 있어요.',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C2","difficulty":2,"kind":"ox","stem":"수수깡이 우드록에 기울어지게 꽂혀 있어도 태양 고도를 정확하게 잴 수 있어요.","answer":"X","reason_options":[{"t":"수수깡이 우드록에 수직이 되도록 고정해야 정확하게 잴 수 있기 때문에","correct":true},{"t":"막대기가 기운 방향은 재는 각과 상관없기 때문에","mis":"SC6-2-u1-X05"}],"mis":"SC6-2-u1-X05","explanation":["수직으로 꽂았어요.","기울면 각이 달라져요.","정확하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#9','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',2,'error','auto','측정기를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C2","difficulty":2,"kind":"error","stem":"측정기를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「가위를 휘두르며 빨리빨리 만들자.」","correct":true,"mis_target":"SC6-2-u1-X05"},{"t":"나은 — 「가위를 쓸 때 다치지 않게 조심하자.」","mis":"SC6-2-u1-X05"},{"t":"시우 — 「다음 시간에 또 쓰니 잘 보관하자.」","mis":"SC6-2-u1-X05"}],"explanation":["안전이 먼저예요.","가위로 장난치지 않아요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_basic#10','sci',6,2,'u1','L02','g6_2_sci_u1_L02_basic','lesson_basic','SC6-2-u1-C2',3,'mc','auto','같은 시각, 같은 곳에서 막대기만 더 긴 것으로 바꾸면 태양 고도는 어떻게 될까요?',ARRAY['SC6-2-u1-X04']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"mc","stem":"같은 시각, 같은 곳에서 막대기만 더 긴 것으로 바꾸면 태양 고도는 어떻게 될까요?","options":[{"t":"그림자도 함께 길어지므로 태양 고도는 달라지지 않는다","correct":true},{"t":"막대기가 길어진 만큼 태양 고도가 높아진다","mis":"SC6-2-u1-X04"},{"t":"막대기가 길어진 만큼 태양 고도가 낮아진다","mis":"SC6-2-u1-X04"},{"t":"태양 고도를 아예 잴 수 없게 된다","mis":"SC6-2-u1-X04"}],"explanation":["태양 빛은 거의 평행하게 와요.","그림자도 같이 길어져요.","각은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#1','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',2,'blank','auto','「태양의 높이는 태양이 (    )과 이루는 각으로 나타냅니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u1-X03']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C2","difficulty":2,"kind":"blank","stem":"「태양의 높이는 태양이 (    )과 이루는 각으로 나타냅니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"지표면","correct":true},{"t":"막대기","mis":"SC6-2-u1-X03"},{"t":"달","mis":"SC6-2-u1-X03"},{"t":"구름","mis":"SC6-2-u1-X03"}],"explanation":["태양과 땅 사이의 각이에요.","땅의 표면이에요.","지표면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#2','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',2,'mc','auto','각도기를 기울이면서 쓰는 측정기로 태양 고도를 재는 방법은 어느 것인가요?',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C2","difficulty":2,"kind":"mc","stem":"각도기를 기울이면서 쓰는 측정기로 태양 고도를 재는 방법은 어느 것인가요?","options":[{"t":"태양 빛에 평행하게 기울여 각도기와 우드록에 그은 선이 만날 때의 각을 읽는다","correct":true},{"t":"실을 그림자 끝에 맞추어 그림자와 실이 이루는 각을 읽는다","mis":"SC6-2-u1-X05"},{"t":"막대기 그림자가 가장 길어질 때까지 기다린다","mis":"SC6-2-u1-X05"},{"t":"태양을 똑바로 보며 각도기를 댄다","mis":"SC6-2-u1-X05"}],"explanation":["㉯를 찾아요.","태양 빛에 맞춰 기울여요.","선이 만나는 각이에요."],"asset":{"type":"passage","lines":["㉮ 수수깡과 실 — 실을 그림자 끝에 맞추고 그림자와 실이 이루는 각을 읽는다.","㉯ 기울이는 각도기 — 태양 빛에 평행하게 기울여 선이 만날 때의 각을 읽는다.","㉰ 이쑤시개 — 막대기 그림자가 보이지 않게 종이를 조절한 때의 각을 읽는다."],"title":"태양 고도 측정기 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#3','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',3,'match','auto','측정기와 태양 고도를 재는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"match","stem":"측정기와 태양 고도를 재는 방법을 알맞게 이으세요.","pairs":[{"l":"수수깡과 실","r":"그림자와 실이 이루는 각"},{"l":"기울이는 각도기","r":"선이 만날 때의 각"},{"l":"이쑤시개","r":"그림자가 보이지 않게 조절한 때의 각"}],"mis":"SC6-2-u1-X05","explanation":["실은 그림자 끝에 맞춰요.","각도기는 기울여요.","이쑤시개는 그림자를 없애요."],"asset":{"type":"passage","lines":["㉮ 수수깡과 실 — 실을 그림자 끝에 맞추고 그림자와 실이 이루는 각을 읽는다.","㉯ 기울이는 각도기 — 태양 빛에 평행하게 기울여 선이 만날 때의 각을 읽는다.","㉰ 이쑤시개 — 막대기 그림자가 보이지 않게 종이를 조절한 때의 각을 읽는다."],"title":"태양 고도 측정기 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#4','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',3,'error','auto','막대기 길이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X04']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"error","stem":"막대기 길이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「막대기를 두 배로 길게 하면 태양 고도도 두 배가 돼.」","correct":true,"mis_target":"SC6-2-u1-X04"},{"t":"소윤 — 「막대기가 길어지면 그림자도 길어져.」","mis":"SC6-2-u1-X04"},{"t":"민재 — 「태양 빛은 지구에 거의 평행하게 들어와.」","mis":"SC6-2-u1-X04"}],"explanation":["막대기와 그림자가 함께 늘어요.","각은 그대로예요.","하준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#5','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',3,'mc','auto','태양 고도 측정기를 만들 때 고려할 점으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"mc","stem":"태양 고도 측정기를 만들 때 고려할 점으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"되도록 크고 무겁게 만든다","correct":true},{"t":"태양 고도를 쉽고 정확하게 잴 수 있게 만든다","mis":"SC6-2-u1-X05"},{"t":"각도기를 사용해 측정 원리를 적용한다","mis":"SC6-2-u1-X05"},{"t":"간편하게 잴 수 있게 만든다","mis":"SC6-2-u1-X05"}],"explanation":["쉽고 정확해야 해요.","간편해야 해요.","크고 무거울 필요는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#6','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',3,'ox','auto','태양 고도 측정기는 한 가지 모양으로만 만들 수 있어요.',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"ox","stem":"태양 고도 측정기는 한 가지 모양으로만 만들 수 있어요.","answer":"X","reason_options":[{"t":"측정 원리를 적용하면 여러 가지 모양으로 만들 수 있고 재는 방법도 다양하기 때문에","correct":true},{"t":"각도기는 한 가지 방법으로만 쓸 수 있기 때문에","mis":"SC6-2-u1-X05"}],"mis":"SC6-2-u1-X05","explanation":["세 가지 측정기를 봤어요.","모양이 서로 달라요.","여러 가지로 만들어요."],"asset":{"type":"passage","lines":["㉮ 수수깡과 실 — 실을 그림자 끝에 맞추고 그림자와 실이 이루는 각을 읽는다.","㉯ 기울이는 각도기 — 태양 빛에 평행하게 기울여 선이 만날 때의 각을 읽는다.","㉰ 이쑤시개 — 막대기 그림자가 보이지 않게 종이를 조절한 때의 각을 읽는다."],"title":"태양 고도 측정기 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#7','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',3,'mc','auto','이쑤시개를 이용한 측정기에서 각을 읽는 때는 언제인가요?',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"mc","stem":"이쑤시개를 이용한 측정기에서 각을 읽는 때는 언제인가요?","options":[{"t":"이쑤시개 그림자가 보이지 않도록 종이를 조절했을 때","correct":true},{"t":"그림자가 가장 길게 생겼을 때","mis":"SC6-2-u1-X05"},{"t":"이쑤시개를 뽑았을 때","mis":"SC6-2-u1-X05"},{"t":"태양을 직접 바라보았을 때","mis":"SC6-2-u1-X05"}],"explanation":["㉰를 읽어요.","그림자를 없애요.","그때 각을 읽어요."],"asset":{"type":"passage","lines":["㉮ 수수깡과 실 — 실을 그림자 끝에 맞추고 그림자와 실이 이루는 각을 읽는다.","㉯ 기울이는 각도기 — 태양 빛에 평행하게 기울여 선이 만날 때의 각을 읽는다.","㉰ 이쑤시개 — 막대기 그림자가 보이지 않게 종이를 조절한 때의 각을 읽는다."],"title":"태양 고도 측정기 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#8','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',4,'mc','auto','「태양 빛은 지구에 거의 평행하게 들어온다」는 사실로 설명할 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u1-X04','SC6-2-u1-X03']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C2","difficulty":4,"kind":"mc","stem":"「태양 빛은 지구에 거의 평행하게 들어온다」는 사실로 설명할 수 있는 것은 어느 것인가요?","options":[{"t":"막대기의 길이가 달라져도 태양 고도는 같게 측정된다","correct":true},{"t":"막대기가 길수록 태양 고도가 높게 측정된다","mis":"SC6-2-u1-X04"},{"t":"태양 고도는 막대기로 잴 수 없다","mis":"SC6-2-u1-X03"},{"t":"그림자 길이는 막대기 길이와 상관없다","mis":"SC6-2-u1-X04"}],"explanation":["빛이 나란히 와요.","막대기와 그림자가 함께 늘어요.","각은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#9','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',4,'mc','auto','태양 고도와 측정기를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X03','SC6-2-u1-X04','SC6-2-u1-X05']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C2","difficulty":4,"kind":"mc","stem":"태양 고도와 측정기를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"태양 고도는 태양이 지표면과 이루는 각이고, 각도기를 쓴 측정기를 여러 모양으로 만들어 다양한 방법으로 잴 수 있다","correct":true},{"t":"태양 고도는 태양까지의 거리이고 자로 잰다","mis":"SC6-2-u1-X03"},{"t":"측정기는 한 가지 모양뿐이고 막대기가 길수록 정확하다","mis":"SC6-2-u1-X04"},{"t":"측정기는 한 번 쓰고 바로 버린다","mis":"SC6-2-u1-X05"}],"explanation":["태양 고도의 뜻이에요.","측정기는 여러 가지예요.","재는 방법도 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L02_challenge#10','sci',6,2,'u1','L02','g6_2_sci_u1_L02_challenge','lesson_challenge','SC6-2-u1-C2',4,'essay','teacher','수수깡과 실을 이용한 태양 고도 측정기를 만드는 순서를 쓰고, 이 측정기로 태양 고도를 재는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C2","difficulty":4,"kind":"essay","stem":"수수깡과 실을 이용한 태양 고도 측정기를 만드는 순서를 쓰고, 이 측정기로 태양 고도를 재는 방법을 쓰세요.","answer_guide":{"answer":"예: 우드록 한쪽에 양면테이프로 자를 붙인다. 수수깡을 10 cm 정도 잘라 자의 0 위치에 수직이 되도록 꽂는다. 수수깡 끝에 실을 묶고 실의 다른 쪽 끝을 구멍 뚫린 각도기 가운데에 끼운다. 태양 빛이 잘 드는 곳에서 실을 수수깡 그림자 끝에 맞추고 그림자와 실이 이루는 각을 읽으면 태양 고도이다.","scoring_points":["자·수수깡·실·각도기를 쓰는 순서를 썼는가","수수깡을 수직으로 꽂는다는 점을 썼는가","실을 그림자 끝에 맞추어 각을 읽는 방법을 썼는가"]},"explanation":["자 → 수수깡 → 실 → 각도기예요.","수직으로 꽂아요.","그림자와 실이 이루는 각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_basic#1','sci',6,2,'u1','L03','g6_2_sci_u1_L03_basic','lesson_basic','SC6-2-u1-C4',1,'mc','auto','태양의 남중 고도는 무엇인가요?',ARRAY['SC6-2-u1-X10','SC6-2-u1-X09']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C4","difficulty":1,"kind":"mc","stem":"태양의 남중 고도는 무엇인가요?","options":[{"t":"태양이 정남쪽에 위치할 때의 태양 고도","correct":true},{"t":"태양이 막 떠오르는 순간의 태양 고도","mis":"SC6-2-u1-X10"},{"t":"태양이 막 지는 순간의 태양 고도","mis":"SC6-2-u1-X10"},{"t":"하루 중 기온이 가장 높을 때의 태양 고도","mis":"SC6-2-u1-X09"}],"explanation":["남쪽과 관계있어요.","정남쪽에 온 때예요.","그때의 태양 고도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_basic#2','sci',6,2,'u1','L03','g6_2_sci_u1_L03_basic','lesson_basic','SC6-2-u1-C3',1,'mc','auto','하루 동안 태양 고도가 높아지면 그림자 길이는 어떻게 되나요?',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C3","difficulty":1,"kind":"mc","stem":"하루 동안 태양 고도가 높아지면 그림자 길이는 어떻게 되나요?","options":[{"t":"짧아진다","correct":true},{"t":"길어진다","mis":"SC6-2-u1-X07"},{"t":"그대로이다","mis":"SC6-2-u1-X07"},{"t":"그림자가 생기지 않는다","mis":"SC6-2-u1-X07"}],"explanation":["태양이 높이 떠요.","그림자가 발밑으로 줄어요.","짧아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_basic#3','sci',6,2,'u1','L03','g6_2_sci_u1_L03_basic','lesson_basic','SC6-2-u1-C3',1,'ox','auto','하루 동안 태양 고도가 높아지면 기온도 대체로 높아져요.',ARRAY['SC6-2-u1-X08']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C3","difficulty":1,"kind":"ox","stem":"하루 동안 태양 고도가 높아지면 기온도 대체로 높아져요.","answer":"O","reason_options":[{"t":"태양 고도 그래프와 기온 그래프가 비슷한 모양으로 함께 오르기 때문에","correct":true},{"t":"태양 고도와 기온은 아무 관계가 없기 때문에","mis":"SC6-2-u1-X08"}],"mis":"SC6-2-u1-X08","explanation":["두 그래프를 떠올려요.","함께 올라가요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_basic#4','sci',6,2,'u1','L03','g6_2_sci_u1_L03_basic','lesson_basic','SC6-2-u1-C4',1,'sa','auto','태양이 정남쪽에 위치하는 것을 「태양이 □□했다」고 해요. □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u1-C4","difficulty":1,"kind":"sa","stem":"태양이 정남쪽에 위치하는 것을 「태양이 □□했다」고 해요. □□에 알맞은 말을 쓰세요.","answer":["남중"],"explanation":["남쪽 하늘 한가운데예요.","두 글자예요.","남중이에요."],"mis":"SC6-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_basic#5','sci',6,2,'u1','L03','g6_2_sci_u1_L03_basic','lesson_basic','SC6-2-u1-C3',2,'mc','auto','하루 동안 잰 기록에서 태양 고도가 가장 높은 시각은 언제인가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X06']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C3","difficulty":2,"kind":"mc","stem":"하루 동안 잰 기록에서 태양 고도가 가장 높은 시각은 언제인가요?","options":[{"t":"12시 30분","correct":true},{"t":"14시 30분","mis":"SC6-2-u1-X09"},{"t":"9시 30분","mis":"SC6-2-u1-X06"},{"t":"15시 30분","mis":"SC6-2-u1-X06"}],"explanation":["태양 고도 줄을 읽어요.","가장 큰 수를 찾아요.","51.7°인 12시 30분이에요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 34.5 · 43.5 · 49.7 · 51.7 · 48.3 · 42.2 · 32.8","그림자 길이(cm) — 14.5 · 10.5 · 8.5 · 7.9 · 8.9 · 11.0 · 15.5","기온(°C) — 21.1 · 23.0 · 24.8 · 26.1 · 26.8 · 27.0 · 26.9"],"title":"하루 동안 잰 기록(막대기 10 cm, 실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
