INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_basic#7','sci',6,2,'u1','L03','g6_2_sci_u1_L03_basic','lesson_basic','SC6-2-u1-C5',2,'mc','auto','하루 동안 기온은 어디에서 재나요?',ARRAY['SC6-2-u1-X12']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C5","difficulty":2,"kind":"mc","stem":"하루 동안 기온은 어디에서 재나요?","options":[{"t":"그늘지고 지표면에서 1.5 m 정도 높이인 곳","correct":true},{"t":"햇빛이 쨍쨍한 땅바닥","mis":"SC6-2-u1-X12"},{"t":"창문을 닫은 교실 안","mis":"SC6-2-u1-X12"},{"t":"온도계를 태양 쪽으로 높이 든 곳","mis":"SC6-2-u1-X12"}],"explanation":["직사광선을 피해요.","땅에서 조금 떨어져요.","그늘 1.5 m 높이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
