INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_basic#9','sci',6,2,'u1','L03','g6_2_sci_u1_L03_basic','lesson_basic','SC6-2-u1-C5',2,'error','auto','하루 동안 측정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X12']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C5","difficulty":2,"kind":"error","stem":"하루 동안 측정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「태양을 똑바로 바라보면서 높이를 확인하자.」","correct":true,"mis_target":"SC6-2-u1-X12"},{"t":"지민 — 「태양 빛을 가리는 모자를 쓰자.」","mis":"SC6-2-u1-X12"},{"t":"라온 — 「측정기는 평평한 곳에 놓자.」","mis":"SC6-2-u1-X12"}],"explanation":["태양 빛에 눈을 다칠 수 있어요.","직접 보지 않아요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
