INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#3','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C3',3,'mc','auto','하루 동안 잰 기록에서 9시 30분부터 12시 30분까지의 변화를 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X07','SC6-2-u1-X08','SC6-2-u1-X06']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C3","difficulty":3,"kind":"mc","stem":"하루 동안 잰 기록에서 9시 30분부터 12시 30분까지의 변화를 바르게 말한 것은 어느 것인가요?","options":[{"t":"태양 고도는 높아지고, 그림자 길이는 짧아지고, 기온은 높아진다","correct":true},{"t":"태양 고도는 높아지고, 그림자 길이도 길어진다","mis":"SC6-2-u1-X07"},{"t":"태양 고도는 높아지고, 기온은 낮아진다","mis":"SC6-2-u1-X08"},{"t":"세 가지 모두 그대로이다","mis":"SC6-2-u1-X06"}],"explanation":["세 줄을 차례로 읽어요.","그림자는 반대로 가요.","기온은 함께 올라요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 34.5 · 43.5 · 49.7 · 51.7 · 48.3 · 42.2 · 32.8","그림자 길이(cm) — 14.5 · 10.5 · 8.5 · 7.9 · 8.9 · 11.0 · 15.5","기온(°C) — 21.1 · 23.0 · 24.8 · 26.1 · 26.8 · 27.0 · 26.9"],"title":"하루 동안 잰 기록(막대기 10 cm, 실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#4','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C3',3,'ox','auto','하루 중 태양 고도가 가장 높을 때 기온도 가장 높아요.',ARRAY['SC6-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C3","difficulty":3,"kind":"ox","stem":"하루 중 태양 고도가 가장 높을 때 기온도 가장 높아요.","answer":"X","reason_options":[{"t":"기온이 가장 높은 시각은 태양 고도가 가장 높은 시각보다 늦어 두 시각에 차이가 있기 때문에","correct":true},{"t":"태양 고도가 가장 높으면 곧바로 가장 따뜻해지기 때문에","mis":"SC6-2-u1-X09"}],"mis":"SC6-2-u1-X09","explanation":["두 꼭짓점을 견줘요.","기온 꼭짓점이 뒤에 있어요.","같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#5','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C4',3,'mc','auto','오늘과 똑같은 시각에 내일도 같은 곳에서 태양 고도를 재면 어떻게 될까요?',ARRAY['SC6-2-u1-X11']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C4","difficulty":3,"kind":"mc","stem":"오늘과 똑같은 시각에 내일도 같은 곳에서 태양 고도를 재면 어떻게 될까요?","options":[{"t":"날마다 조금씩 다른 값이 나온다","correct":true},{"t":"어제도 오늘도 내일도 똑같은 값이 나온다","mis":"SC6-2-u1-X11"},{"t":"잴 때마다 전혀 다른 값이 나와 규칙이 없다","mis":"SC6-2-u1-X11"},{"t":"그림자 길이만 달라지고 태양 고도는 그대로이다","mis":"SC6-2-u1-X11"}],"explanation":["태양이 뜨고 지는 시각을 생각해요.","매일 조금씩 달라져요.","값도 조금씩 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#6','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C5',3,'error','auto','꺾은선그래프를 그리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X12']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C5","difficulty":3,"kind":"error","stem":"꺾은선그래프를 그리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「그래프마다 가로축의 측정 시각을 다르게 쓰자.」","correct":true,"mis_target":"SC6-2-u1-X12"},{"t":"수아 — 「가로축에 측정 시각을 일정한 간격으로 쓰자.」","mis":"SC6-2-u1-X12"},{"t":"이준 — 「세 그래프는 다른 색으로 그리자.」","mis":"SC6-2-u1-X12"}],"explanation":["세 그래프를 겹쳐 견줘요.","가로축이 같아야 해요.","도윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#7','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C3',3,'mc','auto','그림자밟기 놀이에서 그림자를 밟기 가장 어려운 때는 언제인가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X07']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C3","difficulty":3,"kind":"mc","stem":"그림자밟기 놀이에서 그림자를 밟기 가장 어려운 때는 언제인가요?","options":[{"t":"태양이 남중하는 12시 30분 무렵","correct":true},{"t":"기온이 가장 높은 14시 30분 무렵","mis":"SC6-2-u1-X09"},{"t":"해가 막 떠오른 이른 아침","mis":"SC6-2-u1-X07"},{"t":"해가 지기 직전의 늦은 오후","mis":"SC6-2-u1-X07"}],"explanation":["그림자가 가장 짧은 때예요.","태양 고도가 가장 높아요.","남중할 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#8','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C3',4,'mc','auto','하루 동안 잰 기록을 세 꺾은선그래프로 나타내 겹쳤어요. 가장 알맞은 결론은 어느 것인가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X07','SC6-2-u1-X08']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C3","difficulty":4,"kind":"mc","stem":"하루 동안 잰 기록을 세 꺾은선그래프로 나타내 겹쳤어요. 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"태양 고도와 기온 그래프는 모양이 비슷하지만 가장 높은 시각에 차이가 있고, 그림자 길이 그래프는 반대 모양이다","correct":true},{"t":"세 그래프는 모두 같은 시각에 가장 높다","mis":"SC6-2-u1-X09"},{"t":"태양 고도 그래프와 그림자 길이 그래프의 모양이 같다","mis":"SC6-2-u1-X07"},{"t":"기온 그래프는 하루 내내 계속 올라가기만 한다","mis":"SC6-2-u1-X08"}],"explanation":["태양 고도와 기온은 닮았어요.","그림자는 거꾸로예요.","꼭짓점 시각을 봐요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 34.5 · 43.5 · 49.7 · 51.7 · 48.3 · 42.2 · 32.8","그림자 길이(cm) — 14.5 · 10.5 · 8.5 · 7.9 · 8.9 · 11.0 · 15.5","기온(°C) — 21.1 · 23.0 · 24.8 · 26.1 · 26.8 · 27.0 · 26.9"],"title":"하루 동안 잰 기록(막대기 10 cm, 실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#9','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C4',4,'mc','auto','매일 같은 시각에 재어도 태양 고도가 조금씩 다른 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X11','SC6-2-u1-X07']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C4","difficulty":4,"kind":"mc","stem":"매일 같은 시각에 재어도 태양 고도가 조금씩 다른 까닭은 무엇인가요?","options":[{"t":"태양이 뜨고 지는 시각과 태양의 남중 고도가 매일 조금씩 달라지기 때문에","correct":true},{"t":"측정기가 매일 조금씩 고장 나기 때문에","mis":"SC6-2-u1-X11"},{"t":"태양 고도는 아무 규칙 없이 바뀌기 때문에","mis":"SC6-2-u1-X11"},{"t":"그림자 길이는 바뀌지 않기 때문에","mis":"SC6-2-u1-X07"}],"explanation":["태양이 뜨고 지는 시각이요.","남중 고도도요.","매일 조금씩 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L03_challenge#10','sci',6,2,'u1','L03','g6_2_sci_u1_L03_challenge','lesson_challenge','SC6-2-u1-C3',4,'essay','teacher','하루 동안 잰 기록을 보고 하루 동안 태양 고도·그림자 길이·기온이 어떻게 달라지는지 쓰고, 태양 고도와 나머지 둘의 관계를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C3","difficulty":4,"kind":"essay","stem":"하루 동안 잰 기록을 보고 하루 동안 태양 고도·그림자 길이·기온이 어떻게 달라지는지 쓰고, 태양 고도와 나머지 둘의 관계를 쓰세요.","answer_guide":{"answer":"예: 태양 고도는 12시 30분까지 높아졌다가 다시 낮아진다. 그림자 길이는 12시 30분까지 짧아졌다가 다시 길어진다. 기온은 점점 높아져 14시 30분 무렵에 가장 높고 그 뒤 조금 낮아진다. 태양 고도가 높아지면 그림자 길이는 짧아지고 기온은 높아지지만, 태양 고도가 가장 높은 시각과 기온이 가장 높은 시각에는 차이가 있다.","scoring_points":["세 가지의 하루 변화를 썼는가","태양 고도와 그림자 길이의 관계를 썼는가","태양 고도와 기온의 관계와 두 시각의 차이를 썼는가"]},"explanation":["세 줄을 읽어요.","그림자는 반대예요.","기온은 늦게 가장 높아요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 34.5 · 43.5 · 49.7 · 51.7 · 48.3 · 42.2 · 32.8","그림자 길이(cm) — 14.5 · 10.5 · 8.5 · 7.9 · 8.9 · 11.0 · 15.5","기온(°C) — 21.1 · 23.0 · 24.8 · 26.1 · 26.8 · 27.0 · 26.9"],"title":"하루 동안 잰 기록(막대기 10 cm, 실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_basic#1','sci',6,2,'u1','L04','g6_2_sci_u1_L04_basic','lesson_basic','SC6-2-u1-C6',1,'mc','auto','태양의 남중 고도가 가장 높은 계절은 언제인가요?',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C6","difficulty":1,"kind":"mc","stem":"태양의 남중 고도가 가장 높은 계절은 언제인가요?","options":[{"t":"여름","correct":true},{"t":"겨울","mis":"SC6-2-u1-X13"},{"t":"봄","mis":"SC6-2-u1-X13"},{"t":"가을","mis":"SC6-2-u1-X13"}],"explanation":["태양이 가장 높이 뜨는 때예요.","더운 계절이에요.","여름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
