INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_basic#3','sci',6,2,'u1','L04','g6_2_sci_u1_L04_basic','lesson_basic','SC6-2-u1-C6',1,'sa','auto','태양이 지평선 위로 떠 있는 시간을 무엇이라고 하나요?','{}'::text[],false,'{"seq":3,"concept":"SC6-2-u1-C6","difficulty":1,"kind":"sa","stem":"태양이 지평선 위로 떠 있는 시간을 무엇이라고 하나요?","answer":["낮의 길이","낮의길이"],"explanation":["해가 떠 있는 동안이에요.","계절마다 달라요.","낮의 길이예요."],"mis":"SC6-2-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_basic#4','sci',6,2,'u1','L04','g6_2_sci_u1_L04_basic','lesson_basic','SC6-2-u1-C6',1,'ox','auto','태양의 남중 고도가 높아질수록 낮의 길이가 길어져요.',ARRAY['SC6-2-u1-X14']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C6","difficulty":1,"kind":"ox","stem":"태양의 남중 고도가 높아질수록 낮의 길이가 길어져요.","answer":"O","reason_options":[{"t":"남중 고도가 높아질수록 태양이 지평선 위로 떠 있는 시간이 길어지기 때문에","correct":true},{"t":"남중 고도가 높으면 태양이 빨리 지기 때문에","mis":"SC6-2-u1-X14"}],"mis":"SC6-2-u1-X14","explanation":["두 그래프를 떠올려요.","함께 올라가요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_basic#5','sci',6,2,'u1','L04','g6_2_sci_u1_L04_basic','lesson_basic','SC6-2-u1-C6',2,'mc','auto','조사 기록에서 태양의 남중 고도가 가장 높은 날은 언제인가요?',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C6","difficulty":2,"kind":"mc","stem":"조사 기록에서 태양의 남중 고도가 가장 높은 날은 언제인가요?","options":[{"t":"6월 21일","correct":true},{"t":"12월 21일","mis":"SC6-2-u1-X13"},{"t":"3월 21일","mis":"SC6-2-u1-X13"},{"t":"9월 21일","mis":"SC6-2-u1-X13"}],"explanation":["남중 고도를 견줘요.","가장 큰 수예요.","75.52°인 6월이에요."],"asset":{"type":"passage","lines":["3월 21일 — 남중 고도 52.47° · 낮의 길이 12시간 10분","6월 21일 — 남중 고도 75.52° · 낮의 길이 14시간 45분","9월 21일 — 남중 고도 52.58° · 낮의 길이 12시간 12분","12월 21일 — 남중 고도 29.00° · 낮의 길이 9시간 33분"],"title":"서울특별시 2024년 조사 기록 일부(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
