INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_basic#7','sci',6,2,'u1','L04','g6_2_sci_u1_L04_basic','lesson_basic','SC6-2-u1-C6',2,'match','auto','계절과 태양의 남중 고도·낮의 길이를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u1-C6","difficulty":2,"kind":"match","stem":"계절과 태양의 남중 고도·낮의 길이를 알맞게 이으세요.","pairs":[{"l":"여름","r":"남중 고도가 가장 높고 낮이 가장 길다"},{"l":"겨울","r":"남중 고도가 가장 낮고 낮이 가장 짧다"},{"l":"봄과 가을","r":"여름과 겨울의 중간 정도이다"}],"mis":"SC6-2-u1-X13","explanation":["여름은 높고 길어요.","겨울은 낮고 짧아요.","봄과 가을은 그 사이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_basic#8','sci',6,2,'u1','L04','g6_2_sci_u1_L04_basic','lesson_basic','SC6-2-u1-C6',2,'error','auto','계절별 태양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C6","difficulty":2,"kind":"error","stem":"계절별 태양을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유진 — 「겨울에는 태양의 남중 고도가 높아서 낮이 짧아.」","correct":true,"mis_target":"SC6-2-u1-X13"},{"t":"태린 — 「여름에는 낮의 길이가 가장 길어.」","mis":"SC6-2-u1-X13"},{"t":"시온 — 「봄과 가을은 여름과 겨울의 중간 정도야.」","mis":"SC6-2-u1-X13"}],"explanation":["겨울엔 태양이 낮게 떠요.","그래서 낮도 짧아요.","유진이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
