INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_challenge#5','sci',6,2,'u1','L04','g6_2_sci_u1_L04_challenge','lesson_challenge','SC6-2-u1-C6',3,'error','auto','두 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X14','SC6-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C6","difficulty":3,"kind":"error","stem":"두 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「남중 고도가 가장 높은 달과 낮이 가장 긴 달은 서로 달라.」","correct":true,"mis_target":"SC6-2-u1-X14"},{"t":"로아 — 「두 그래프는 모양이 서로 비슷해.」","mis":"SC6-2-u1-X14"},{"t":"한결 — 「12월에 남중 고도가 가장 낮아.」","mis":"SC6-2-u1-X13"}],"explanation":["두 꼭짓점을 견줘요.","모두 6월이에요.","가온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_challenge#6','sci',6,2,'u1','L04','g6_2_sci_u1_L04_challenge','lesson_challenge','SC6-2-u1-C6',3,'mc','auto','계절별 태양의 남중 고도와 낮의 길이를 조사할 때 바른 행동은 어느 것인가요?',ARRAY['SC6-2-u1-X16']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C6","difficulty":3,"kind":"mc","stem":"계절별 태양의 남중 고도와 낮의 길이를 조사할 때 바른 행동은 어느 것인가요?","options":[{"t":"자신이 사는 지역을 중심으로 조사하고 조사한 지역과 연도를 적어 둔다","correct":true},{"t":"정해진 주제가 아닌 것까지 함께 찾아본다","mis":"SC6-2-u1-X16"},{"t":"조사한 지역과 연도는 적지 않고 넘어간다","mis":"SC6-2-u1-X16"},{"t":"지역마다 값이 같으니 아무 지역이나 섞어 쓴다","mis":"SC6-2-u1-X16"}],"explanation":["필요한 정보만 찾아요.","지역이 중요해요.","지역과 연도를 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_challenge#7','sci',6,2,'u1','L04','g6_2_sci_u1_L04_challenge','lesson_challenge','SC6-2-u1-C6',3,'mc','auto','태양의 남중 고도 그래프와 모양이 가장 비슷한 그래프는 어느 것인가요?',ARRAY['SC6-2-u1-X07','SC6-2-u1-X14']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C6","difficulty":3,"kind":"mc","stem":"태양의 남중 고도 그래프와 모양이 가장 비슷한 그래프는 어느 것인가요?","options":[{"t":"계절별 낮의 길이 그래프","correct":true},{"t":"계절별 같은 시각의 그림자 길이 그래프","mis":"SC6-2-u1-X07"},{"t":"모양이 비슷한 그래프는 없다","mis":"SC6-2-u1-X14"},{"t":"어느 그래프나 모양이 똑같다","mis":"SC6-2-u1-X14"}],"explanation":["함께 오르내리는 것을 찾아요.","그림자는 반대로 가요.","낮의 길이 그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_challenge#8','sci',6,2,'u1','L04','g6_2_sci_u1_L04_challenge','lesson_challenge','SC6-2-u1-C6',4,'mc','auto','계절별 태양의 남중 고도와 낮의 길이를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X13','SC6-2-u1-X14','SC6-2-u1-X15']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C6","difficulty":4,"kind":"mc","stem":"계절별 태양의 남중 고도와 낮의 길이를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"여름에 남중 고도가 가장 높고 낮이 가장 길며, 남중 고도가 높아질수록 낮의 길이가 연속적으로 길어진다","correct":true},{"t":"겨울에 남중 고도가 가장 높고 낮이 가장 길다","mis":"SC6-2-u1-X13"},{"t":"남중 고도와 낮의 길이는 서로 관계가 없다","mis":"SC6-2-u1-X14"},{"t":"낮의 길이는 달이 바뀔 때만 한 번씩 달라진다","mis":"SC6-2-u1-X15"}],"explanation":["여름과 겨울을 견줘요.","두 가지가 함께 움직여요.","이어서 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_challenge#9','sci',6,2,'u1','L04','g6_2_sci_u1_L04_challenge','lesson_challenge','SC6-2-u1-C6',4,'mc','auto','어느 지역을 조사했더니 남중 고도가 가장 높은 달이 6월이었어요. 이 지역에서 낮의 길이가 가장 긴 달은 언제쯤일까요?',ARRAY['SC6-2-u1-X14']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C6","difficulty":4,"kind":"mc","stem":"어느 지역을 조사했더니 남중 고도가 가장 높은 달이 6월이었어요. 이 지역에서 낮의 길이가 가장 긴 달은 언제쯤일까요?","options":[{"t":"6월 무렵","correct":true},{"t":"12월 무렵","mis":"SC6-2-u1-X14"},{"t":"3월 무렵","mis":"SC6-2-u1-X14"},{"t":"알 수 없다","mis":"SC6-2-u1-X14"}],"explanation":["두 그래프는 꼭짓점이 겹쳐요.","남중 고도가 높으면 낮이 길어요.","같은 6월 무렵이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L04_challenge#10','sci',6,2,'u1','L04','g6_2_sci_u1_L04_challenge','lesson_challenge','SC6-2-u1-C6',4,'essay','teacher','조사 기록을 보고 계절에 따라 태양의 남중 고도와 낮의 길이가 어떻게 달라지는지 쓰고, 두 가지의 관계를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C6","difficulty":4,"kind":"essay","stem":"조사 기록을 보고 계절에 따라 태양의 남중 고도와 낮의 길이가 어떻게 달라지는지 쓰고, 두 가지의 관계를 쓰세요.","answer_guide":{"answer":"예: 6월 21일에 태양의 남중 고도가 75.52°로 가장 높고 낮의 길이도 14시간 45분으로 가장 길다. 12월 21일에는 남중 고도가 29.00°로 가장 낮고 낮의 길이도 9시간 33분으로 가장 짧다. 3월과 9월은 그 중간 정도이다. 태양의 남중 고도가 높아질수록 태양이 지평선 위로 떠 있는 시간이 길어져 낮의 길이가 길어진다.","scoring_points":["여름(6월)의 남중 고도·낮의 길이를 썼는가","겨울(12월)의 남중 고도·낮의 길이를 썼는가","남중 고도가 높아질수록 낮이 길어진다는 관계를 썼는가"]},"explanation":["6월을 읽어요.","12월을 읽어요.","관계를 한 문장으로 써요."],"asset":{"type":"passage","lines":["3월 21일 — 남중 고도 52.47° · 낮의 길이 12시간 10분","6월 21일 — 남중 고도 75.52° · 낮의 길이 14시간 45분","9월 21일 — 남중 고도 52.58° · 낮의 길이 12시간 12분","12월 21일 — 남중 고도 29.00° · 낮의 길이 9시간 33분"],"title":"서울특별시 2024년 조사 기록 일부(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#1','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',1,'mc','auto','태양 고도가 높아질수록 일정한 면적의 지표면이 받는 태양 에너지양은 어떻게 되나요?',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"mc","stem":"태양 고도가 높아질수록 일정한 면적의 지표면이 받는 태양 에너지양은 어떻게 되나요?","options":[{"t":"많아진다","correct":true},{"t":"적어진다","mis":"SC6-2-u1-X17"},{"t":"달라지지 않는다","mis":"SC6-2-u1-X17"},{"t":"들쭉날쭉해진다","mis":"SC6-2-u1-X17"}],"explanation":["높이 뜬 태양을 떠올려요.","빛이 세게 닿아요.","많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#2','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',1,'match','auto','실험에서 쓴 것과 자연에서 나타내는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"match","stem":"실험에서 쓴 것과 자연에서 나타내는 것을 알맞게 이으세요.","pairs":[{"l":"손전등","r":"태양"},{"l":"스마트 기기","r":"지표면"},{"l":"손전등과 스마트 기기가 이루는 각","r":"태양 고도"},{"l":"센서가 받는 에너지양","r":"태양 에너지양"}],"mis":"SC6-2-u1-X18","explanation":["빛을 내는 것은 태양이에요.","빛을 받는 것은 지표면이에요.","각은 태양 고도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#3','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',1,'ox','auto','손전등을 기울일 때 손전등과 스마트 기기 사이의 거리는 일정하게 해요.',ARRAY['SC6-2-u1-X18']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"ox","stem":"손전등을 기울일 때 손전등과 스마트 기기 사이의 거리는 일정하게 해요.","answer":"O","reason_options":[{"t":"각만 다르게 하고 거리는 같게 해야 각에 따른 빛의 세기를 비교할 수 있기 때문에","correct":true},{"t":"거리도 함께 바꾸어야 비교가 잘 되기 때문에","mis":"SC6-2-u1-X18"}],"mis":"SC6-2-u1-X18","explanation":["하나만 바꿔요.","바꾸는 것은 각이에요.","거리는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#4','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',1,'sa','auto','손전등 실험에서 태양을 나타내는 것은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"sa","stem":"손전등 실험에서 태양을 나타내는 것은 무엇인가요? 세 글자로 쓰세요.","answer":["손전등"],"explanation":["빛을 내는 것이에요.","손에 들고 비춰요.","손전등이에요."],"mis":"SC6-2-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#5','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',2,'mc','auto','실험 기록에서 빛의 세기가 더 센 때는 언제인가요?',ARRAY['SC6-2-u1-X17','SC6-2-u1-X18']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C7","difficulty":2,"kind":"mc","stem":"실험 기록에서 빛의 세기가 더 센 때는 언제인가요?","options":[{"t":"막대 그림자가 짧고 이루는 각이 클 때","correct":true},{"t":"막대 그림자가 길고 이루는 각이 작을 때","mis":"SC6-2-u1-X17"},{"t":"두 때의 빛의 세기가 같을 때","mis":"SC6-2-u1-X17"},{"t":"손전등을 더 멀리 가져갔을 때","mis":"SC6-2-u1-X18"}],"explanation":["두 수를 견줘요.","1,412가 더 커요.","각이 클 때예요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 약 20 cm로 같게 한다.","막대 그림자가 짧을 때 — 이루는 각이 크다 · 빛의 세기 예 1,412","막대 그림자가 길 때 — 이루는 각이 작다 · 빛의 세기 예 986"],"title":"손전등 실험 기록(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#6','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C8',2,'mc','auto','겨울에 추운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X19','SC6-2-u1-X13','SC6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C8","difficulty":2,"kind":"mc","stem":"겨울에 추운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"태양의 남중 고도가 낮아 일정한 면적의 지표면이 받는 태양 에너지양이 적기 때문에","correct":true},{"t":"태양의 남중 고도가 높아 태양 에너지양이 많기 때문에","mis":"SC6-2-u1-X19"},{"t":"낮의 길이가 가장 길기 때문에","mis":"SC6-2-u1-X13"},{"t":"태양 에너지양은 계절마다 늘 같기 때문에","mis":"SC6-2-u1-X17"}],"explanation":["겨울의 남중 고도를 떠올려요.","태양 에너지양이 적어요.","그래서 추워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#7','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',2,'error','auto','실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X18']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C7","difficulty":2,"kind":"error","stem":"실험을 준비하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「교실을 환하게 밝혀야 빛이 잘 재져.」","correct":true,"mis_target":"SC6-2-u1-X18"},{"t":"주원 — 「교실을 어둡게 하자.」","mis":"SC6-2-u1-X18"},{"t":"채아 — 「손전등 빛을 눈에 비추지 말자.」","mis":"SC6-2-u1-X18"}],"explanation":["다른 빛이 섞이면 안 돼요.","교실을 어둡게 해요.","하율이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#8','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',2,'mc','auto','실험할 때 교실을 어둡게 하는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X18']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C7","difficulty":2,"kind":"mc","stem":"실험할 때 교실을 어둡게 하는 까닭은 무엇인가요?","options":[{"t":"주변의 다른 빛이 측정되지 않도록 하기 위해서","correct":true},{"t":"손전등이 더 오래 켜지게 하기 위해서","mis":"SC6-2-u1-X18"},{"t":"스마트 기기 화면이 꺼지지 않게 하기 위해서","mis":"SC6-2-u1-X18"},{"t":"막대 그림자를 없애기 위해서","mis":"SC6-2-u1-X18"}],"explanation":["센서는 모든 빛을 재요.","손전등 빛만 재야 해요.","다른 빛을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#9','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C8',2,'ox','auto','여름에는 태양의 남중 고도가 높아 일정한 면적의 지표면이 받는 태양 에너지양이 많아요.',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C8","difficulty":2,"kind":"ox","stem":"여름에는 태양의 남중 고도가 높아 일정한 면적의 지표면이 받는 태양 에너지양이 많아요.","answer":"O","reason_options":[{"t":"태양 고도가 높을수록 일정한 면적의 지표면이 받는 태양 에너지양이 많아지기 때문에","correct":true},{"t":"태양 고도가 높을수록 태양 에너지양이 적어지기 때문에","mis":"SC6-2-u1-X17"}],"mis":"SC6-2-u1-X17","explanation":["여름에 높이 떠요.","높을수록 많이 받아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_basic#10','sci',6,2,'u1','L05','g6_2_sci_u1_L05_basic','lesson_basic','SC6-2-u1-C7',3,'mc','auto','무대 위 배우가 가장 밝게 보이게 하려면 조명을 어떻게 비춰야 할까요?',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C7","difficulty":3,"kind":"mc","stem":"무대 위 배우가 가장 밝게 보이게 하려면 조명을 어떻게 비춰야 할까요?","options":[{"t":"배우에게 수직으로 비춘다","correct":true},{"t":"바닥과 거의 나란하게 비스듬히 비춘다","mis":"SC6-2-u1-X17"},{"t":"배우 뒤쪽 벽을 비춘다","mis":"SC6-2-u1-X17"},{"t":"조명을 비추는 방향은 상관없다","mis":"SC6-2-u1-X17"}],"explanation":["손전등 실험을 떠올려요.","각이 클수록 세요.","수직으로 비춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
