INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#3','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C7',3,'mc','auto','스마트 기기 센서 가까이에 빨판 달린 막대를 세우는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X18']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C7","difficulty":3,"kind":"mc","stem":"스마트 기기 센서 가까이에 빨판 달린 막대를 세우는 까닭은 무엇인가요?","options":[{"t":"막대 그림자 길이로 손전등의 각도를 알아보기 위해서","correct":true},{"t":"빛의 세기를 막대로 재기 위해서","mis":"SC6-2-u1-X18"},{"t":"손전등을 받쳐 두기 위해서","mis":"SC6-2-u1-X18"},{"t":"손전등까지의 거리를 재기 위해서","mis":"SC6-2-u1-X18"}],"explanation":["그림자가 짧고 긴 때를 봐요.","각을 그림자로 알아봐요.","각도를 보려는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#4','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C7',3,'error','auto','손전등 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X18','SC6-2-u1-X17']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C7","difficulty":3,"kind":"error","stem":"손전등 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「손전등을 더 가까이 가져갈수록 각이 커져.」","correct":true,"mis_target":"SC6-2-u1-X18"},{"t":"다은 — 「거리는 그대로 두고 각만 바꿔.」","mis":"SC6-2-u1-X18"},{"t":"지안 — 「각이 클수록 빛의 세기가 세.」","mis":"SC6-2-u1-X17"}],"explanation":["거리와 각은 달라요.","거리는 바꾸지 않아요.","서준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#5','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C8',3,'mc','auto','여름에 덥고 겨울에 추운 까닭을 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X19','SC6-2-u1-X17']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C8","difficulty":3,"kind":"mc","stem":"여름에 덥고 겨울에 추운 까닭을 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"여름에는 남중 고도가 높아 태양 에너지양이 많고, 겨울에는 남중 고도가 낮아 태양 에너지양이 적기 때문에","correct":true},{"t":"여름에는 남중 고도가 낮아 태양 에너지양이 많기 때문에","mis":"SC6-2-u1-X19"},{"t":"계절이 달라져도 지표면이 받는 태양 에너지양은 같기 때문에","mis":"SC6-2-u1-X17"},{"t":"남중 고도와 태양 에너지양은 아무 관계가 없기 때문에","mis":"SC6-2-u1-X19"}],"explanation":["남중 고도부터 봐요.","태양 에너지양으로 이어요.","기온으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#6','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C7',3,'ox','auto','막대 그림자 길이가 길 때 빛의 세기가 더 세요.',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C7","difficulty":3,"kind":"ox","stem":"막대 그림자 길이가 길 때 빛의 세기가 더 세요.","answer":"X","reason_options":[{"t":"그림자가 길 때는 이루는 각이 작아 빛의 세기가 더 약하기 때문에","correct":true},{"t":"그림자가 길수록 빛이 많이 모이기 때문에","mis":"SC6-2-u1-X17"}],"mis":"SC6-2-u1-X17","explanation":["986과 1,412를 견줘요.","그림자가 길면 각이 작아요.","빛이 약해요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 약 20 cm로 같게 한다.","막대 그림자가 짧을 때 — 이루는 각이 크다 · 빛의 세기 예 1,412","막대 그림자가 길 때 — 이루는 각이 작다 · 빛의 세기 예 986"],"title":"손전등 실험 기록(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#7','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C7',3,'mc','auto','실험 기록을 태양으로 옮겨 생각한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X17','SC6-2-u1-X18']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C7","difficulty":3,"kind":"mc","stem":"실험 기록을 태양으로 옮겨 생각한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"태양 고도가 높을수록 일정한 면적의 지표면이 받는 태양 에너지양이 많다","correct":true},{"t":"태양 고도가 낮을수록 태양 에너지양이 많다","mis":"SC6-2-u1-X17"},{"t":"태양까지의 거리가 가까울수록 태양 에너지양이 많다","mis":"SC6-2-u1-X18"},{"t":"태양 고도와 태양 에너지양은 관계가 없다","mis":"SC6-2-u1-X17"}],"explanation":["각은 태양 고도예요.","각이 클 때 빛이 셌어요.","높을수록 많이 받아요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 약 20 cm로 같게 한다.","막대 그림자가 짧을 때 — 이루는 각이 크다 · 빛의 세기 예 1,412","막대 그림자가 길 때 — 이루는 각이 작다 · 빛의 세기 예 986"],"title":"손전등 실험 기록(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#8','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C7',4,'mc','auto','같은 날 같은 곳에서 9시 30분 무렵과 12시 30분 무렵 가운데 일정한 면적의 지표면이 받는 태양 에너지양이 더 많은 때와 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X17','SC6-2-u1-X09']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C7","difficulty":4,"kind":"mc","stem":"같은 날 같은 곳에서 9시 30분 무렵과 12시 30분 무렵 가운데 일정한 면적의 지표면이 받는 태양 에너지양이 더 많은 때와 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"12시 30분 무렵 — 태양 고도가 더 높기 때문에","correct":true},{"t":"9시 30분 무렵 — 아침 햇빛이 더 세기 때문에","mis":"SC6-2-u1-X17"},{"t":"두 때가 같다 — 같은 날이기 때문에","mis":"SC6-2-u1-X17"},{"t":"14시 30분 무렵 — 기온이 가장 높기 때문에","mis":"SC6-2-u1-X09"}],"explanation":["두 때의 태양 고도를 견줘요.","12시 30분에 가장 높아요.","그때 많이 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#9','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C7',4,'mc','auto','손전등 실험에서 같게 할 조건과 다르게 할 조건을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X18']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C7","difficulty":4,"kind":"mc","stem":"손전등 실험에서 같게 할 조건과 다르게 할 조건을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"같게 — 손전등과 스마트 기기 사이의 거리 / 다르게 — 손전등과 스마트 기기가 이루는 각","correct":true},{"t":"같게 — 이루는 각 / 다르게 — 거리","mis":"SC6-2-u1-X18"},{"t":"같게 — 아무것도 없음 / 다르게 — 거리와 각 모두","mis":"SC6-2-u1-X18"},{"t":"같게 — 거리와 각 모두 / 다르게 — 아무것도 없음","mis":"SC6-2-u1-X18"}],"explanation":["알아보려는 것을 생각해요.","각에 따른 빛의 세기예요.","각만 다르게 해요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 약 20 cm로 같게 한다.","막대 그림자가 짧을 때 — 이루는 각이 크다 · 빛의 세기 예 1,412","막대 그림자가 길 때 — 이루는 각이 작다 · 빛의 세기 예 986"],"title":"손전등 실험 기록(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L05_challenge#10','sci',6,2,'u1','L05','g6_2_sci_u1_L05_challenge','lesson_challenge','SC6-2-u1-C8',4,'essay','teacher','실험 기록을 바탕으로 태양 고도와 태양 에너지양의 관계를 쓰고, 이것으로 여름에 덥고 겨울에 추운 까닭을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C8","difficulty":4,"kind":"essay","stem":"실험 기록을 바탕으로 태양 고도와 태양 에너지양의 관계를 쓰고, 이것으로 여름에 덥고 겨울에 추운 까닭을 설명하세요.","answer_guide":{"answer":"예: 손전등과 스마트 기기가 이루는 각이 클 때는 빛의 세기가 예 1,412로 세고, 각이 작을 때는 예 986으로 약했다. 손전등은 태양, 각은 태양 고도이므로 태양 고도가 높을수록 일정한 면적의 지표면이 받는 태양 에너지양이 많다. 여름에는 태양의 남중 고도가 높아 태양 에너지양이 많아 덥고, 겨울에는 남중 고도가 낮아 태양 에너지양이 적어 춥다.","scoring_points":["실험 결과(각과 빛의 세기)를 썼는가","태양 고도와 태양 에너지양의 관계를 썼는가","여름·겨울의 남중 고도와 기온을 이어 썼는가"]},"explanation":["두 기록을 견줘요.","실험을 태양으로 옮겨요.","여름과 겨울을 설명해요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 약 20 cm로 같게 한다.","막대 그림자가 짧을 때 — 이루는 각이 크다 · 빛의 세기 예 1,412","막대 그림자가 길 때 — 이루는 각이 작다 · 빛의 세기 예 986"],"title":"손전등 실험 기록(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#1','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',1,'mc','auto','계절의 변화가 생기는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X21']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"mc","stem":"계절의 변화가 생기는 까닭은 무엇인가요?","options":[{"t":"지구의 자전축이 기울어진 채 태양 주위를 공전하기 때문에","correct":true},{"t":"지구의 자전축이 수직인 채 태양 주위를 공전하기 때문에","mis":"SC6-2-u1-X21"},{"t":"지구가 태양 주위를 공전하지 않기 때문에","mis":"SC6-2-u1-X21"},{"t":"지구의 자전축이 기울어진 방향을 계절마다 바꾸기 때문에","mis":"SC6-2-u1-X21"}],"explanation":["자전축을 떠올려요.","기울어져 있어요.","기울어진 채 공전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#2','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',1,'sa','auto','지구의 북극과 남극을 이은 가상의 직선을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"sa","stem":"지구의 북극과 남극을 이은 가상의 직선을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["자전축"],"explanation":["지구가 이 둘레로 돌아요.","보이지 않는 선이에요.","자전축이에요."],"mis":"SC6-2-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#3','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',1,'ox','auto','지구는 태양을 중심으로 일 년에 한 바퀴씩 서쪽에서 동쪽으로 도는 공전을 해요.',ARRAY['SC6-2-u1-X21']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"ox","stem":"지구는 태양을 중심으로 일 년에 한 바퀴씩 서쪽에서 동쪽으로 도는 공전을 해요.","answer":"O","reason_options":[{"t":"지구가 일정한 길을 따라 태양 둘레를 일 년에 한 바퀴 돌기 때문에","correct":true},{"t":"태양이 지구 둘레를 일 년에 한 바퀴 돌기 때문에","mis":"SC6-2-u1-X21"}],"mis":"SC6-2-u1-X21","explanation":["중심은 태양이에요.","일 년에 한 바퀴예요.","공전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#4','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',1,'mc','auto','지구본 모형실험에서 다르게 해야 할 조건은 무엇인가요?',ARRAY['SC6-2-u1-X22']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"mc","stem":"지구본 모형실험에서 다르게 해야 할 조건은 무엇인가요?","options":[{"t":"지구본의 자전축 기울기","correct":true},{"t":"전등과 지구본 사이의 거리","mis":"SC6-2-u1-X22"},{"t":"전등의 높이","mis":"SC6-2-u1-X22"},{"t":"지구본의 크기","mis":"SC6-2-u1-X22"}],"explanation":["알아보려는 것이 무엇인가요?","자전축을 세우고 기울여요.","기울기만 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#5','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',2,'mc','auto','실험 기록에서 자전축을 세운 채 공전할 때 그림자 길이는 어떠했나요?',ARRAY['SC6-2-u1-X22']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"mc","stem":"실험 기록에서 자전축을 세운 채 공전할 때 그림자 길이는 어떠했나요?","options":[{"t":"가·나·다·라 네 위치에서 모두 같았다","correct":true},{"t":"나에서 가장 짧고 라에서 가장 길었다","mis":"SC6-2-u1-X22"},{"t":"위치마다 모두 달랐다","mis":"SC6-2-u1-X22"},{"t":"그림자가 생기지 않았다","mis":"SC6-2-u1-X22"}],"explanation":["첫째 줄을 읽어요.","1.4가 네 번이에요.","모두 같아요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 한다.","자전축을 세운 채 — 가 1.4 · 나 1.4 · 다 1.4 · 라 1.4(cm, 예)","자전축을 기울인 채 — 가 1.4 · 나 0.8 · 다 1.4 · 라 3.5(cm, 예)"],"title":"지구본 실험 그림자 길이(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#6','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',2,'match','auto','실험에서 쓴 것과 실제로 나타내는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"match","stem":"실험에서 쓴 것과 실제로 나타내는 것을 알맞게 이으세요.","pairs":[{"l":"전등","r":"태양"},{"l":"지구본","r":"지구"},{"l":"지구본이 전등 둘레를 도는 것","r":"지구의 공전"},{"l":"측정기가 전등을 정면으로 향할 때","r":"태양이 남중하는 위치"}],"mis":"SC6-2-u1-X22","explanation":["빛을 내는 것은 태양이에요.","도는 것은 공전이에요.","정면이면 남중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#7','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',2,'error','auto','지구본 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X22']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"error","stem":"지구본 실험을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「지구본을 옮길 때마다 자전축이 기운 방향을 바꾸자.」","correct":true,"mis_target":"SC6-2-u1-X22"},{"t":"하은 — 「자전축이 늘 같은 방향을 향하게 하자.」","mis":"SC6-2-u1-X22"},{"t":"지우 — 「전등과 지구본 사이 거리를 일정하게 하자.」","mis":"SC6-2-u1-X22"}],"explanation":["자전축 방향은 고정해요.","방향을 바꾸면 안 돼요.","예준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#8','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',2,'mc','auto','전등의 중심 높이를 지구본의 중심 높이와 같게 맞추는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X22']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"mc","stem":"전등의 중심 높이를 지구본의 중심 높이와 같게 맞추는 까닭은 무엇인가요?","options":[{"t":"다르게 할 조건 하나만 바꾸고 나머지 조건은 같게 하기 위해서","correct":true},{"t":"전등을 더 밝게 하기 위해서","mis":"SC6-2-u1-X22"},{"t":"지구본을 빨리 돌리기 위해서","mis":"SC6-2-u1-X22"},{"t":"그림자를 없애기 위해서","mis":"SC6-2-u1-X22"}],"explanation":["조건을 맞춰요.","바꿀 것은 기울기 하나예요.","나머지는 같게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#9','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',2,'ox','auto','자전축이 수직인 채 공전하면 태양의 남중 고도가 달라지지 않아 계절의 변화가 생기지 않아요.',ARRAY['SC6-2-u1-X21']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"ox","stem":"자전축이 수직인 채 공전하면 태양의 남중 고도가 달라지지 않아 계절의 변화가 생기지 않아요.","answer":"O","reason_options":[{"t":"세운 채 공전할 때 네 위치의 그림자 길이가 모두 같았기 때문에","correct":true},{"t":"자전축의 기울기와 계절의 변화는 관계가 없기 때문에","mis":"SC6-2-u1-X21"}],"mis":"SC6-2-u1-X21","explanation":["세운 채 결과를 봐요.","그림자가 다 같았어요.","계절이 생기지 않아요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 한다.","자전축을 세운 채 — 가 1.4 · 나 1.4 · 다 1.4 · 라 1.4(cm, 예)","자전축을 기울인 채 — 가 1.4 · 나 0.8 · 다 1.4 · 라 3.5(cm, 예)"],"title":"지구본 실험 그림자 길이(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_basic#10','sci',6,2,'u1','L06','g6_2_sci_u1_L06_basic','lesson_basic','SC6-2-u1-C9',3,'mc','auto','여름에 기온이 높은 것은 지구가 태양과 가까워졌기 때문일까요?',ARRAY['SC6-2-u1-X20']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"mc","stem":"여름에 기온이 높은 것은 지구가 태양과 가까워졌기 때문일까요?","options":[{"t":"아니다, 태양과의 거리는 계절의 변화에 거의 영향을 미치지 않는다","correct":true},{"t":"그렇다, 여름에는 지구가 태양과 가까워져 기온이 높다","mis":"SC6-2-u1-X20"},{"t":"그렇다, 겨울에는 지구가 태양과 멀어져서만 기온이 낮다","mis":"SC6-2-u1-X20"},{"t":"태양과의 거리는 해마다 아무렇게나 달라진다","mis":"SC6-2-u1-X20"}],"explanation":["실험의 거리를 떠올려요.","늘 30 cm였어요.","거리는 거의 영향이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#1','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',2,'blank','auto','「실제 지구는 자전축이 (    ) 채 태양 주위를 공전합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u1-X21']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"blank","stem":"「실제 지구는 자전축이 (    ) 채 태양 주위를 공전합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"기울어진","correct":true},{"t":"수직인","mis":"SC6-2-u1-X21"},{"t":"멈춘","mis":"SC6-2-u1-X21"},{"t":"방향을 바꾼","mis":"SC6-2-u1-X21"}],"explanation":["실제 지구를 떠올려요.","똑바로 서 있지 않아요.","기울어진 채예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#2','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',2,'mc','auto','북반구가 태양 쪽으로 기울어져 있을 때 북반구의 계절은 무엇인가요?',ARRAY['SC6-2-u1-X21']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"mc","stem":"북반구가 태양 쪽으로 기울어져 있을 때 북반구의 계절은 무엇인가요?","options":[{"t":"여름","correct":true},{"t":"겨울","mis":"SC6-2-u1-X21"},{"t":"봄","mis":"SC6-2-u1-X21"},{"t":"계절이 없다","mis":"SC6-2-u1-X21"}],"explanation":["태양 쪽으로 기울면 높이 떠요.","남중 고도가 높아요.","여름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#3','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',3,'mc','auto','실험 기록에서 자전축을 기울인 채 공전할 때 그림자가 가장 짧은 위치와 그때의 태양의 남중 고도로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X07','SC6-2-u1-X22']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"mc","stem":"실험 기록에서 자전축을 기울인 채 공전할 때 그림자가 가장 짧은 위치와 그때의 태양의 남중 고도로 알맞은 것은 어느 것인가요?","options":[{"t":"나 — 가장 높다","correct":true},{"t":"라 — 가장 높다","mis":"SC6-2-u1-X07"},{"t":"나 — 가장 낮다","mis":"SC6-2-u1-X07"},{"t":"네 위치 모두 같다","mis":"SC6-2-u1-X22"}],"explanation":["둘째 줄의 가장 작은 수예요.","0.8은 나예요.","그림자가 짧으면 높이 떠요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 한다.","자전축을 세운 채 — 가 1.4 · 나 1.4 · 다 1.4 · 라 1.4(cm, 예)","자전축을 기울인 채 — 가 1.4 · 나 0.8 · 다 1.4 · 라 3.5(cm, 예)"],"title":"지구본 실험 그림자 길이(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#4','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',3,'error','auto','계절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X19','SC6-2-u1-X21']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"error","stem":"계절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라희 — 「여름에는 지구가 태양에 가까워져서 더운 거야.」","correct":true,"mis_target":"SC6-2-u1-X20"},{"t":"준호 — 「여름에는 태양의 남중 고도가 높아서 더워.」","mis":"SC6-2-u1-X19"},{"t":"민서 — 「자전축이 기울어진 채 공전해서 계절이 생겨.」","mis":"SC6-2-u1-X21"}],"explanation":["거리는 거의 영향이 없어요.","남중 고도가 열쇠예요.","라희가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#5','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',3,'mc','auto','「여름에는 태양과 가까워서 덥다」는 생각을 우리 실험으로 바로잡을 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X22']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"mc","stem":"「여름에는 태양과 가까워서 덥다」는 생각을 우리 실험으로 바로잡을 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"거리는 30 cm로 늘 같았는데도 자전축을 기울이자 위치에 따라 그림자 길이가 달라졌다","correct":true},{"t":"전등을 가까이 가져가자 그림자 길이가 달라졌다","mis":"SC6-2-u1-X20"},{"t":"자전축을 세우자 그림자 길이가 위치마다 달라졌다","mis":"SC6-2-u1-X22"},{"t":"지구본을 돌리지 않아도 그림자 길이가 달라졌다","mis":"SC6-2-u1-X22"}],"explanation":["거리는 바꾸지 않았어요.","기울기만 바꿨어요.","그래도 그림자가 달라졌어요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 한다.","자전축을 세운 채 — 가 1.4 · 나 1.4 · 다 1.4 · 라 1.4(cm, 예)","자전축을 기울인 채 — 가 1.4 · 나 0.8 · 다 1.4 · 라 3.5(cm, 예)"],"title":"지구본 실험 그림자 길이(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#6','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',3,'ox','auto','자전축이 기울어진 채 공전하면 지구의 위치에 따라 남중 고도뿐 아니라 낮의 길이와 태양 에너지양도 달라져요.',ARRAY['SC6-2-u1-X21']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"ox","stem":"자전축이 기울어진 채 공전하면 지구의 위치에 따라 남중 고도뿐 아니라 낮의 길이와 태양 에너지양도 달라져요.","answer":"O","reason_options":[{"t":"남중 고도가 달라지면 낮의 길이와 일정한 면적의 지표면이 받는 태양 에너지양도 함께 달라지기 때문에","correct":true},{"t":"남중 고도만 달라지고 나머지는 늘 같기 때문에","mis":"SC6-2-u1-X21"}],"mis":"SC6-2-u1-X21","explanation":["앞 차시들을 떠올려요.","남중 고도와 함께 움직여요.","모두 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#7','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',3,'mc','auto','북반구가 태양 반대쪽으로 기울어져 있을 때 북반구의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X13','SC6-2-u1-X19','SC6-2-u1-X20']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"mc","stem":"북반구가 태양 반대쪽으로 기울어져 있을 때 북반구의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"남중 고도가 낮고 낮이 짧으며 태양 에너지양이 적다","correct":true},{"t":"남중 고도가 높고 낮이 길며 태양 에너지양이 많다","mis":"SC6-2-u1-X13"},{"t":"남중 고도는 낮지만 태양 에너지양은 많다","mis":"SC6-2-u1-X19"},{"t":"태양에서 멀어져서 남중 고도가 높다","mis":"SC6-2-u1-X20"}],"explanation":["반대쪽으로 기울면 겨울이에요.","태양이 낮게 떠요.","낮고 짧고 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#8','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',4,'mc','auto','만약 지구의 자전축이 수직인 채 공전한다면 어떻게 될까요?',ARRAY['SC6-2-u1-X21','SC6-2-u1-X20']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C9","difficulty":4,"kind":"mc","stem":"만약 지구의 자전축이 수직인 채 공전한다면 어떻게 될까요?","options":[{"t":"계절의 변화가 생기지 않아 일 년 내내 기온이 거의 일정할 것이다","correct":true},{"t":"여름과 겨울의 기온 차이가 더 커질 것이다","mis":"SC6-2-u1-X21"},{"t":"태양의 남중 고도가 계절마다 더 크게 달라질 것이다","mis":"SC6-2-u1-X21"},{"t":"지구와 태양의 거리가 크게 달라질 것이다","mis":"SC6-2-u1-X20"}],"explanation":["세운 채 실험을 떠올려요.","그림자가 다 같았어요.","계절이 생기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#9','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',4,'mc','auto','두 실험 결과로 계절 변화의 원인을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X21','SC6-2-u1-X22']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C9","difficulty":4,"kind":"mc","stem":"두 실험 결과로 계절 변화의 원인을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"자전축이 기울어진 채 공전하면 위치에 따라 남중 고도가 달라지고, 그에 따라 낮의 길이와 태양 에너지양이 달라져 계절이 생긴다","correct":true},{"t":"지구가 태양에 가까워졌다 멀어졌다 해서 계절이 생긴다","mis":"SC6-2-u1-X20"},{"t":"자전축이 수직이어야 계절이 생긴다","mis":"SC6-2-u1-X21"},{"t":"공전할 때 자전축이 기운 방향이 바뀌어 계절이 생긴다","mis":"SC6-2-u1-X22"}],"explanation":["두 줄을 견줘요.","기울일 때만 달라졌어요.","남중 고도부터 이어요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 한다.","자전축을 세운 채 — 가 1.4 · 나 1.4 · 다 1.4 · 라 1.4(cm, 예)","자전축을 기울인 채 — 가 1.4 · 나 0.8 · 다 1.4 · 라 3.5(cm, 예)"],"title":"지구본 실험 그림자 길이(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L06_challenge#10','sci',6,2,'u1','L06','g6_2_sci_u1_L06_challenge','lesson_challenge','SC6-2-u1-C9',4,'essay','teacher','실험 기록의 두 결과를 견주어 계절의 변화가 생기는 까닭을 설명하고, 「여름에는 지구가 태양과 가까워서 덥다」는 생각이 왜 맞지 않는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C9","difficulty":4,"kind":"essay","stem":"실험 기록의 두 결과를 견주어 계절의 변화가 생기는 까닭을 설명하고, 「여름에는 지구가 태양과 가까워서 덥다」는 생각이 왜 맞지 않는지 쓰세요.","answer_guide":{"answer":"예: 자전축을 세운 채 공전하면 네 위치의 그림자 길이가 모두 같아 태양의 남중 고도가 달라지지 않는다. 자전축을 기울인 채 공전하면 위치에 따라 그림자 길이가 달라져 남중 고도가 달라진다. 실제 지구는 자전축이 기울어진 채 공전하므로 위치에 따라 남중 고도·낮의 길이·태양 에너지양이 달라져 계절이 생긴다. 실험에서 전등과 지구본의 거리는 늘 같았는데도 그림자 길이가 달라졌고, 북반구는 겨울보다 여름에 태양과 오히려 더 멀기 때문에 거리 때문에 덥다는 생각은 맞지 않다.","scoring_points":["세운 채와 기울인 채의 결과를 견주었는가","기울어진 채 공전해서 계절이 생긴다고 썼는가","거리가 원인이 아닌 근거를 썼는가"]},"explanation":["두 결과를 견줘요.","원인을 한 문장으로 써요.","거리는 늘 같았어요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 한다.","자전축을 세운 채 — 가 1.4 · 나 1.4 · 다 1.4 · 라 1.4(cm, 예)","자전축을 기울인 채 — 가 1.4 · 나 0.8 · 다 1.4 · 라 3.5(cm, 예)"],"title":"지구본 실험 그림자 길이(실험관찰 예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#1','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',1,'mc','auto','계절 축제 안내 자료에 꼭 담아야 할 과학 정보는 어느 것인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C10","difficulty":1,"kind":"mc","stem":"계절 축제 안내 자료에 꼭 담아야 할 과학 정보는 어느 것인가요?","options":[{"t":"축제 시기의 태양의 남중 고도, 낮의 길이, 기온","correct":true},{"t":"축제를 여는 사람의 이름","mis":"SC6-2-u1-X23"},{"t":"입장권의 가격","mis":"SC6-2-u1-X23"},{"t":"화려한 꾸밈 그림","mis":"SC6-2-u1-X23"}],"explanation":["이 단원에서 배운 것이에요.","계절마다 달라지는 세 가지예요.","남중 고도·낮의 길이·기온이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#2','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',1,'mc','auto','계절 축제 안내 자료를 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C10","difficulty":1,"kind":"mc","stem":"계절 축제 안내 자료를 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"축제를 하나 고른 다음 그 시기의 남중 고도, 낮의 길이, 기온을 조사한다","correct":true},{"t":"디자인 플랫폼으로 안내 자료를 만든다","mis":"SC6-2-u1-X23"},{"t":"모은 자료를 공유 플랫폼에 올린다","mis":"SC6-2-u1-X23"},{"t":"다른 모둠의 자료에 댓글을 단다","mis":"SC6-2-u1-X23"}],"explanation":["계획하기부터 해요.","축제를 골라요.","그 시기를 조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#3','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',1,'ox','auto','다른 모둠의 좋은 아이디어는 그대로 가져와 써도 돼요.',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C10","difficulty":1,"kind":"ox","stem":"다른 모둠의 좋은 아이디어는 그대로 가져와 써도 돼요.","answer":"X","reason_options":[{"t":"자신만의 아이디어를 내야 하고, 어려우면 기존 아이디어를 더하거나 빼서 바꿀 수 있기 때문에","correct":true},{"t":"좋은 아이디어는 누구 것이든 그대로 써야 하기 때문에","mis":"SC6-2-u1-X23"}],"mis":"SC6-2-u1-X23","explanation":["나만의 생각이 필요해요.","변형은 할 수 있어요.","그대로는 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#4','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',1,'sa','auto','글자·사진·아이콘 등을 자유롭게 배치해 자료를 쉽고 빠르게 만드는 도구를 무엇이라고 하나요? (□□□ 플랫폼)','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u1-C10","difficulty":1,"kind":"sa","stem":"글자·사진·아이콘 등을 자유롭게 배치해 자료를 쉽고 빠르게 만드는 도구를 무엇이라고 하나요? (□□□ 플랫폼)","answer":["디자인","디자인 플랫폼","디자인플랫폼"],"explanation":["자료를 꾸며 만드는 도구예요.","세 글자예요.","디자인 플랫폼이에요."],"mis":"SC6-2-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#5','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',2,'mc','auto','여름 축제의 준비물 안내로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"mc","stem":"여름 축제의 준비물 안내로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"색안경과 자외선 차단제를 준비하고 시원한 옷을 입고 오세요","correct":true},{"t":"두꺼운 외투와 장갑을 꼭 챙기세요","mis":"SC6-2-u1-X23"},{"t":"손난로를 여러 개 준비하세요","mis":"SC6-2-u1-X23"},{"t":"준비물은 아무것도 필요 없어요","mis":"SC6-2-u1-X23"}],"explanation":["여름은 남중 고도가 높아요.","햇빛이 강하고 더워요.","햇빛과 더위를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#6','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',2,'match','auto','교과서 예시 축제와 그 자료에 담은 과학 정보를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"match","stem":"교과서 예시 축제와 그 자료에 담은 과학 정보를 알맞게 이으세요.","pairs":[{"l":"수박 축제","r":"태양의 남중 고도가 높다"},{"l":"단풍 축제","r":"여름보다 낮의 길이가 짧다"},{"l":"눈꽃 축제","r":"기온이 낮다"}],"mis":"SC6-2-u1-X23","explanation":["여름은 높게 떠요.","가을은 낮이 짧아져요.","겨울은 추워요."],"asset":{"type":"passage","lines":["수박 축제(6월) — 남중 고도가 높아요 · 그늘막을 많이 준비했어요.","단풍 축제(9월) — 여름보다 낮이 짧아요 · 해가 지는 시각을 확인하세요.","눈꽃 축제(12월) — 기온이 낮아요 · 옷을 따뜻하게 입고 오세요."],"title":"교과서 예시 안내 자료 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#7','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',2,'error','auto','다른 모둠의 자료를 보고 친구들이 댓글을 달았어요. 바르지 않은 댓글을 쓴 친구는 누구인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"error","stem":"다른 모둠의 자료를 보고 친구들이 댓글을 달았어요. 바르지 않은 댓글을 쓴 친구는 누구인가요?","options":[{"t":"이현 — 「너희 모둠 자료는 글씨가 엉망이라 별로야.」","correct":true,"mis_target":"SC6-2-u1-X23"},{"t":"세아 — 「여름에 남중 고도가 높다는 내용이 잘 드러나 있네.」","mis":"SC6-2-u1-X23"},{"t":"우진 — 「겨울에 기온이 낮으니 옷차림 안내를 잘했어.」","mis":"SC6-2-u1-X23"}],"explanation":["잘한 점을 칭찬해요.","바르고 고운 말을 써요.","이현의 댓글이 바르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#8','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',2,'mc','auto','여름 축제 운영 시간을 오전 10시부터 오후 7시까지로 길게 정한 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X23','SC6-2-u1-X13']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"mc","stem":"여름 축제 운영 시간을 오전 10시부터 오후 7시까지로 길게 정한 까닭은 무엇인가요?","options":[{"t":"여름에는 낮의 길이가 길기 때문에","correct":true},{"t":"여름에는 기온이 낮기 때문에","mis":"SC6-2-u1-X23"},{"t":"여름에는 태양의 남중 고도가 낮기 때문에","mis":"SC6-2-u1-X13"},{"t":"여름에는 사람이 적게 오기 때문에","mis":"SC6-2-u1-X23"}],"explanation":["해가 언제까지 떠 있나요?","여름은 해가 늦게 져요.","낮이 길어서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#9','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',2,'ox','auto','겨울 축제 안내에 「기온이 낮으므로 옷을 따뜻하게 입고 오세요」라고 쓸 수 있어요.',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"ox","stem":"겨울 축제 안내에 「기온이 낮으므로 옷을 따뜻하게 입고 오세요」라고 쓸 수 있어요.","answer":"O","reason_options":[{"t":"겨울에는 남중 고도가 낮아 태양 에너지양이 적고 기온이 낮기 때문에","correct":true},{"t":"겨울에는 남중 고도가 높아 따뜻하기 때문에","mis":"SC6-2-u1-X13"}],"mis":"SC6-2-u1-X13","explanation":["겨울 기온을 떠올려요.","추우니 따뜻하게 입어요.","알맞은 안내예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_basic#10','sci',6,2,'u1','L07','g6_2_sci_u1_L07_basic','lesson_basic','SC6-2-u1-C10',3,'mc','auto','단풍 축제 안내 자료에서 해가 지는 시각을 확인하라고 한 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X23','SC6-2-u1-X13']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"mc","stem":"단풍 축제 안내 자료에서 해가 지는 시각을 확인하라고 한 까닭은 무엇인가요?","options":[{"t":"가을은 여름보다 낮의 길이가 짧기 때문에","correct":true},{"t":"가을은 기온이 가장 낮기 때문에","mis":"SC6-2-u1-X23"},{"t":"가을은 태양의 남중 고도가 가장 높기 때문에","mis":"SC6-2-u1-X13"},{"t":"가을은 축제 기간이 짧기 때문에","mis":"SC6-2-u1-X23"}],"explanation":["해넘이 행사가 있어요.","여름과 낮의 길이를 견줘요.","낮이 짧아졌어요."],"asset":{"type":"passage","lines":["수박 축제(6월) — 남중 고도가 높아요 · 그늘막을 많이 준비했어요.","단풍 축제(9월) — 여름보다 낮이 짧아요 · 해가 지는 시각을 확인하세요.","눈꽃 축제(12월) — 기온이 낮아요 · 옷을 따뜻하게 입고 오세요."],"title":"교과서 예시 안내 자료 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#1','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',2,'mc','auto','안내 자료 만들기에서 「나누기」 단계에 하는 일은 어느 것인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"mc","stem":"안내 자료 만들기에서 「나누기」 단계에 하는 일은 어느 것인가요?","options":[{"t":"공유 플랫폼에 자료를 올리고 다른 모둠의 잘한 점을 댓글로 칭찬한다","correct":true},{"t":"축제 시기의 남중 고도를 조사한다","mis":"SC6-2-u1-X23"},{"t":"준비물과 옷차림을 이야기한다","mis":"SC6-2-u1-X23"},{"t":"디자인 플랫폼으로 자료를 만든다","mis":"SC6-2-u1-X23"}],"explanation":["계획하기·해 보기·나누기가 있어요.","마지막 단계예요.","올리고 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#2','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',2,'sa','auto','모둠에서 만든 자료를 올려 반 친구들 모두가 볼 수 있게 하는 곳을 무엇이라고 하나요? (□□ 플랫폼)','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"sa","stem":"모둠에서 만든 자료를 올려 반 친구들 모두가 볼 수 있게 하는 곳을 무엇이라고 하나요? (□□ 플랫폼)","answer":["공유","공유 플랫폼","공유플랫폼"],"explanation":["함께 보는 곳이에요.","두 글자예요.","공유 플랫폼이에요."],"mis":"SC6-2-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#3','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',3,'mc','auto','겨울 빙어 축제 안내 문구로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"mc","stem":"겨울 빙어 축제 안내 문구로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"태양의 남중 고도가 높아 그늘막을 많이 준비했어요","correct":true},{"t":"기온이 낮으므로 따뜻하게 입고 오세요","mis":"SC6-2-u1-X13"},{"t":"낮의 길이가 짧으니 해가 지기 전에 오세요","mis":"SC6-2-u1-X13"},{"t":"태양의 남중 고도가 낮아 기온이 낮아요","mis":"SC6-2-u1-X13"}],"explanation":["겨울의 태양을 떠올려요.","남중 고도가 낮아요.","그늘막 문구가 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#4','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',3,'error','auto','안내 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"error","stem":"안내 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「안내 자료는 예쁘게 꾸미기만 하면 돼.」","correct":true,"mis_target":"SC6-2-u1-X23"},{"t":"보민 — 「세 가지 과학 정보를 꼭 담아야 해.」","mis":"SC6-2-u1-X23"},{"t":"아린 — 「모둠원이 역할을 나누어 함께 만들자.」","mis":"SC6-2-u1-X23"}],"explanation":["꾸밈보다 내용이에요.","과학 정보가 중심이에요.","수호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#5','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',3,'mc','auto','여름 축제에 추가로 안내할 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X23','SC6-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"mc","stem":"여름 축제에 추가로 안내할 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"물을 충분히 마시고, 태양 빛을 피할 모자나 양산을 준비하세요","correct":true},{"t":"손난로와 두꺼운 목도리를 준비하세요","mis":"SC6-2-u1-X23"},{"t":"해가 일찍 지니 오후 4시 전에 오세요","mis":"SC6-2-u1-X13"},{"t":"햇빛이 약하니 모자는 필요 없어요","mis":"SC6-2-u1-X13"}],"explanation":["여름은 햇빛이 강해요.","더워서 땀이 나요.","물과 모자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#6','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',3,'ox','auto','안내 자료를 평가할 때 먼저 볼 것은 계절에 따른 남중 고도·낮의 길이·기온을 설명했는지예요.',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"ox","stem":"안내 자료를 평가할 때 먼저 볼 것은 계절에 따른 남중 고도·낮의 길이·기온을 설명했는지예요.","answer":"O","reason_options":[{"t":"이 활동의 중심은 계절에 따른 과학 정보를 담는 것이기 때문에","correct":true},{"t":"얼마나 화려하게 꾸몄는지가 가장 중요하기 때문에","mis":"SC6-2-u1-X23"}],"mis":"SC6-2-u1-X23","explanation":["평가하기 첫 항목을 떠올려요.","과학 정보예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#7','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',3,'mc','auto','디자인 플랫폼이나 공유 플랫폼을 쓰기 어려울 때는 어떻게 하면 좋을까요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"mc","stem":"디자인 플랫폼이나 공유 플랫폼을 쓰기 어려울 때는 어떻게 하면 좋을까요?","options":[{"t":"그림 도구로 직접 만들어 사진으로 찍어 올린다","correct":true},{"t":"활동을 하지 않는다","mis":"SC6-2-u1-X23"},{"t":"다른 모둠의 자료를 대신 올린다","mis":"SC6-2-u1-X23"},{"t":"과학 정보를 빼고 짧게 만든다","mis":"SC6-2-u1-X23"}],"explanation":["다른 방법이 있어요.","손으로 만들 수 있어요.","사진으로 올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#8','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',4,'mc','auto','봄에 열리는 벚꽃 축제 안내 자료를 만들 때 남중 고도와 낮의 길이를 어떻게 쓰면 알맞을까요?',ARRAY['SC6-2-u1-X13','SC6-2-u1-X23']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C10","difficulty":4,"kind":"mc","stem":"봄에 열리는 벚꽃 축제 안내 자료를 만들 때 남중 고도와 낮의 길이를 어떻게 쓰면 알맞을까요?","options":[{"t":"여름과 겨울의 중간 정도라고 쓴다","correct":true},{"t":"남중 고도가 가장 높고 낮이 가장 길다고 쓴다","mis":"SC6-2-u1-X13"},{"t":"남중 고도가 가장 낮고 낮이 가장 짧다고 쓴다","mis":"SC6-2-u1-X13"},{"t":"봄은 조사할 수 없으니 빼고 쓴다","mis":"SC6-2-u1-X23"}],"explanation":["계절별 그래프를 떠올려요.","봄은 여름과 겨울 사이예요.","중간 정도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#9','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',4,'mc','auto','수박 축제에서 그늘막을 많이 준비한 까닭을 과학 정보와 이어 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X13','SC6-2-u1-X23']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C10","difficulty":4,"kind":"mc","stem":"수박 축제에서 그늘막을 많이 준비한 까닭을 과학 정보와 이어 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"여름에는 태양의 남중 고도가 높아 태양 빛이 강하기 때문에","correct":true},{"t":"여름에는 낮의 길이가 짧기 때문에","mis":"SC6-2-u1-X13"},{"t":"여름에는 태양의 남중 고도가 낮기 때문에","mis":"SC6-2-u1-X13"},{"t":"그늘막을 놓으면 자료가 예뻐 보이기 때문에","mis":"SC6-2-u1-X23"}],"explanation":["수박 축제 정보를 읽어요.","남중 고도가 높아요.","햇빛이 강해요."],"asset":{"type":"passage","lines":["수박 축제(6월) — 남중 고도가 높아요 · 그늘막을 많이 준비했어요.","단풍 축제(9월) — 여름보다 낮이 짧아요 · 해가 지는 시각을 확인하세요.","눈꽃 축제(12월) — 기온이 낮아요 · 옷을 따뜻하게 입고 오세요."],"title":"교과서 예시 안내 자료 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L07_challenge#10','sci',6,2,'u1','L07','g6_2_sci_u1_L07_challenge','lesson_challenge','SC6-2-u1-C10',4,'essay','teacher','계절 하나를 골라 그 계절 축제의 안내 자료를 계획하세요. 축제 시기의 태양의 남중 고도·낮의 길이·기온을 쓰고, 그에 맞는 준비물·옷차림·운영 시간을 안내하세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C10","difficulty":4,"kind":"essay","stem":"계절 하나를 골라 그 계절 축제의 안내 자료를 계획하세요. 축제 시기의 태양의 남중 고도·낮의 길이·기온을 쓰고, 그에 맞는 준비물·옷차림·운영 시간을 안내하세요.","answer_guide":{"answer":"예: 겨울 빙어 축제 — 겨울에는 태양의 남중 고도가 낮고 낮의 길이가 짧으며 기온이 낮다. 기온이 낮으므로 두꺼운 외투와 장갑을 준비하고 따뜻하게 입고 온다. 낮의 길이가 짧아 해가 일찍 지므로 축제 운영 시간은 오전 10시부터 오후 4시까지로 정한다.","scoring_points":["남중 고도·낮의 길이·기온을 계절에 맞게 썼는가","준비물·옷차림을 과학 정보와 이어 썼는가","운영 시간을 낮의 길이와 이어 썼는가"]},"explanation":["계절을 정해요.","세 정보를 써요.","안내를 정보와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#1','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',1,'mc','auto','추적형 태양광 발전기가 자동으로 방향과 각도를 움직이는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C11","difficulty":1,"kind":"mc","stem":"추적형 태양광 발전기가 자동으로 방향과 각도를 움직이는 까닭은 무엇인가요?","options":[{"t":"태양과 발전기의 면이 이루는 각을 수직으로 유지하기 위해서","correct":true},{"t":"비가 오는 것을 미리 알려 주기 위해서","mis":"SC6-2-u1-X24"},{"t":"늘 한 방향만 바라보게 하기 위해서","mis":"SC6-2-u1-X24"},{"t":"지붕에만 설치하기 위해서","mis":"SC6-2-u1-X24"}],"explanation":["태양을 따라가요.","빛을 정면으로 받아요.","수직을 유지해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#2','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',1,'mc','auto','햇빛 지도는 무엇을 알려 주나요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C11","difficulty":1,"kind":"mc","stem":"햇빛 지도는 무엇을 알려 주나요?","options":[{"t":"장소별로 일 년 동안 받을 수 있는 태양 에너지양","correct":true},{"t":"장소별 하루 기온","mis":"SC6-2-u1-X24"},{"t":"앞으로 비가 올 날짜","mis":"SC6-2-u1-X24"},{"t":"발전기를 만든 회사","mis":"SC6-2-u1-X24"}],"explanation":["지도에 햇빛 정보가 있어요.","장소마다 달라요.","받을 수 있는 태양 에너지양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#3','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',1,'sa','auto','재생 에너지 가운데 태양 빛을 이용해 전기를 만드는 발전 방법을 무엇이라고 하나요?','{}'::text[],false,'{"seq":3,"concept":"SC6-2-u1-C11","difficulty":1,"kind":"sa","stem":"재생 에너지 가운데 태양 빛을 이용해 전기를 만드는 발전 방법을 무엇이라고 하나요?","answer":["태양광 발전","태양광발전"],"explanation":["태양 빛으로 전기를 만들어요.","□□□ 발전이에요.","태양광 발전이에요."],"mis":"SC6-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#4','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',1,'ox','auto','추적형 태양광 발전기는 고정형 태양광 발전기보다 전기 에너지를 더 많이 생산할 수 있어요.',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C11","difficulty":1,"kind":"ox","stem":"추적형 태양광 발전기는 고정형 태양광 발전기보다 전기 에너지를 더 많이 생산할 수 있어요.","answer":"O","reason_options":[{"t":"태양을 따라 움직여 태양 에너지를 더 많이 받기 때문에","correct":true},{"t":"늘 한 방향만 바라보기 때문에","mis":"SC6-2-u1-X24"}],"mis":"SC6-2-u1-X24","explanation":["태양을 따라가요.","더 많이 받아요.","전기도 더 많이 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#5','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',2,'match','auto','기술과 그 기술이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"match","stem":"기술과 그 기술이 하는 일을 알맞게 이으세요.","pairs":[{"l":"추적형 태양광 발전기","r":"태양을 따라 방향과 각도를 움직인다"},{"l":"햇빛 지도","r":"장소별 태양 에너지양을 알려 준다"},{"l":"태양 전지판","r":"지붕·외벽·유리에 붙여 전기를 만든다"},{"l":"태양광 발전","r":"태양 에너지를 전기 에너지로 바꾼다"}],"mis":"SC6-2-u1-X24","explanation":["움직이는 것은 추적형이에요.","알려 주는 것은 지도예요.","판과 발전 방법을 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#6','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',2,'mc','auto','햇빛 지도를 어디에 활용할 수 있나요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"mc","stem":"햇빛 지도를 어디에 활용할 수 있나요?","options":[{"t":"태양광 발전기를 어느 장소에 설치할지 고를 때","correct":true},{"t":"발전기의 색깔을 고를 때","mis":"SC6-2-u1-X24"},{"t":"발전기를 만드는 공장을 고를 때","mis":"SC6-2-u1-X24"},{"t":"발전기를 한 방향에 고정할 때","mis":"SC6-2-u1-X24"}],"explanation":["장소별 정보예요.","많이 받는 곳을 찾아요.","설치할 곳을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#7','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',2,'error','auto','태양광 발전기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"error","stem":"태양광 발전기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"정우 — 「발전기는 한 방향에 고정해 두는 게 가장 좋아.」","correct":true,"mis_target":"SC6-2-u1-X24"},{"t":"나래 — 「태양을 따라 움직이면 더 많이 받아.」","mis":"SC6-2-u1-X24"},{"t":"윤재 — 「햇빛 지도로 설치할 곳을 고를 수 있어.」","mis":"SC6-2-u1-X24"}],"explanation":["태양은 계속 움직여요.","따라가야 더 받아요.","정우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#8','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',2,'mc','auto','태양광 발전 연구 및 개발자가 하는 일은 어느 것인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"mc","stem":"태양광 발전 연구 및 개발자가 하는 일은 어느 것인가요?","options":[{"t":"태양 전지의 소재를 연구하고 개발한다","correct":true},{"t":"지형을 분석해 태양 전지판을 설치한다","mis":"SC6-2-u1-X24"},{"t":"축제 안내 자료를 만든다","mis":"SC6-2-u1-X24"},{"t":"날씨를 예보한다","mis":"SC6-2-u1-X24"}],"explanation":["연구하는 직업이에요.","전지의 재료를 연구해요.","소재를 개발해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#9','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',2,'ox','auto','그늘이 많이 지는 곳에 발전기를 설치하면 태양 에너지를 많이 받을 수 있어요.',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"ox","stem":"그늘이 많이 지는 곳에 발전기를 설치하면 태양 에너지를 많이 받을 수 있어요.","answer":"X","reason_options":[{"t":"그늘에서는 태양 빛을 덜 받아 태양 에너지양이 적기 때문에","correct":true},{"t":"그늘에서 발전기가 더 시원해 전기를 많이 만들기 때문에","mis":"SC6-2-u1-X24"}],"mis":"SC6-2-u1-X24","explanation":["그늘은 빛이 가려진 곳이에요.","빛을 덜 받아요.","많이 받을 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_basic#10','sci',6,2,'u1','L08','g6_2_sci_u1_L08_basic','lesson_basic','SC6-2-u1-C11',3,'mc','auto','추적형 태양광 발전기와 햇빛 지도는 어떤 과학적 사실을 바탕으로 만들어졌나요?',ARRAY['SC6-2-u1-X24','SC6-2-u1-X06']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"mc","stem":"추적형 태양광 발전기와 햇빛 지도는 어떤 과학적 사실을 바탕으로 만들어졌나요?","options":[{"t":"태양 고도가 달라지면 일정한 면적의 지표면이 받는 태양 에너지양이 달라진다","correct":true},{"t":"새로 나온 기술일수록 전기를 많이 만든다","mis":"SC6-2-u1-X24"},{"t":"발전기가 비쌀수록 태양 에너지를 많이 받는다","mis":"SC6-2-u1-X24"},{"t":"태양은 하루 동안 늘 같은 높이에 머문다","mis":"SC6-2-u1-X06"}],"explanation":["왜 필요했는지 거슬러 가요.","태양 고도가 달라져요.","받는 양도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#1','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',2,'mc','auto','태양 에너지를 많이 받을 수 있는 방법이 아닌 것은 어느 것인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"mc","stem":"태양 에너지를 많이 받을 수 있는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"그늘이 많이 지는 곳에 발전기를 설치한다","correct":true},{"t":"태양을 따라 발전기의 방향과 각도를 움직인다","mis":"SC6-2-u1-X24"},{"t":"태양 에너지양이 많은 장소를 찾아 설치한다","mis":"SC6-2-u1-X24"},{"t":"커다란 거울로 태양 빛을 발전기로 반사한다","mis":"SC6-2-u1-X24"}],"explanation":["빛을 더 받는 방법을 골라요.","그늘은 빛이 적어요.","그늘 설치가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#2','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',2,'sa','auto','태양광 발전 시스템을 설계하고 지형과 일조량을 분석해 태양 전지판을 설치하는 직업은 무엇인가요? (태양광 □□ 전문가)','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"sa","stem":"태양광 발전 시스템을 설계하고 지형과 일조량을 분석해 태양 전지판을 설치하는 직업은 무엇인가요? (태양광 □□ 전문가)","answer":["설치","태양광 설치 전문가"],"explanation":["직접 설치하는 직업이에요.","두 글자예요.","태양광 설치 전문가예요."],"mis":"SC6-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#3','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',3,'mc','auto','커다란 거울을 이용하면 태양 에너지를 더 많이 받을 수 있는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"mc","stem":"커다란 거울을 이용하면 태양 에너지를 더 많이 받을 수 있는 까닭은 무엇인가요?","options":[{"t":"여러 방향에서 온 태양 빛을 발전기 쪽으로 모을 수 있기 때문에","correct":true},{"t":"거울이 태양 빛을 없애 주기 때문에","mis":"SC6-2-u1-X24"},{"t":"거울이 비싸기 때문에","mis":"SC6-2-u1-X24"},{"t":"거울이 그늘을 만들어 주기 때문에","mis":"SC6-2-u1-X24"}],"explanation":["거울은 빛을 반사해요.","한곳으로 보내요.","빛을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#4','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',3,'error','auto','과학 기술을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"error","stem":"과학 기술을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「새로 나온 기술일수록 무조건 좋은 기술이야.」","correct":true,"mis_target":"SC6-2-u1-X24"},{"t":"하람 — 「태양 고도에 관한 과학적 사실에서 기술이 나왔어.」","mis":"SC6-2-u1-X24"},{"t":"지율 — 「햇빛 지도는 설치할 곳을 고르게 해 줘.」","mis":"SC6-2-u1-X24"}],"explanation":["기술의 값어치를 생각해요.","바탕이 된 과학적 사실을 봐요.","태윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#5','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',3,'mc','auto','한곳에 고정된 태양광 발전기가 받는 태양 에너지양이 하루 동안 달라지는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X24','SC6-2-u1-X06']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"mc","stem":"한곳에 고정된 태양광 발전기가 받는 태양 에너지양이 하루 동안 달라지는 까닭은 무엇인가요?","options":[{"t":"하루 동안 태양 고도가 달라지기 때문에","correct":true},{"t":"발전기가 저절로 움직이기 때문에","mis":"SC6-2-u1-X24"},{"t":"태양 고도가 하루 내내 같기 때문에","mis":"SC6-2-u1-X06"},{"t":"기온만 달라지기 때문에","mis":"SC6-2-u1-X24"}],"explanation":["태양은 높아졌다 낮아져요.","고정된 발전기는 따라가지 못해요.","태양 고도 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#6','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',3,'ox','auto','태양 에너지를 효과적으로 받는 기술은 안전하고 지속가능한 사회를 만드는 데 도움을 줘요.',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"ox","stem":"태양 에너지를 효과적으로 받는 기술은 안전하고 지속가능한 사회를 만드는 데 도움을 줘요.","answer":"O","reason_options":[{"t":"태양 에너지를 전기 에너지로 바꾸어 생활에 쓰는 재생 에너지이기 때문에","correct":true},{"t":"기술은 과학적 사실과 아무 관계가 없기 때문에","mis":"SC6-2-u1-X24"}],"mis":"SC6-2-u1-X24","explanation":["재생 에너지예요.","생활에 쓰여요.","도움을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#7','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',3,'mc','auto','태양 전지판을 붙인 가방을 만들면 좋은 점은 무엇인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"mc","stem":"태양 전지판을 붙인 가방을 만들면 좋은 점은 무엇인가요?","options":[{"t":"평소에 이동할 때에도 태양 에너지를 받을 수 있다","correct":true},{"t":"가방이 더 무거워진다","mis":"SC6-2-u1-X24"},{"t":"그늘에서만 전기를 만든다","mis":"SC6-2-u1-X24"},{"t":"태양 고도를 바꿀 수 있다","mis":"SC6-2-u1-X24"}],"explanation":["가방은 늘 들고 다녀요.","걸을 때도 햇빛을 받아요.","이동하며 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#8','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',4,'mc','auto','이 차시에서 배운 것을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C11","difficulty":4,"kind":"mc","stem":"이 차시에서 배운 것을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"태양 고도가 달라진다는 사실을 바탕으로 추적형 발전기와 햇빛 지도 같은 기술이 나왔고, 받은 태양 에너지는 전기 에너지로 바뀌어 쓰인다","correct":true},{"t":"새롭고 비싼 기술일수록 태양 에너지를 많이 받는다","mis":"SC6-2-u1-X24"},{"t":"발전기는 한 방향에 고정하는 것이 가장 좋다","mis":"SC6-2-u1-X24"},{"t":"태양 에너지 기술은 과학적 사실과 관계없이 만들어졌다","mis":"SC6-2-u1-X24"}],"explanation":["과학적 사실에서 출발해요.","두 기술이 나왔어요.","전기 에너지로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#9','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',4,'mc','auto','같은 고정형 태양광 발전기가 겨울에 여름보다 전기를 적게 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X24','SC6-2-u1-X13']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C11","difficulty":4,"kind":"mc","stem":"같은 고정형 태양광 발전기가 겨울에 여름보다 전기를 적게 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"겨울에는 남중 고도가 낮아 받는 태양 에너지양이 적고 낮의 길이도 짧기 때문에","correct":true},{"t":"겨울에는 지구가 태양에서 멀어지기 때문에","mis":"SC6-2-u1-X20"},{"t":"겨울에는 발전기가 자주 고장 나기 때문에","mis":"SC6-2-u1-X24"},{"t":"겨울에는 남중 고도가 높아 빛이 너무 세기 때문에","mis":"SC6-2-u1-X13"}],"explanation":["겨울의 남중 고도를 떠올려요.","태양 에너지양이 적어요.","낮도 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_L08_challenge#10','sci',6,2,'u1','L08','g6_2_sci_u1_L08_challenge','lesson_challenge','SC6-2-u1-C11',4,'essay','teacher','태양 에너지를 더 많이 받을 수 있는 방법을 하나 생각해 쓰고, 그 방법이 어떤 과학적 사실을 바탕으로 했는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC6-2-u1-C11","difficulty":4,"kind":"essay","stem":"태양 에너지를 더 많이 받을 수 있는 방법을 하나 생각해 쓰고, 그 방법이 어떤 과학적 사실을 바탕으로 했는지 쓰세요.","answer_guide":{"answer":"예: 학교 옥상에 태양을 따라 각도가 바뀌는 태양 전지판을 설치한다. 태양 고도는 하루 동안과 계절에 따라 달라지고, 태양 고도가 높을수록 일정한 면적의 지표면이 받는 태양 에너지양이 많으므로 전지판이 태양을 향해 수직을 유지하면 태양 에너지를 더 많이 받을 수 있다.","scoring_points":["태양 에너지를 더 많이 받는 방법을 썼는가","태양 고도가 달라진다는 사실을 썼는가","방법과 과학적 사실을 알맞게 이었는가"]},"explanation":["방법을 하나 정해요.","태양 고도를 떠올려요.","둘을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#1','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C1',1,'mc','auto','여러 가지 꽃이 피어 온 세상이 밝아지는 계절은 언제인가요?',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"mc","stem":"여러 가지 꽃이 피어 온 세상이 밝아지는 계절은 언제인가요?","options":[{"t":"봄","correct":true},{"t":"여름","mis":"SC6-2-u1-X01"},{"t":"가을","mis":"SC6-2-u1-X01"},{"t":"겨울","mis":"SC6-2-u1-X01"}],"explanation":["꽃을 떠올려요.","날이 따뜻해지기 시작해요.","봄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#2','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C2',1,'mc','auto','태양의 높이를 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"mc","stem":"태양의 높이를 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"태양이 지표면과 이루는 각으로 나타낸다","correct":true},{"t":"태양까지의 거리로 나타낸다","mis":"SC6-2-u1-X03"},{"t":"태양이 떠 있는 시간으로 나타낸다","mis":"SC6-2-u1-X03"},{"t":"막대기의 길이로 나타낸다","mis":"SC6-2-u1-X03"}],"explanation":["높이를 각으로 나타내요.","지표면과 이루는 각이에요.","그것이 태양 고도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#3','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C3',1,'mc','auto','솔빛반 신문 ①에서 그림자 길이가 가장 짧은 시각은 언제인가요?',ARRAY['SC6-2-u1-X07','SC6-2-u1-X09']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C3","difficulty":1,"kind":"mc","stem":"솔빛반 신문 ①에서 그림자 길이가 가장 짧은 시각은 언제인가요?","options":[{"t":"12시 30분","correct":true},{"t":"15시 30분","mis":"SC6-2-u1-X07"},{"t":"9시 30분","mis":"SC6-2-u1-X07"},{"t":"14시 30분","mis":"SC6-2-u1-X09"}],"explanation":["그림자 줄을 읽어요.","가장 작은 수예요.","10.7인 12시 30분이에요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#4','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C4',1,'mc','auto','태양이 남중했다는 것은 무슨 뜻인가요?',ARRAY['SC6-2-u1-X10','SC6-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C4","difficulty":1,"kind":"mc","stem":"태양이 남중했다는 것은 무슨 뜻인가요?","options":[{"t":"태양이 정남쪽에 위치했다","correct":true},{"t":"태양이 막 떠올랐다","mis":"SC6-2-u1-X10"},{"t":"태양이 막 졌다","mis":"SC6-2-u1-X10"},{"t":"기온이 가장 높아졌다","mis":"SC6-2-u1-X09"}],"explanation":["남쪽과 관계있어요.","정남쪽이에요.","남중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#5','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C6',1,'mc','auto','태양의 남중 고도가 가장 낮은 계절은 언제인가요?',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C6","difficulty":1,"kind":"mc","stem":"태양의 남중 고도가 가장 낮은 계절은 언제인가요?","options":[{"t":"겨울","correct":true},{"t":"여름","mis":"SC6-2-u1-X13"},{"t":"봄","mis":"SC6-2-u1-X13"},{"t":"가을","mis":"SC6-2-u1-X13"}],"explanation":["태양이 낮게 떠요.","추운 계절이에요.","겨울이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#6','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C7',1,'mc','auto','태양 고도가 낮아질수록 일정한 면적의 지표면이 받는 태양 에너지양은 어떻게 되나요?',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"mc","stem":"태양 고도가 낮아질수록 일정한 면적의 지표면이 받는 태양 에너지양은 어떻게 되나요?","options":[{"t":"적어진다","correct":true},{"t":"많아진다","mis":"SC6-2-u1-X17"},{"t":"그대로이다","mis":"SC6-2-u1-X17"},{"t":"들쭉날쭉해진다","mis":"SC6-2-u1-X17"}],"explanation":["낮게 뜬 태양이에요.","빛이 약하게 닿아요.","적어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#7','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C9',1,'mc','auto','지구본 실험에서 자전축을 기울인 채 공전시켰을 때 그림자 길이는 어떠했나요?',ARRAY['SC6-2-u1-X22']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"mc","stem":"지구본 실험에서 자전축을 기울인 채 공전시켰을 때 그림자 길이는 어떠했나요?","options":[{"t":"위치에 따라 달라졌다","correct":true},{"t":"네 위치에서 모두 같았다","mis":"SC6-2-u1-X22"},{"t":"그림자가 생기지 않았다","mis":"SC6-2-u1-X22"},{"t":"전등을 끄자 길어졌다","mis":"SC6-2-u1-X22"}],"explanation":["기울인 채를 떠올려요.","0.8, 3.5처럼 달랐어요.","위치마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#8','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C11',1,'mc','auto','태양을 따라 자동으로 방향과 각도를 움직이는 발전기를 무엇이라고 하나요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C11","difficulty":1,"kind":"mc","stem":"태양을 따라 자동으로 방향과 각도를 움직이는 발전기를 무엇이라고 하나요?","options":[{"t":"추적형 태양광 발전기","correct":true},{"t":"고정형 태양광 발전기","mis":"SC6-2-u1-X24"},{"t":"햇빛 지도","mis":"SC6-2-u1-X24"},{"t":"태양 고도 측정기","mis":"SC6-2-u1-X24"}],"explanation":["태양을 따라가요.","쫓아간다는 말이 들어가요.","추적형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#9','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C3',2,'mc','auto','솔빛반 신문 ①에서 태양 고도가 가장 높은 시각은 언제인가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X06']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C3","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ①에서 태양 고도가 가장 높은 시각은 언제인가요?","options":[{"t":"12시 30분","correct":true},{"t":"14시 30분","mis":"SC6-2-u1-X09"},{"t":"9시 30분","mis":"SC6-2-u1-X06"},{"t":"15시 30분","mis":"SC6-2-u1-X06"}],"explanation":["태양 고도 줄을 읽어요.","가장 큰 수예요.","43°인 12시 30분이에요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#10','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C5',2,'mc','auto','하루 동안 태양 고도를 잴 때 측정기를 어디에 두어야 하나요?',ARRAY['SC6-2-u1-X12']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C5","difficulty":2,"kind":"mc","stem":"하루 동안 태양 고도를 잴 때 측정기를 어디에 두어야 하나요?","options":[{"t":"태양 빛이 잘 드는 평평한 곳","correct":true},{"t":"그늘진 비탈길","mis":"SC6-2-u1-X12"},{"t":"창문을 닫은 교실 책상 위","mis":"SC6-2-u1-X12"},{"t":"물웅덩이 옆 기울어진 땅","mis":"SC6-2-u1-X12"}],"explanation":["그림자가 잘 생겨야 해요.","기울면 각이 틀려요.","햇빛 드는 평평한 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#11','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C6',2,'mc','auto','솔빛반 신문 ②에서 남중 고도 그래프와 낮의 길이 그래프의 공통점으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X14','SC6-2-u1-X13']::text[],false,'{"seq":11,"concept":"SC6-2-u1-C6","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ②에서 남중 고도 그래프와 낮의 길이 그래프의 공통점으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 그래프 모두 6월에 가장 높고 12월에 가장 낮다","correct":true},{"t":"남중 고도는 6월, 낮의 길이는 12월에 가장 높다","mis":"SC6-2-u1-X14"},{"t":"두 그래프는 서로 반대 모양이다","mis":"SC6-2-u1-X14"},{"t":"두 그래프 모두 3월에 가장 높다","mis":"SC6-2-u1-X13"}],"explanation":["두 줄을 견줘요.","6월과 12월이에요.","꼭짓점이 겹쳐요."],"asset":{"type":"passage","lines":["우리 고장에서 매월 21일 남중 고도와 낮의 길이를 조사했다.","남중 고도 그래프 — 6월에 가장 높고 12월에 가장 낮았다.","낮의 길이 그래프 — 6월에 가장 길고 12월에 가장 짧았다.","서울특별시 자료와 견주니 값이 조금 달랐다."],"title":"솔빛반 신문 ② 우리 고장 한 해 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#12','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C7',2,'mc','auto','솔빛반 신문 ③에서 빛의 세기가 더 센 것과 그때 이루는 각으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":12,"concept":"SC6-2-u1-C7","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ③에서 빛의 세기가 더 센 것과 그때 이루는 각으로 알맞은 것은 어느 것인가요?","options":[{"t":"㉠ — 이루는 각이 크다","correct":true},{"t":"㉡ — 이루는 각이 크다","mis":"SC6-2-u1-X17"},{"t":"㉠ — 이루는 각이 작다","mis":"SC6-2-u1-X17"},{"t":"㉠과 ㉡이 같다","mis":"SC6-2-u1-X17"}],"explanation":["1,250과 870을 견줘요.","㉠이 더 세요.","그림자가 짧으면 각이 커요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 20 cm로 같게 했다.","㉠ 막대 그림자가 짧을 때 — 빛의 세기 예 1,250","㉡ 막대 그림자가 길 때 — 빛의 세기 예 870"],"title":"솔빛반 신문 ③ 우리 모둠 손전등 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#13','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C8',2,'mc','auto','여름이 겨울보다 더운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X19','SC6-2-u1-X17']::text[],false,'{"seq":13,"concept":"SC6-2-u1-C8","difficulty":2,"kind":"mc","stem":"여름이 겨울보다 더운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여름에는 남중 고도가 높아 일정한 면적의 지표면이 받는 태양 에너지양이 많기 때문에","correct":true},{"t":"여름에는 남중 고도가 낮기 때문에","mis":"SC6-2-u1-X19"},{"t":"여름에는 태양 에너지양이 적기 때문에","mis":"SC6-2-u1-X17"},{"t":"여름과 겨울의 태양 에너지양이 같기 때문에","mis":"SC6-2-u1-X17"}],"explanation":["여름 남중 고도는 높아요.","태양 에너지양이 많아요.","그래서 더워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#14','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C9',2,'mc','auto','솔빛반 신문 ④에서 자전축을 세운 채 공전할 때의 결과로 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u1-X22','SC6-2-u1-X21','SC6-2-u1-X20']::text[],false,'{"seq":14,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ④에서 자전축을 세운 채 공전할 때의 결과로 알 수 있는 것은 어느 것인가요?","options":[{"t":"태양의 남중 고도가 달라지지 않아 계절의 변화가 생기지 않는다","correct":true},{"t":"위치마다 남중 고도가 크게 달라진다","mis":"SC6-2-u1-X22"},{"t":"계절의 변화가 더 뚜렷해진다","mis":"SC6-2-u1-X21"},{"t":"전등과의 거리가 달라진다","mis":"SC6-2-u1-X20"}],"explanation":["세운 채 줄을 읽어요.","모두 1.5예요.","계절이 생기지 않아요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 했다.","자전축을 세운 채 — 가·나·다·라 모두 그림자 예 1.5 cm","자전축을 기울인 채 — 가 1.5 · 나 0.9 · 다 1.5 · 라 3.2(cm, 예)"],"title":"솔빛반 신문 ④ 우리 모둠 지구본 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#15','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C10',2,'mc','auto','솔빛반 신문 ⑦에서 「축제는 해가 지기 전에 마칩니다」라고 안내한 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X13','SC6-2-u1-X23']::text[],false,'{"seq":15,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ⑦에서 「축제는 해가 지기 전에 마칩니다」라고 안내한 까닭은 무엇인가요?","options":[{"t":"겨울에는 낮의 길이가 짧기 때문에","correct":true},{"t":"겨울에는 낮의 길이가 길기 때문에","mis":"SC6-2-u1-X13"},{"t":"겨울에는 남중 고도가 높기 때문에","mis":"SC6-2-u1-X13"},{"t":"저수지가 작기 때문에","mis":"SC6-2-u1-X23"}],"explanation":["과학 정보를 읽어요.","낮이 짧아요.","해가 일찍 져요."],"asset":{"type":"passage","lines":["솔빛 겨울 빙어 축제 — 1월 ○일~○일, ○○ 저수지","과학 정보 — 남중 고도가 낮고 낮의 길이가 짧으며 기온이 낮다.","안내 — 따뜻한 옷을 입고 오세요. 축제는 해가 지기 전에 마칩니다."],"title":"솔빛반 신문 ⑦ 우리 모둠 축제 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#16','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C11',2,'mc','auto','솔빛반 신문 ⑧의 발전기가 태양을 따라 방향과 각도를 바꾸는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X24','SC6-2-u1-X06']::text[],false,'{"seq":16,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ⑧의 발전기가 태양을 따라 방향과 각도를 바꾸는 까닭은 무엇인가요?","options":[{"t":"태양과 발전기의 면이 이루는 각을 수직으로 유지해 태양 에너지를 많이 받으려고","correct":true},{"t":"발전기를 예쁘게 보이게 하려고","mis":"SC6-2-u1-X24"},{"t":"태양 고도가 하루 내내 같아서","mis":"SC6-2-u1-X06"},{"t":"비를 피하려고","mis":"SC6-2-u1-X24"}],"explanation":["태양 고도가 바뀌어요.","따라가며 정면으로 받아요.","수직을 유지해요."],"asset":{"type":"passage","lines":["견학한 발전소의 발전기는 태양을 따라 방향과 각도를 바꾼다.","발전소를 세울 곳은 햇빛 지도를 보고 골랐다고 한다.","만든 전기는 마을의 학교와 집으로 보낸다."],"title":"솔빛반 신문 ⑧ 태양광 발전소 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#17','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C3',3,'mc','auto','솔빛반 신문 ①에서 기온 그래프의 꼭짓점과 태양 고도 그래프의 꼭짓점을 견주면 어떠한가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X08']::text[],false,'{"seq":17,"concept":"SC6-2-u1-C3","difficulty":3,"kind":"mc","stem":"솔빛반 신문 ①에서 기온 그래프의 꼭짓점과 태양 고도 그래프의 꼭짓점을 견주면 어떠한가요?","options":[{"t":"기온의 꼭짓점이 태양 고도의 꼭짓점보다 오른쪽(늦은 시각)에 있다","correct":true},{"t":"두 꼭짓점이 같은 시각에 겹친다","mis":"SC6-2-u1-X09"},{"t":"기온의 꼭짓점이 더 왼쪽(이른 시각)에 있다","mis":"SC6-2-u1-X09"},{"t":"기온 그래프에는 꼭짓점이 없다","mis":"SC6-2-u1-X08"}],"explanation":["12시 30분과 14시 30분이에요.","기온이 늦어요.","오른쪽에 있어요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#18','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C6',3,'mc','auto','우리 고장에서 6월부터 12월까지 낮의 길이는 어떻게 달라질까요?',ARRAY['SC6-2-u1-X15','SC6-2-u1-X13','SC6-2-u1-X14']::text[],false,'{"seq":18,"concept":"SC6-2-u1-C6","difficulty":3,"kind":"mc","stem":"우리 고장에서 6월부터 12월까지 낮의 길이는 어떻게 달라질까요?","options":[{"t":"조금씩 이어서 짧아진다","correct":true},{"t":"한 달씩 뚝뚝 끊겨 짧아진다","mis":"SC6-2-u1-X15"},{"t":"점점 길어진다","mis":"SC6-2-u1-X13"},{"t":"그대로이다","mis":"SC6-2-u1-X14"}],"explanation":["6월이 가장 길어요.","12월이 가장 짧아요.","이어서 짧아져요."],"asset":{"type":"passage","lines":["우리 고장에서 매월 21일 남중 고도와 낮의 길이를 조사했다.","남중 고도 그래프 — 6월에 가장 높고 12월에 가장 낮았다.","낮의 길이 그래프 — 6월에 가장 길고 12월에 가장 짧았다.","서울특별시 자료와 견주니 값이 조금 달랐다."],"title":"솔빛반 신문 ② 우리 고장 한 해 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#19','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C7',3,'mc','auto','솔빛반 신문 ③의 ㉠과 ㉡을 계절로 옮기면 어떻게 짝지을 수 있나요?',ARRAY['SC6-2-u1-X19','SC6-2-u1-X17']::text[],false,'{"seq":19,"concept":"SC6-2-u1-C7","difficulty":3,"kind":"mc","stem":"솔빛반 신문 ③의 ㉠과 ㉡을 계절로 옮기면 어떻게 짝지을 수 있나요?","options":[{"t":"㉠ 여름 한낮의 태양 — ㉡ 겨울 한낮의 태양","correct":true},{"t":"㉠ 겨울 — ㉡ 여름","mis":"SC6-2-u1-X19"},{"t":"㉠과 ㉡ 모두 여름","mis":"SC6-2-u1-X17"},{"t":"계절과 관계없다","mis":"SC6-2-u1-X17"}],"explanation":["㉠은 각이 커요.","여름 남중 고도가 높아요.","㉠ 여름, ㉡ 겨울이에요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 20 cm로 같게 했다.","㉠ 막대 그림자가 짧을 때 — 빛의 세기 예 1,250","㉡ 막대 그림자가 길 때 — 빛의 세기 예 870"],"title":"솔빛반 신문 ③ 우리 모둠 손전등 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#20','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C9',3,'mc','auto','솔빛반 신문 ⑤에서 하람의 생각을 바로잡는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X21']::text[],false,'{"seq":20,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"mc","stem":"솔빛반 신문 ⑤에서 하람의 생각을 바로잡는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"태양과의 거리는 계절에 거의 영향을 주지 않고, 여름에 더운 것은 남중 고도가 높기 때문이다","correct":true},{"t":"하람의 말이 맞다, 여름에는 태양과 가깝다","mis":"SC6-2-u1-X20"},{"t":"겨울에는 태양과 멀어져서만 춥다","mis":"SC6-2-u1-X20"},{"t":"계절은 자전축과 관계없다","mis":"SC6-2-u1-X21"}],"explanation":["선생님 말을 읽어요.","여름이 오히려 멀어요.","남중 고도가 열쇠예요."],"asset":{"type":"passage","lines":["하람 — 「여름에 더운 건 지구가 태양에 가까워지기 때문이야.」","도윤 — 「④ 실험에서 거리는 늘 같았는데도 그림자가 달라졌어.」","선생님 — 북반구는 겨울보다 여름에 태양과 오히려 더 멀어요."],"title":"솔빛반 신문 ⑤ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#21','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C2',3,'mc','auto','모둠마다 막대기 길이가 다른 측정기로 같은 시각에 태양 고도를 쟀어요. 결과로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X04']::text[],false,'{"seq":21,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"mc","stem":"모둠마다 막대기 길이가 다른 측정기로 같은 시각에 태양 고도를 쟀어요. 결과로 알맞은 것은 어느 것인가요?","options":[{"t":"그림자 길이는 달라도 태양 고도는 거의 같게 나온다","correct":true},{"t":"막대기가 긴 모둠의 태양 고도가 더 높다","mis":"SC6-2-u1-X04"},{"t":"막대기가 짧은 모둠의 태양 고도가 더 높다","mis":"SC6-2-u1-X04"},{"t":"막대기 길이가 다르면 잴 수 없다","mis":"SC6-2-u1-X04"}],"explanation":["태양 빛은 평행하게 와요.","그림자가 함께 달라져요.","각은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#22','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C11',3,'mc','auto','추적형 태양광 발전기, 햇빛 지도, 계절 축제 안내 자료의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X24','SC6-2-u1-X23','SC6-2-u1-X20']::text[],false,'{"seq":22,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"mc","stem":"추적형 태양광 발전기, 햇빛 지도, 계절 축제 안내 자료의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"태양 고도가 달라진다는 과학적 사실을 생활에 활용했다","correct":true},{"t":"모두 새롭고 비싼 기술이다","mis":"SC6-2-u1-X24"},{"t":"모두 과학 정보 없이 꾸밈만 했다","mis":"SC6-2-u1-X23"},{"t":"모두 태양과의 거리를 이용했다","mis":"SC6-2-u1-X20"}],"explanation":["셋의 바탕을 찾아요.","태양 고도가 바뀌어요.","과학적 사실을 활용했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#23','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C3',4,'mc','auto','솔빛반 신문 ①을 가장 잘 해석한 것은 어느 것인가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X07','SC6-2-u1-X08']::text[],false,'{"seq":23,"concept":"SC6-2-u1-C3","difficulty":4,"kind":"mc","stem":"솔빛반 신문 ①을 가장 잘 해석한 것은 어느 것인가요?","options":[{"t":"태양 고도가 높아지면 그림자는 짧아지고 기온은 높아지지만, 기온은 태양 고도보다 늦은 시각에 가장 높다","correct":true},{"t":"세 가지는 모두 12시 30분에 가장 크다","mis":"SC6-2-u1-X09"},{"t":"태양 고도가 높아지면 그림자도 길어진다","mis":"SC6-2-u1-X07"},{"t":"기온은 태양 고도와 관계없이 아침에 가장 높다","mis":"SC6-2-u1-X08"}],"explanation":["세 줄을 함께 봐요.","그림자는 반대예요.","기온은 늦게 가장 높아요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#24','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C3',4,'essay','teacher','솔빛반 신문 ①을 보고 하루 동안 태양 고도·그림자 길이·기온의 변화를 쓰고, 세 가지의 관계와 「가장 높은 때」에 대해 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u1-C3","difficulty":4,"kind":"essay","stem":"솔빛반 신문 ①을 보고 하루 동안 태양 고도·그림자 길이·기온의 변화를 쓰고, 세 가지의 관계와 「가장 높은 때」에 대해 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 태양 고도는 12시 30분에 43°로 가장 높고 그 전에는 높아졌다가 그 뒤에는 낮아진다. 그림자 길이는 12시 30분에 10.7 cm로 가장 짧고 그 전후로 길어진다. 기온은 14시 30분에 20.9 °C로 가장 높다. 태양 고도가 높아지면 그림자 길이는 짧아지고 기온은 높아지지만, 태양 고도가 가장 높은 시각과 기온이 가장 높은 시각에는 차이가 있다.","scoring_points":["세 가지의 하루 변화를 썼는가","태양 고도와 그림자·기온의 관계를 썼는가","두 꼭짓점 시각에 차이가 있다는 점을 썼는가"]},"explanation":["세 줄을 읽어요.","관계를 써요.","가장 높은 때를 견줘요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_a#25','sci',6,2,'u1','','g6_2_sci_u1_review_a','unit_review','SC6-2-u1-C10',4,'essay','teacher','솔빛반 신문 ⑦을 여름 축제 안내 자료로 바꾸어 쓰세요. 여름의 남중 고도·낮의 길이·기온을 쓰고, 그에 맞는 준비물·옷차림·운영 시간을 안내하세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u1-C10","difficulty":4,"kind":"essay","stem":"솔빛반 신문 ⑦을 여름 축제 안내 자료로 바꾸어 쓰세요. 여름의 남중 고도·낮의 길이·기온을 쓰고, 그에 맞는 준비물·옷차림·운영 시간을 안내하세요.","answer_guide":{"answer":"예: 솔빛 여름 수박 축제 — 여름에는 태양의 남중 고도가 높고 낮의 길이가 길며 기온이 높다. 남중 고도가 높아 태양 빛이 강하므로 색안경과 자외선 차단제, 모자를 준비하고, 기온이 높으니 시원한 옷을 입고 물을 충분히 마신다. 낮의 길이가 길어 축제는 오전 10시부터 오후 7시까지 연다.","scoring_points":["여름의 세 과학 정보를 바르게 썼는가","준비물·옷차림을 과학 정보와 이었는가","운영 시간을 낮의 길이와 이었는가"]},"explanation":["여름으로 바꿔요.","세 정보를 써요.","안내를 이어요."],"asset":{"type":"passage","lines":["솔빛 겨울 빙어 축제 — 1월 ○일~○일, ○○ 저수지","과학 정보 — 남중 고도가 낮고 낮의 길이가 짧으며 기온이 낮다.","안내 — 따뜻한 옷을 입고 오세요. 축제는 해가 지기 전에 마칩니다."],"title":"솔빛반 신문 ⑦ 우리 모둠 축제 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#1','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C1',1,'mc','auto','눈이 많이 내려 눈썰매를 타는 계절은 언제인가요?',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"mc","stem":"눈이 많이 내려 눈썰매를 타는 계절은 언제인가요?","options":[{"t":"겨울","correct":true},{"t":"봄","mis":"SC6-2-u1-X01"},{"t":"여름","mis":"SC6-2-u1-X01"},{"t":"가을","mis":"SC6-2-u1-X01"}],"explanation":["눈을 떠올려요.","가장 추운 계절이에요.","겨울이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#2','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C2',1,'sa','auto','태양이 지표면과 이루는 각을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"sa","stem":"태양이 지표면과 이루는 각을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["태양고도","태양 고도"],"explanation":["태양의 높이예요.","각으로 나타내요.","태양 고도예요."],"mis":"SC6-2-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#3','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C3',1,'mc','auto','하루 동안 태양 고도가 낮아지면 기온은 대체로 어떻게 되나요?',ARRAY['SC6-2-u1-X08']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C3","difficulty":1,"kind":"mc","stem":"하루 동안 태양 고도가 낮아지면 기온은 대체로 어떻게 되나요?","options":[{"t":"낮아진다","correct":true},{"t":"높아진다","mis":"SC6-2-u1-X08"},{"t":"그대로이다","mis":"SC6-2-u1-X08"},{"t":"태양 고도와 관계없이 들쭉날쭉하다","mis":"SC6-2-u1-X08"}],"explanation":["태양 고도와 기온은 닮았어요.","함께 내려가요.","낮아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#4','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C4',1,'sa','auto','태양이 남중했을 때의 태양 고도를 무엇이라고 하나요? (태양의 □□ 고도)','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u1-C4","difficulty":1,"kind":"sa","stem":"태양이 남중했을 때의 태양 고도를 무엇이라고 하나요? (태양의 □□ 고도)","answer":["남중","남중 고도","태양의 남중 고도"],"explanation":["정남쪽에 온 때예요.","두 글자를 넣어요.","남중 고도예요."],"mis":"SC6-2-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#5','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C6',1,'mc','auto','낮의 길이가 가장 긴 계절은 언제인가요?',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C6","difficulty":1,"kind":"mc","stem":"낮의 길이가 가장 긴 계절은 언제인가요?","options":[{"t":"여름","correct":true},{"t":"겨울","mis":"SC6-2-u1-X13"},{"t":"봄","mis":"SC6-2-u1-X13"},{"t":"가을","mis":"SC6-2-u1-X13"}],"explanation":["해가 오래 떠 있어요.","더운 계절이에요.","여름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#6','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C7',1,'match','auto','손전등 실험에서 쓴 것과 나타내는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"match","stem":"손전등 실험에서 쓴 것과 나타내는 것을 알맞게 이으세요.","pairs":[{"l":"손전등","r":"태양"},{"l":"스마트 기기","r":"지표면"},{"l":"이루는 각","r":"태양 고도"}],"mis":"SC6-2-u1-X18","explanation":["빛을 내는 것은 태양이에요.","받는 것은 지표면이에요.","각은 태양 고도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#7','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C9',1,'sa','auto','지구가 태양을 중심으로 일 년에 한 바퀴씩 도는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"sa","stem":"지구가 태양을 중심으로 일 년에 한 바퀴씩 도는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["공전"],"explanation":["태양 둘레를 돌아요.","일 년에 한 바퀴예요.","공전이에요."],"mis":"SC6-2-u1-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#8','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C10',1,'mc','auto','계절 축제 안내 자료에 담을 과학 정보가 아닌 것은 어느 것인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C10","difficulty":1,"kind":"mc","stem":"계절 축제 안내 자료에 담을 과학 정보가 아닌 것은 어느 것인가요?","options":[{"t":"축제장의 주차 요금","correct":true},{"t":"태양의 남중 고도","mis":"SC6-2-u1-X23"},{"t":"낮의 길이","mis":"SC6-2-u1-X23"},{"t":"기온","mis":"SC6-2-u1-X23"}],"explanation":["이 단원에서 배운 것을 담아요.","세 가지가 있어요.","주차 요금은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#9','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C3',2,'mc','auto','솔빛반 신문 ①에서 기온이 가장 높은 시각은 언제인가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X08']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C3","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ①에서 기온이 가장 높은 시각은 언제인가요?","options":[{"t":"14시 30분","correct":true},{"t":"12시 30분","mis":"SC6-2-u1-X09"},{"t":"9시 30분","mis":"SC6-2-u1-X08"},{"t":"15시 30분","mis":"SC6-2-u1-X08"}],"explanation":["기온 줄을 읽어요.","가장 큰 수예요.","20.9인 14시 30분이에요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#10','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C5',2,'mc','auto','세 가지 측정값을 꺾은선그래프로 나타낼 때 알맞은 방법은 어느 것인가요?',ARRAY['SC6-2-u1-X12']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C5","difficulty":2,"kind":"mc","stem":"세 가지 측정값을 꺾은선그래프로 나타낼 때 알맞은 방법은 어느 것인가요?","options":[{"t":"가로축에 측정 시각을 일정한 간격으로 쓰고 세 그래프를 같은 가로축에 맞추어 견준다","correct":true},{"t":"그래프마다 가로축의 시각을 다르게 쓴다","mis":"SC6-2-u1-X12"},{"t":"세 그래프를 모두 같은 색으로 그린다","mis":"SC6-2-u1-X12"},{"t":"점과 점 사이를 둥근 곡선으로만 잇는다","mis":"SC6-2-u1-X12"}],"explanation":["가로축은 시각이에요.","일정한 간격이에요.","가로축을 맞춰 겹쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#11','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C6',2,'mc','auto','솔빛반 신문 ②에서 서울특별시 자료와 값이 조금 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X16']::text[],false,'{"seq":11,"concept":"SC6-2-u1-C6","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ②에서 서울특별시 자료와 값이 조금 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"태양의 남중 고도와 낮의 길이는 지역마다 차이가 있기 때문에","correct":true},{"t":"우리 고장 조사가 모두 틀렸기 때문에","mis":"SC6-2-u1-X16"},{"t":"같은 날이면 어디서나 값이 같아야 하기 때문에","mis":"SC6-2-u1-X16"},{"t":"조사한 달이 서로 다르기 때문에","mis":"SC6-2-u1-X16"}],"explanation":["조사한 곳이 달라요.","지역마다 달라요.","차이가 있어요."],"asset":{"type":"passage","lines":["우리 고장에서 매월 21일 남중 고도와 낮의 길이를 조사했다.","남중 고도 그래프 — 6월에 가장 높고 12월에 가장 낮았다.","낮의 길이 그래프 — 6월에 가장 길고 12월에 가장 짧았다.","서울특별시 자료와 견주니 값이 조금 달랐다."],"title":"솔빛반 신문 ② 우리 고장 한 해 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#12','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C7',2,'mc','auto','솔빛반 신문 ③에서 거리를 20 cm로 같게 한 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X18']::text[],false,'{"seq":12,"concept":"SC6-2-u1-C7","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ③에서 거리를 20 cm로 같게 한 까닭은 무엇인가요?","options":[{"t":"손전등의 각만 다르게 해서 각에 따른 빛의 세기를 비교하려고","correct":true},{"t":"거리가 멀수록 각이 커지기 때문에","mis":"SC6-2-u1-X18"},{"t":"스마트 기기 화면이 잘 보이게 하려고","mis":"SC6-2-u1-X18"},{"t":"막대 그림자를 없애려고","mis":"SC6-2-u1-X18"}],"explanation":["바꿀 것은 하나예요.","각만 바꿔요.","나머지는 같게 해요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 20 cm로 같게 했다.","㉠ 막대 그림자가 짧을 때 — 빛의 세기 예 1,250","㉡ 막대 그림자가 길 때 — 빛의 세기 예 870"],"title":"솔빛반 신문 ③ 우리 모둠 손전등 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#13','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C8',2,'mc','auto','솔빛반 신문 ⑥에서 ㉠과 ㉡에 알맞은 계절을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":13,"concept":"SC6-2-u1-C8","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ⑥에서 ㉠과 ㉡에 알맞은 계절을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉠ 여름 — ㉡ 겨울","correct":true},{"t":"㉠ 겨울 — ㉡ 여름","mis":"SC6-2-u1-X13"},{"t":"㉠ 봄 — ㉡ 가을","mis":"SC6-2-u1-X13"},{"t":"㉠ 여름 — ㉡ 여름","mis":"SC6-2-u1-X13"}],"explanation":["높이 뜬 태양은 처마에 가려요.","낮게 뜬 태양은 깊이 들어와요.","㉠ 여름, ㉡ 겨울이에요."],"asset":{"type":"passage","lines":["한옥 처마는 집 안으로 들어오는 태양 빛의 양을 조절한다.","㉠ 계절 — 태양 빛이 처마에 가려져 집 안이 시원하다.","㉡ 계절 — 태양 빛이 처마 밑으로 깊이 들어와 집 안이 따뜻하다."],"title":"솔빛반 신문 ⑥ 한옥 처마 탐방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#14','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C9',2,'mc','auto','솔빛반 신문 ④에서 자전축을 기울인 채 공전할 때 태양의 남중 고도가 가장 낮은 위치는 어디인가요?',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":14,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ④에서 자전축을 기울인 채 공전할 때 태양의 남중 고도가 가장 낮은 위치는 어디인가요?","options":[{"t":"라","correct":true},{"t":"나","mis":"SC6-2-u1-X07"},{"t":"가","mis":"SC6-2-u1-X07"},{"t":"다","mis":"SC6-2-u1-X07"}],"explanation":["그림자가 가장 긴 곳이에요.","3.2는 라예요.","그림자가 길면 낮게 떠요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 했다.","자전축을 세운 채 — 가·나·다·라 모두 그림자 예 1.5 cm","자전축을 기울인 채 — 가 1.5 · 나 0.9 · 다 1.5 · 라 3.2(cm, 예)"],"title":"솔빛반 신문 ④ 우리 모둠 지구본 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#15','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C10',2,'mc','auto','솔빛반 신문 ⑦에 더할 안내로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X23','SC6-2-u1-X13']::text[],false,'{"seq":15,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ⑦에 더할 안내로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"장갑과 목도리를 준비하고 따뜻한 음료를 챙기세요","correct":true},{"t":"자외선 차단제와 시원한 옷을 준비하세요","mis":"SC6-2-u1-X23"},{"t":"그늘막을 많이 준비했어요","mis":"SC6-2-u1-X13"},{"t":"운영 시간을 오후 9시까지 늘렸어요","mis":"SC6-2-u1-X13"}],"explanation":["겨울 축제예요.","기온이 낮아요.","따뜻하게 준비해요."],"asset":{"type":"passage","lines":["솔빛 겨울 빙어 축제 — 1월 ○일~○일, ○○ 저수지","과학 정보 — 남중 고도가 낮고 낮의 길이가 짧으며 기온이 낮다.","안내 — 따뜻한 옷을 입고 오세요. 축제는 해가 지기 전에 마칩니다."],"title":"솔빛반 신문 ⑦ 우리 모둠 축제 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#16','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C11',2,'mc','auto','솔빛반 신문 ⑧에서 햇빛 지도를 보고 발전소 자리를 고른 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":16,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ⑧에서 햇빛 지도를 보고 발전소 자리를 고른 까닭은 무엇인가요?","options":[{"t":"태양 에너지를 많이 받을 수 있는 장소를 찾으려고","correct":true},{"t":"그늘이 많은 장소를 찾으려고","mis":"SC6-2-u1-X24"},{"t":"비가 자주 오는 장소를 찾으려고","mis":"SC6-2-u1-X24"},{"t":"발전기 값이 싼 곳을 찾으려고","mis":"SC6-2-u1-X24"}],"explanation":["햇빛 지도가 알려 주는 것을 떠올려요.","장소별 태양 에너지양이에요.","많이 받는 곳을 골라요."],"asset":{"type":"passage","lines":["견학한 발전소의 발전기는 태양을 따라 방향과 각도를 바꾼다.","발전소를 세울 곳은 햇빛 지도를 보고 골랐다고 한다.","만든 전기는 마을의 학교와 집으로 보낸다."],"title":"솔빛반 신문 ⑧ 태양광 발전소 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#17','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C4',3,'mc','auto','솔빛반 신문 ①과 같은 시각에 다음 날 다시 재면 태양 고도는 어떻게 될까요?',ARRAY['SC6-2-u1-X11']::text[],false,'{"seq":17,"concept":"SC6-2-u1-C4","difficulty":3,"kind":"mc","stem":"솔빛반 신문 ①과 같은 시각에 다음 날 다시 재면 태양 고도는 어떻게 될까요?","options":[{"t":"날마다 조금씩 다른 값이 나온다","correct":true},{"t":"똑같은 값이 나온다","mis":"SC6-2-u1-X11"},{"t":"전혀 다른 값이 나와 규칙이 없다","mis":"SC6-2-u1-X11"},{"t":"그림자 길이만 달라진다","mis":"SC6-2-u1-X11"}],"explanation":["뜨고 지는 시각을 생각해요.","남중 고도도 매일 바뀌어요.","조금씩 달라요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#18','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C6',3,'mc','auto','서울특별시와 다른 고장에서 같은 날 조사한 남중 고도가 서로 달랐어요. 가장 알맞은 해석은 어느 것인가요?',ARRAY['SC6-2-u1-X16','SC6-2-u1-X14']::text[],false,'{"seq":18,"concept":"SC6-2-u1-C6","difficulty":3,"kind":"mc","stem":"서울특별시와 다른 고장에서 같은 날 조사한 남중 고도가 서로 달랐어요. 가장 알맞은 해석은 어느 것인가요?","options":[{"t":"남중 고도는 지역마다 차이가 있으므로 두 자료 모두 맞을 수 있다","correct":true},{"t":"한 곳의 조사는 반드시 틀렸다","mis":"SC6-2-u1-X16"},{"t":"같은 날이면 어디서나 같아야 한다","mis":"SC6-2-u1-X16"},{"t":"남중 고도는 아무 규칙이 없다","mis":"SC6-2-u1-X14"}],"explanation":["지역이 달라요.","지역마다 차이가 있어요.","둘 다 맞을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#19','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C8',3,'mc','auto','솔빛반 신문 ⑥에서 여름에 처마가 태양 빛을 가릴 수 있는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X13','SC6-2-u1-X20','SC6-2-u1-X19']::text[],false,'{"seq":19,"concept":"SC6-2-u1-C8","difficulty":3,"kind":"mc","stem":"솔빛반 신문 ⑥에서 여름에 처마가 태양 빛을 가릴 수 있는 까닭은 무엇인가요?","options":[{"t":"여름에는 남중 고도가 높아 태양 빛이 위에서 비스듬히 내려와 처마에 가려지기 때문에","correct":true},{"t":"여름에는 남중 고도가 낮아 빛이 깊이 들어오기 때문에","mis":"SC6-2-u1-X13"},{"t":"여름에는 태양이 지구와 가까워지기 때문에","mis":"SC6-2-u1-X20"},{"t":"처마가 계절마다 길이를 바꾸기 때문에","mis":"SC6-2-u1-X19"}],"explanation":["여름 태양은 높이 떠요.","위에서 내려와요.","처마에 가려요."],"asset":{"type":"passage","lines":["한옥 처마는 집 안으로 들어오는 태양 빛의 양을 조절한다.","㉠ 계절 — 태양 빛이 처마에 가려져 집 안이 시원하다.","㉡ 계절 — 태양 빛이 처마 밑으로 깊이 들어와 집 안이 따뜻하다."],"title":"솔빛반 신문 ⑥ 한옥 처마 탐방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#20','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C9',3,'mc','auto','솔빛반 신문 ⑤에서 도윤이 든 근거가 하람의 생각을 반박할 수 있는 까닭은 무엇인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X22']::text[],false,'{"seq":20,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"mc","stem":"솔빛반 신문 ⑤에서 도윤이 든 근거가 하람의 생각을 반박할 수 있는 까닭은 무엇인가요?","options":[{"t":"거리를 바꾸지 않았는데도 자전축 기울기만으로 그림자 길이(남중 고도)가 달라졌기 때문에","correct":true},{"t":"거리를 바꾸자 그림자가 달라졌기 때문에","mis":"SC6-2-u1-X20"},{"t":"자전축을 세우자 그림자가 달라졌기 때문에","mis":"SC6-2-u1-X22"},{"t":"지구본을 돌리지 않았기 때문에","mis":"SC6-2-u1-X22"}],"explanation":["④ 실험을 떠올려요.","거리는 그대로였어요.","기울기만으로 달라졌어요."],"asset":{"type":"passage","lines":["하람 — 「여름에 더운 건 지구가 태양에 가까워지기 때문이야.」","도윤 — 「④ 실험에서 거리는 늘 같았는데도 그림자가 달라졌어.」","선생님 — 북반구는 겨울보다 여름에 태양과 오히려 더 멀어요."],"title":"솔빛반 신문 ⑤ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#21','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C2',3,'mc','auto','수수깡과 실 측정기로 잰 값이 친구들과 크게 달랐어요. 가장 먼저 살펴볼 것은 어느 것인가요?',ARRAY['SC6-2-u1-X05','SC6-2-u1-X04']::text[],false,'{"seq":21,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"mc","stem":"수수깡과 실 측정기로 잰 값이 친구들과 크게 달랐어요. 가장 먼저 살펴볼 것은 어느 것인가요?","options":[{"t":"수수깡이 수직으로 꽂혔는지와 실을 그림자 끝에 맞추었는지","correct":true},{"t":"수수깡의 색깔","mis":"SC6-2-u1-X05"},{"t":"막대기가 충분히 긴지","mis":"SC6-2-u1-X04"},{"t":"각도기의 크기","mis":"SC6-2-u1-X05"}],"explanation":["측정기 만들기를 떠올려요.","수직이 중요해요.","실을 그림자 끝에 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#22','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C10',3,'mc','auto','가을 단풍 축제 안내 자료에 「여름보다 낮의 길이가 짧아요」라고 쓴 것은 어떤 과학적 사실과 이어지나요?',ARRAY['SC6-2-u1-X13','SC6-2-u1-X14','SC6-2-u1-X20']::text[],false,'{"seq":22,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"mc","stem":"가을 단풍 축제 안내 자료에 「여름보다 낮의 길이가 짧아요」라고 쓴 것은 어떤 과학적 사실과 이어지나요?","options":[{"t":"가을에는 여름보다 태양의 남중 고도가 낮아져 낮의 길이가 짧아진다","correct":true},{"t":"가을에는 남중 고도가 가장 높다","mis":"SC6-2-u1-X13"},{"t":"낮의 길이는 계절과 관계없다","mis":"SC6-2-u1-X14"},{"t":"가을에는 지구가 태양에서 멀어진다","mis":"SC6-2-u1-X20"}],"explanation":["남중 고도와 낮의 길이예요.","가을은 여름보다 낮게 떠요.","그래서 낮이 짧아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#23','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C6',4,'mc','auto','「계절의 변화」 단원의 흐름을 가장 바르게 이은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X19','SC6-2-u1-X21']::text[],false,'{"seq":23,"concept":"SC6-2-u1-C6","difficulty":4,"kind":"mc","stem":"「계절의 변화」 단원의 흐름을 가장 바르게 이은 것은 어느 것인가요?","options":[{"t":"자전축이 기울어진 채 공전 → 계절에 따라 남중 고도가 달라짐 → 낮의 길이·태양 에너지양이 달라짐 → 기온이 달라짐","correct":true},{"t":"태양과의 거리가 달라짐 → 기온이 달라짐","mis":"SC6-2-u1-X20"},{"t":"기온이 달라짐 → 남중 고도가 달라짐 → 자전축이 기울어짐","mis":"SC6-2-u1-X19"},{"t":"자전축이 수직 → 남중 고도가 달라짐 → 계절이 생김","mis":"SC6-2-u1-X21"}],"explanation":["원인부터 시작해요.","남중 고도를 거쳐요.","기온이 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#24','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C6',4,'essay','teacher','솔빛반 신문 ②를 보고 계절에 따른 태양의 남중 고도와 낮의 길이의 변화를 쓰고, 두 가지의 관계와 우리 고장 자료가 서울 자료와 다른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u1-C6","difficulty":4,"kind":"essay","stem":"솔빛반 신문 ②를 보고 계절에 따른 태양의 남중 고도와 낮의 길이의 변화를 쓰고, 두 가지의 관계와 우리 고장 자료가 서울 자료와 다른 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리 고장에서 태양의 남중 고도는 6월에 가장 높고 12월에 가장 낮으며, 낮의 길이도 6월에 가장 길고 12월에 가장 짧다. 태양의 남중 고도가 높아질수록 태양이 지평선 위로 떠 있는 시간이 길어져 낮의 길이가 길어진다. 남중 고도와 낮의 길이는 지역마다 차이가 있어서 서울 자료와 값이 조금 다르다.","scoring_points":["여름·겨울의 남중 고도와 낮의 길이를 썼는가","두 가지의 관계를 썼는가","지역마다 차이가 있다는 까닭을 썼는가"]},"explanation":["6월과 12월을 써요.","관계를 한 문장으로 써요.","지역 차이를 써요."],"asset":{"type":"passage","lines":["우리 고장에서 매월 21일 남중 고도와 낮의 길이를 조사했다.","남중 고도 그래프 — 6월에 가장 높고 12월에 가장 낮았다.","낮의 길이 그래프 — 6월에 가장 길고 12월에 가장 짧았다.","서울특별시 자료와 견주니 값이 조금 달랐다."],"title":"솔빛반 신문 ② 우리 고장 한 해 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_b#25','sci',6,2,'u1','','g6_2_sci_u1_review_b','unit_review','SC6-2-u1-C11',4,'essay','teacher','솔빛반 신문 ⑧의 발전소에 쓰인 두 기술이 각각 어떤 일을 하는지 쓰고, 두 기술이 어떤 과학적 사실에서 나왔는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u1-C11","difficulty":4,"kind":"essay","stem":"솔빛반 신문 ⑧의 발전소에 쓰인 두 기술이 각각 어떤 일을 하는지 쓰고, 두 기술이 어떤 과학적 사실에서 나왔는지 쓰세요.","answer_guide":{"answer":"예: 추적형 태양광 발전기는 태양을 따라 방향과 각도를 움직여 태양과 발전기의 면이 이루는 각을 수직으로 유지하므로 전기를 더 많이 만든다. 햇빛 지도는 장소별로 일 년 동안 받을 수 있는 태양 에너지양을 알려 주어 발전소 자리를 고르게 한다. 두 기술은 태양 고도가 달라지면 일정한 면적의 지표면이 받는 태양 에너지양이 달라진다는 사실을 바탕으로 만들어졌다.","scoring_points":["추적형 발전기가 하는 일을 썼는가","햇빛 지도가 하는 일을 썼는가","바탕이 된 과학적 사실을 썼는가"]},"explanation":["두 기술을 가려요.","하는 일을 써요.","과학적 사실을 써요."],"asset":{"type":"passage","lines":["견학한 발전소의 발전기는 태양을 따라 방향과 각도를 바꾼다.","발전소를 세울 곳은 햇빛 지도를 보고 골랐다고 한다.","만든 전기는 마을의 학교와 집으로 보낸다."],"title":"솔빛반 신문 ⑧ 태양광 발전소 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#1','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C1',1,'ox','auto','여름에는 나뭇잎의 색깔이 짙어지고 계곡이나 바다에서 물놀이를 해요.',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"ox","stem":"여름에는 나뭇잎의 색깔이 짙어지고 계곡이나 바다에서 물놀이를 해요.","answer":"O","reason_options":[{"t":"여름에는 잎이 무성해지고 더워 물놀이를 즐기기 때문에","correct":true},{"t":"여름에는 나뭇잎이 모두 떨어지기 때문에","mis":"SC6-2-u1-X01"}],"mis":"SC6-2-u1-X01","explanation":["짙은 초록 잎이에요.","더운 계절이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#2','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C2',1,'ox','auto','태양 고도 측정기를 만들 때 막대기는 우드록에 수직이 되도록 고정해요.',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"ox","stem":"태양 고도 측정기를 만들 때 막대기는 우드록에 수직이 되도록 고정해요.","answer":"O","reason_options":[{"t":"수직으로 고정해야 태양 고도를 정확하게 잴 수 있기 때문에","correct":true},{"t":"막대기가 기울어야 그림자가 잘 생기기 때문에","mis":"SC6-2-u1-X05"}],"mis":"SC6-2-u1-X05","explanation":["수직으로 꽂아요.","정확하게 재려면요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#3','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C3',1,'ox','auto','하루 동안 태양 고도는 점점 높아졌다가 다시 낮아져요.',ARRAY['SC6-2-u1-X06']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C3","difficulty":1,"kind":"ox","stem":"하루 동안 태양 고도는 점점 높아졌다가 다시 낮아져요.","answer":"O","reason_options":[{"t":"아침에 낮던 태양이 남중할 때 가장 높았다가 오후에 다시 낮아지기 때문에","correct":true},{"t":"태양 고도는 아침부터 저녁까지 계속 높아지기만 하기 때문에","mis":"SC6-2-u1-X06"}],"mis":"SC6-2-u1-X06","explanation":["아침·한낮·오후를 견줘요.","한낮에 가장 높아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#4','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C4',1,'ox','auto','하루 중 태양이 남중할 때 그림자 길이가 가장 짧아요.',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":4,"concept":"SC6-2-u1-C4","difficulty":1,"kind":"ox","stem":"하루 중 태양이 남중할 때 그림자 길이가 가장 짧아요.","answer":"O","reason_options":[{"t":"남중할 때 태양 고도가 가장 높기 때문에","correct":true},{"t":"남중할 때 태양 고도가 가장 낮기 때문에","mis":"SC6-2-u1-X07"}],"mis":"SC6-2-u1-X07","explanation":["남중하면 가장 높아요.","높으면 그림자가 짧아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#5','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C6',1,'ox','auto','봄과 가을의 태양의 남중 고도와 낮의 길이는 여름과 겨울의 중간 정도예요.',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC6-2-u1-C6","difficulty":1,"kind":"ox","stem":"봄과 가을의 태양의 남중 고도와 낮의 길이는 여름과 겨울의 중간 정도예요.","answer":"O","reason_options":[{"t":"계절별 그래프에서 봄과 가을이 여름과 겨울 사이에 있기 때문에","correct":true},{"t":"봄과 가을에 남중 고도가 가장 높기 때문에","mis":"SC6-2-u1-X13"}],"mis":"SC6-2-u1-X13","explanation":["그래프를 떠올려요.","꼭대기와 바닥 사이예요.","중간 정도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#6','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C7',1,'ox','auto','손전등과 스마트 기기가 이루는 각이 클수록 빛의 세기가 세요.',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"ox","stem":"손전등과 스마트 기기가 이루는 각이 클수록 빛의 세기가 세요.","answer":"O","reason_options":[{"t":"각이 클 때 센서가 받는 에너지양이 많기 때문에","correct":true},{"t":"각이 작을수록 빛이 더 모이기 때문에","mis":"SC6-2-u1-X17"}],"mis":"SC6-2-u1-X17","explanation":["그림자가 짧을 때예요.","각이 커요.","빛이 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#7','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C9',1,'ox','auto','지구는 자전축이 기울어진 채 태양 주위를 공전해요.',ARRAY['SC6-2-u1-X21']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"ox","stem":"지구는 자전축이 기울어진 채 태양 주위를 공전해요.","answer":"O","reason_options":[{"t":"실제 지구의 자전축은 기울어져 있고 그 채로 태양 둘레를 돌기 때문에","correct":true},{"t":"실제 지구의 자전축은 수직이기 때문에","mis":"SC6-2-u1-X21"}],"mis":"SC6-2-u1-X21","explanation":["실제 지구예요.","자전축이 기울었어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#8','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C11',1,'ox','auto','햇빛 지도를 보면 태양광 발전기를 어디에 세우면 좋을지 알 수 있어요.',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":8,"concept":"SC6-2-u1-C11","difficulty":1,"kind":"ox","stem":"햇빛 지도를 보면 태양광 발전기를 어디에 세우면 좋을지 알 수 있어요.","answer":"O","reason_options":[{"t":"장소별로 받을 수 있는 태양 에너지양을 알려 주기 때문에","correct":true},{"t":"햇빛 지도는 비가 올 날짜만 알려 주기 때문에","mis":"SC6-2-u1-X24"}],"mis":"SC6-2-u1-X24","explanation":["장소별 정보예요.","많이 받는 곳을 찾아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#9','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C3',2,'ox','auto','솔빛반 신문 ①에서 태양 고도가 가장 높은 시각과 기온이 가장 높은 시각은 같아요.',ARRAY['SC6-2-u1-X09']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C3","difficulty":2,"kind":"ox","stem":"솔빛반 신문 ①에서 태양 고도가 가장 높은 시각과 기온이 가장 높은 시각은 같아요.","answer":"X","reason_options":[{"t":"태양 고도는 12시 30분, 기온은 14시 30분에 가장 높아 두 시각에 차이가 있기 때문에","correct":true},{"t":"태양 고도가 가장 높으면 기온도 바로 가장 높기 때문에","mis":"SC6-2-u1-X09"}],"mis":"SC6-2-u1-X09","explanation":["두 줄의 꼭짓점을 찾아요.","시각이 달라요.","같지 않아요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#10','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C5',2,'ox','auto','기온은 햇빛이 직접 닿는 땅바닥에 온도계를 놓고 재요.',ARRAY['SC6-2-u1-X12']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C5","difficulty":2,"kind":"ox","stem":"기온은 햇빛이 직접 닿는 땅바닥에 온도계를 놓고 재요.","answer":"X","reason_options":[{"t":"그늘지고 지표면에서 1.5 m 정도 떨어진 곳에서 재야 하기 때문에","correct":true},{"t":"햇빛이 닿아야 기온이 정확하기 때문에","mis":"SC6-2-u1-X12"}],"mis":"SC6-2-u1-X12","explanation":["직사광선을 피해요.","땅에서 떨어져요.","그늘 1.5 m 높이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#11','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C6',2,'ox','auto','솔빛반 신문 ②의 조사 자료에는 조사한 지역과 연도를 함께 적어 두는 것이 좋아요.',ARRAY['SC6-2-u1-X16']::text[],false,'{"seq":11,"concept":"SC6-2-u1-C6","difficulty":2,"kind":"ox","stem":"솔빛반 신문 ②의 조사 자료에는 조사한 지역과 연도를 함께 적어 두는 것이 좋아요.","answer":"O","reason_options":[{"t":"지역과 연도에 따라 값에 차이가 있기 때문에","correct":true},{"t":"지역과 연도는 값과 아무 관계가 없기 때문에","mis":"SC6-2-u1-X16"}],"mis":"SC6-2-u1-X16","explanation":["값이 지역마다 달라요.","나중에 견주려면 필요해요.","적어 두어요."],"asset":{"type":"passage","lines":["우리 고장에서 매월 21일 남중 고도와 낮의 길이를 조사했다.","남중 고도 그래프 — 6월에 가장 높고 12월에 가장 낮았다.","낮의 길이 그래프 — 6월에 가장 길고 12월에 가장 짧았다.","서울특별시 자료와 견주니 값이 조금 달랐다."],"title":"솔빛반 신문 ② 우리 고장 한 해 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#12','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C7',2,'ox','auto','솔빛반 신문 ③의 ㉠은 태양 고도가 높을 때를 나타내요.',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":12,"concept":"SC6-2-u1-C7","difficulty":2,"kind":"ox","stem":"솔빛반 신문 ③의 ㉠은 태양 고도가 높을 때를 나타내요.","answer":"O","reason_options":[{"t":"막대 그림자가 짧고 이루는 각이 커서 태양이 높이 떠 있을 때와 같기 때문에","correct":true},{"t":"그림자가 짧을수록 태양 고도가 낮기 때문에","mis":"SC6-2-u1-X07"}],"mis":"SC6-2-u1-X07","explanation":["그림자가 짧아요.","각이 커요.","태양 고도가 높아요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 20 cm로 같게 했다.","㉠ 막대 그림자가 짧을 때 — 빛의 세기 예 1,250","㉡ 막대 그림자가 길 때 — 빛의 세기 예 870"],"title":"솔빛반 신문 ③ 우리 모둠 손전등 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#13','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C8',2,'ox','auto','솔빛반 신문 ⑥의 ㉡ 계절에는 태양의 남중 고도가 낮아요.',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":13,"concept":"SC6-2-u1-C8","difficulty":2,"kind":"ox","stem":"솔빛반 신문 ⑥의 ㉡ 계절에는 태양의 남중 고도가 낮아요.","answer":"O","reason_options":[{"t":"태양이 낮게 떠서 빛이 처마 밑으로 깊이 들어오기 때문에","correct":true},{"t":"태양이 높이 떠서 빛이 처마 밑으로 들어오기 때문에","mis":"SC6-2-u1-X13"}],"mis":"SC6-2-u1-X13","explanation":["빛이 깊이 들어와요.","낮게 떠야 그래요.","남중 고도가 낮아요."],"asset":{"type":"passage","lines":["한옥 처마는 집 안으로 들어오는 태양 빛의 양을 조절한다.","㉠ 계절 — 태양 빛이 처마에 가려져 집 안이 시원하다.","㉡ 계절 — 태양 빛이 처마 밑으로 깊이 들어와 집 안이 따뜻하다."],"title":"솔빛반 신문 ⑥ 한옥 처마 탐방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#14','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C9',2,'ox','auto','솔빛반 신문 ④ 실험에서 다르게 한 조건은 자전축의 기울기 하나뿐이에요.',ARRAY['SC6-2-u1-X22']::text[],false,'{"seq":14,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"ox","stem":"솔빛반 신문 ④ 실험에서 다르게 한 조건은 자전축의 기울기 하나뿐이에요.","answer":"O","reason_options":[{"t":"거리는 30 cm로 같게 하고 자전축을 세운 채와 기울인 채만 다르게 했기 때문에","correct":true},{"t":"거리와 기울기를 함께 바꾸었기 때문에","mis":"SC6-2-u1-X22"}],"mis":"SC6-2-u1-X22","explanation":["같게 한 것을 찾아요.","거리는 늘 같았어요.","기울기만 달라요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 했다.","자전축을 세운 채 — 가·나·다·라 모두 그림자 예 1.5 cm","자전축을 기울인 채 — 가 1.5 · 나 0.9 · 다 1.5 · 라 3.2(cm, 예)"],"title":"솔빛반 신문 ④ 우리 모둠 지구본 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#15','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C10',2,'ox','auto','솔빛반 신문 ⑦은 축제 시기의 남중 고도·낮의 길이·기온을 모두 담았어요.',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":15,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"ox","stem":"솔빛반 신문 ⑦은 축제 시기의 남중 고도·낮의 길이·기온을 모두 담았어요.","answer":"O","reason_options":[{"t":"과학 정보 줄에 세 가지가 모두 들어 있기 때문에","correct":true},{"t":"안내 자료에는 과학 정보를 담지 않아도 되기 때문에","mis":"SC6-2-u1-X23"}],"mis":"SC6-2-u1-X23","explanation":["과학 정보 줄을 읽어요.","세 가지를 찾아요.","모두 있어요."],"asset":{"type":"passage","lines":["솔빛 겨울 빙어 축제 — 1월 ○일~○일, ○○ 저수지","과학 정보 — 남중 고도가 낮고 낮의 길이가 짧으며 기온이 낮다.","안내 — 따뜻한 옷을 입고 오세요. 축제는 해가 지기 전에 마칩니다."],"title":"솔빛반 신문 ⑦ 우리 모둠 축제 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#16','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C11',2,'ox','auto','솔빛반 신문 ⑧에서 학교와 집으로 보내는 것은 태양 에너지가 바뀐 전기 에너지예요.',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":16,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"ox","stem":"솔빛반 신문 ⑧에서 학교와 집으로 보내는 것은 태양 에너지가 바뀐 전기 에너지예요.","answer":"O","reason_options":[{"t":"태양광 발전은 태양 에너지를 전기 에너지로 바꾸기 때문에","correct":true},{"t":"태양 빛을 그대로 전선에 담아 보내기 때문에","mis":"SC6-2-u1-X24"}],"mis":"SC6-2-u1-X24","explanation":["발전소가 만든 것이에요.","전기예요.","태양 에너지가 바뀌었어요."],"asset":{"type":"passage","lines":["견학한 발전소의 발전기는 태양을 따라 방향과 각도를 바꾼다.","발전소를 세울 곳은 햇빛 지도를 보고 골랐다고 한다.","만든 전기는 마을의 학교와 집으로 보낸다."],"title":"솔빛반 신문 ⑧ 태양광 발전소 견학"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#17','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C3',3,'error','auto','솔빛반 신문 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X09','SC6-2-u1-X07']::text[],false,'{"seq":17,"concept":"SC6-2-u1-C3","difficulty":3,"kind":"error","stem":"솔빛반 신문 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"아윤 — 「12시 30분이 태양 고도가 가장 높으니 가장 따뜻했을 거야.」","correct":true,"mis_target":"SC6-2-u1-X09"},{"t":"도하 — 「그림자는 12시 30분에 가장 짧았어.」","mis":"SC6-2-u1-X07"},{"t":"리안 — 「기온은 14시 30분에 가장 높았어.」","mis":"SC6-2-u1-X09"}],"explanation":["기온 줄을 확인해요.","꼭짓점이 늦어요.","아윤이 잘못 말했어요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#18','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C6',3,'error','auto','계절별 그래프를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X15','SC6-2-u1-X14']::text[],false,'{"seq":18,"concept":"SC6-2-u1-C6","difficulty":3,"kind":"error","stem":"계절별 그래프를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"보람 — 「낮의 길이는 21일에만 바뀌고 나머지 날은 같아.」","correct":true,"mis_target":"SC6-2-u1-X15"},{"t":"지수 — 「낮의 길이는 날마다 조금씩 달라져.」","mis":"SC6-2-u1-X15"},{"t":"해인 — 「남중 고도가 높아지면 낮도 길어져.」","mis":"SC6-2-u1-X14"}],"explanation":["21일은 조사한 날이에요.","매일 이어서 바뀌어요.","보람이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#19','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C8',3,'error','auto','여름과 겨울을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X19','SC6-2-u1-X13']::text[],false,'{"seq":19,"concept":"SC6-2-u1-C8","difficulty":3,"kind":"error","stem":"여름과 겨울을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시윤 — 「겨울에는 남중 고도가 낮지만 태양 에너지양은 여름보다 많아.」","correct":true,"mis_target":"SC6-2-u1-X19"},{"t":"가람 — 「여름에는 태양 에너지양이 많아 더워.」","mis":"SC6-2-u1-X19"},{"t":"연우 — 「겨울에는 처마 밑으로 햇빛이 깊이 들어와.」","mis":"SC6-2-u1-X13"}],"explanation":["낮게 뜨면 적게 받아요.","겨울은 적어요.","시윤이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#20','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C9',3,'error','auto','솔빛반 신문 ⑤를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X21']::text[],false,'{"seq":20,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"error","stem":"솔빛반 신문 ⑤를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「여름이 태양에서 더 멀다면 여름이 더 추워야 해.」","correct":true,"mis_target":"SC6-2-u1-X20"},{"t":"수빈 — 「거리보다 남중 고도가 더 중요해.」","mis":"SC6-2-u1-X20"},{"t":"하윤 — 「기울어진 채 공전해서 계절이 생겨.」","mis":"SC6-2-u1-X21"}],"explanation":["거리는 거의 영향이 없어요.","남중 고도가 높아 더워요.","태오가 잘못 말했어요."],"asset":{"type":"passage","lines":["하람 — 「여름에 더운 건 지구가 태양에 가까워지기 때문이야.」","도윤 — 「④ 실험에서 거리는 늘 같았는데도 그림자가 달라졌어.」","선생님 — 북반구는 겨울보다 여름에 태양과 오히려 더 멀어요."],"title":"솔빛반 신문 ⑤ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#21','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C2',3,'error','auto','측정기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X04','SC6-2-u1-X05']::text[],false,'{"seq":21,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"error","stem":"측정기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「막대기를 길게 만들수록 태양 고도가 높게 나와.」","correct":true,"mis_target":"SC6-2-u1-X04"},{"t":"강민 — 「막대기를 길게 하면 그림자도 길어져.」","mis":"SC6-2-u1-X04"},{"t":"서아 — 「여러 모양의 측정기로 잴 수 있어.」","mis":"SC6-2-u1-X05"}],"explanation":["막대기와 그림자가 함께 늘어요.","각은 그대로예요.","윤서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#22','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C11',3,'error','auto','태양 에너지 기술을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X24']::text[],false,'{"seq":22,"concept":"SC6-2-u1-C11","difficulty":3,"kind":"error","stem":"태양 에너지 기술을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"한별 — 「비싼 발전기일수록 태양 에너지를 많이 받아.」","correct":true,"mis_target":"SC6-2-u1-X24"},{"t":"지오 — 「태양을 따라 움직이면 더 많이 받아.」","mis":"SC6-2-u1-X24"},{"t":"유나 — 「햇빛이 많은 곳에 세우면 좋아.」","mis":"SC6-2-u1-X24"}],"explanation":["값이 아니라 원리예요.","태양 고도를 따라가요.","한별이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#23','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C8',4,'mc','auto','솔빛반 신문 ③과 ⑥을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X13','SC6-2-u1-X19']::text[],false,'{"seq":23,"concept":"SC6-2-u1-C8","difficulty":4,"kind":"mc","stem":"솔빛반 신문 ③과 ⑥을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"태양 고도가 높으면 받는 태양 에너지양이 많다는 사실을 우리 조상은 처마로 여름 햇빛을 가리는 데 활용했다","correct":true},{"t":"처마는 태양과의 거리를 바꾸는 장치이다","mis":"SC6-2-u1-X20"},{"t":"여름에는 태양 고도가 낮아 처마가 필요 없다","mis":"SC6-2-u1-X13"},{"t":"손전등 실험과 처마는 아무 관계가 없다","mis":"SC6-2-u1-X19"}],"explanation":["③은 태양 고도와 에너지양이에요.","⑥은 여름 햇빛을 가려요.","사실을 생활에 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#24','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C8',4,'essay','teacher','솔빛반 신문 ③의 결과를 쓰고, 이것으로 솔빛반 신문 ⑥의 한옥 처마가 여름에는 햇빛을 가리고 겨울에는 들이는 까닭을 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u1-C8","difficulty":4,"kind":"essay","stem":"솔빛반 신문 ③의 결과를 쓰고, 이것으로 솔빛반 신문 ⑥의 한옥 처마가 여름에는 햇빛을 가리고 겨울에는 들이는 까닭을 설명하세요.","answer_guide":{"answer":"예: 막대 그림자가 짧아 이루는 각이 클 때 빛의 세기는 예 1,250으로, 그림자가 길어 각이 작을 때의 예 870보다 셌다. 태양 고도가 높을수록 일정한 면적의 지표면이 받는 태양 에너지양이 많다는 뜻이다. 여름에는 남중 고도가 높아 받는 태양 에너지양이 많고 더우므로 처마가 높이 뜬 태양 빛을 가려 집 안을 시원하게 하고, 겨울에는 남중 고도가 낮아 태양 빛이 처마 밑으로 깊이 들어와 집 안을 따뜻하게 한다.","scoring_points":["③의 실험 결과를 썼는가","태양 고도와 태양 에너지양의 관계를 썼는가","여름·겨울 남중 고도와 처마를 이어 설명했는가"]},"explanation":["두 수를 견줘요.","태양 고도와 에너지양이에요.","처마로 이어요."],"asset":{"type":"passage","lines":["한옥 처마는 집 안으로 들어오는 태양 빛의 양을 조절한다.","㉠ 계절 — 태양 빛이 처마에 가려져 집 안이 시원하다.","㉡ 계절 — 태양 빛이 처마 밑으로 깊이 들어와 집 안이 따뜻하다."],"title":"솔빛반 신문 ⑥ 한옥 처마 탐방"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_c#25','sci',6,2,'u1','','g6_2_sci_u1_review_c','unit_review','SC6-2-u1-C1',4,'essay','teacher','「계절의 변화」 단원에서 배운 것을 바탕으로 우리 주변의 모습이 계절마다 달라지는 까닭을 원인부터 차례로 쓰세요. 여름과 겨울의 모습을 하나씩 예로 드세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u1-C1","difficulty":4,"kind":"essay","stem":"「계절의 변화」 단원에서 배운 것을 바탕으로 우리 주변의 모습이 계절마다 달라지는 까닭을 원인부터 차례로 쓰세요. 여름과 겨울의 모습을 하나씩 예로 드세요.","answer_guide":{"answer":"예: 지구의 자전축이 기울어진 채 태양 주위를 공전하므로 계절에 따라 태양의 남중 고도가 달라진다. 남중 고도가 높은 여름에는 낮이 길고 일정한 면적의 지표면이 받는 태양 에너지양이 많아 기온이 높아서 나뭇잎이 짙어지고 물놀이를 한다. 남중 고도가 낮은 겨울에는 낮이 짧고 태양 에너지양이 적어 기온이 낮아서 눈이 내리고 두꺼운 옷을 입는다.","scoring_points":["자전축이 기울어진 채 공전한다는 원인을 썼는가","남중 고도·낮의 길이·태양 에너지양·기온을 차례로 이었는가","여름과 겨울 모습을 예로 들었는가"]},"explanation":["원인부터 써요.","차례로 이어요.","여름과 겨울을 예로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#1','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C1',1,'error','auto','네 계절의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC6-2-u1-C1","difficulty":1,"kind":"error","stem":"네 계절의 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「봄에는 울긋불긋 단풍이 들어.」","correct":true,"mis_target":"SC6-2-u1-X01"},{"t":"채윤 — 「겨울에는 눈사람을 만들어.」","mis":"SC6-2-u1-X01"},{"t":"도겸 — 「여름에는 물놀이를 해.」","mis":"SC6-2-u1-X01"}],"explanation":["단풍은 가을이에요.","봄에는 꽃이 펴요.","라온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#2','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C2',1,'blank','auto','「태양 고도 측정기에서 태양의 높이를 재려면 (    )를 사용합니다.」 (    )에 알맞은 도구는 어느 것인가요?',ARRAY['SC6-2-u1-X03']::text[],false,'{"seq":2,"concept":"SC6-2-u1-C2","difficulty":1,"kind":"blank","stem":"「태양 고도 측정기에서 태양의 높이를 재려면 (    )를 사용합니다.」 (    )에 알맞은 도구는 어느 것인가요?","options":[{"t":"각도기","correct":true},{"t":"줄자","mis":"SC6-2-u1-X03"},{"t":"온도계","mis":"SC6-2-u1-X03"},{"t":"저울","mis":"SC6-2-u1-X03"}],"explanation":["각을 재요.","각을 재는 도구예요.","각도기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#3','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C3',1,'blank','auto','「하루 동안 태양 고도가 높아지면 그림자 길이는 (    ).」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":3,"concept":"SC6-2-u1-C3","difficulty":1,"kind":"blank","stem":"「하루 동안 태양 고도가 높아지면 그림자 길이는 (    ).」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"짧아집니다","correct":true},{"t":"길어집니다","mis":"SC6-2-u1-X07"},{"t":"그대로입니다","mis":"SC6-2-u1-X07"},{"t":"사라집니다","mis":"SC6-2-u1-X07"}],"explanation":["높이 뜬 태양이에요.","그림자가 줄어요.","짧아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#4','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C4',1,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-2-u1-C4","difficulty":1,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"남중","r":"태양이 정남쪽에 위치하는 것"},{"l":"남중 고도","r":"남중했을 때의 태양 고도"},{"l":"낮의 길이","r":"태양이 지평선 위로 떠 있는 시간"}],"mis":"SC6-2-u1-X10","explanation":["위치, 고도, 시간을 가려요.","남중은 위치예요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#5','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C6',1,'sa','auto','태양의 남중 고도가 가장 높고 낮의 길이가 가장 긴 계절을 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-2-u1-C6","difficulty":1,"kind":"sa","stem":"태양의 남중 고도가 가장 높고 낮의 길이가 가장 긴 계절을 쓰세요.","answer":["여름"],"explanation":["높고 길어요.","더운 계절이에요.","여름이에요."],"mis":"SC6-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#6','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C7',1,'blank','auto','「태양 고도가 높아질수록 일정한 면적의 지표면이 받는 태양 에너지양이 (    ).」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":6,"concept":"SC6-2-u1-C7","difficulty":1,"kind":"blank","stem":"「태양 고도가 높아질수록 일정한 면적의 지표면이 받는 태양 에너지양이 (    ).」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"많아집니다","correct":true},{"t":"적어집니다","mis":"SC6-2-u1-X17"},{"t":"같아집니다","mis":"SC6-2-u1-X17"},{"t":"없어집니다","mis":"SC6-2-u1-X17"}],"explanation":["높이 뜬 태양이에요.","빛이 세게 닿아요.","많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#7','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C9',1,'mc','auto','계절의 변화가 생기지 않는 경우는 어느 것인가요?',ARRAY['SC6-2-u1-X21','SC6-2-u1-X22']::text[],false,'{"seq":7,"concept":"SC6-2-u1-C9","difficulty":1,"kind":"mc","stem":"계절의 변화가 생기지 않는 경우는 어느 것인가요?","options":[{"t":"자전축이 수직인 채 공전할 때","correct":true},{"t":"자전축이 기울어진 채 공전할 때","mis":"SC6-2-u1-X21"},{"t":"지구가 태양 둘레를 돌 때","mis":"SC6-2-u1-X21"},{"t":"자전축이 늘 같은 방향을 향할 때","mis":"SC6-2-u1-X22"}],"explanation":["세운 채 실험을 떠올려요.","그림자가 모두 같았어요.","수직인 채일 때예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#8','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C10',1,'sa','auto','계절 축제 안내 자료를 쉽고 빠르게 만들 때 쓴 도구는 무엇인가요? (□□□ 플랫폼)','{}'::text[],false,'{"seq":8,"concept":"SC6-2-u1-C10","difficulty":1,"kind":"sa","stem":"계절 축제 안내 자료를 쉽고 빠르게 만들 때 쓴 도구는 무엇인가요? (□□□ 플랫폼)","answer":["디자인","디자인 플랫폼","디자인플랫폼"],"explanation":["글자·사진을 배치해요.","세 글자예요.","디자인 플랫폼이에요."],"mis":"SC6-2-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#9','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C3',2,'mc','auto','솔빛반 신문 ①에서 13시 30분부터 15시 30분까지 그림자 길이는 어떻게 달라졌나요?',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":9,"concept":"SC6-2-u1-C3","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ①에서 13시 30분부터 15시 30분까지 그림자 길이는 어떻게 달라졌나요?","options":[{"t":"점점 길어졌다","correct":true},{"t":"점점 짧아졌다","mis":"SC6-2-u1-X07"},{"t":"그대로였다","mis":"SC6-2-u1-X07"},{"t":"한 번 짧아졌다가 길어졌다","mis":"SC6-2-u1-X07"}],"explanation":["11.9 → 14.8 → 21.4예요.","태양 고도는 낮아져요.","그림자는 길어져요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#10','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C5',2,'error','auto','야외에서 측정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X12']::text[],false,'{"seq":10,"concept":"SC6-2-u1-C5","difficulty":2,"kind":"error","stem":"야외에서 측정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유하 — 「시간 간격은 그때그때 마음대로 바꾸자.」","correct":true,"mis_target":"SC6-2-u1-X12"},{"t":"주아 — 「한 시간 간격으로 재자.」","mis":"SC6-2-u1-X12"},{"t":"건호 — 「끝나면 손을 꼭 씻자.」","mis":"SC6-2-u1-X12"}],"explanation":["일정한 간격이 필요해요.","그래야 그래프로 견줘요.","유하가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#11','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C6',2,'mc','auto','솔빛반 신문 ②의 그래프를 점만 찍지 않고 꺾은선으로 이었을 때 알 수 있는 것은 어느 것인가요?',ARRAY['SC6-2-u1-X15','SC6-2-u1-X14']::text[],false,'{"seq":11,"concept":"SC6-2-u1-C6","difficulty":2,"kind":"mc","stem":"솔빛반 신문 ②의 그래프를 점만 찍지 않고 꺾은선으로 이었을 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"낮의 길이는 월별로 끊기지 않고 연속적으로 달라진다","correct":true},{"t":"낮의 길이는 달이 바뀔 때만 바뀐다","mis":"SC6-2-u1-X15"},{"t":"낮의 길이는 일 년 내내 같다","mis":"SC6-2-u1-X14"},{"t":"낮의 길이는 아무렇게나 바뀐다","mis":"SC6-2-u1-X15"}],"explanation":["점을 이어 봐요.","이어진 변화가 보여요.","연속적으로 달라져요."],"asset":{"type":"passage","lines":["우리 고장에서 매월 21일 남중 고도와 낮의 길이를 조사했다.","남중 고도 그래프 — 6월에 가장 높고 12월에 가장 낮았다.","낮의 길이 그래프 — 6월에 가장 길고 12월에 가장 짧았다.","서울특별시 자료와 견주니 값이 조금 달랐다."],"title":"솔빛반 신문 ② 우리 고장 한 해 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#12','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C7',2,'error','auto','솔빛반 신문 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X17','SC6-2-u1-X18']::text[],false,'{"seq":12,"concept":"SC6-2-u1-C7","difficulty":2,"kind":"error","stem":"솔빛반 신문 ③을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민우 — 「㉡처럼 그림자가 길 때 태양 에너지를 더 많이 받아.」","correct":true,"mis_target":"SC6-2-u1-X17"},{"t":"소이 — 「㉠의 빛의 세기가 더 세.」","mis":"SC6-2-u1-X17"},{"t":"태경 — 「손전등은 태양을 나타내.」","mis":"SC6-2-u1-X18"}],"explanation":["870이 더 작아요.","그림자가 길면 약해요.","민우가 잘못 말했어요."],"asset":{"type":"passage","lines":["손전등과 스마트 기기 사이 거리 — 20 cm로 같게 했다.","㉠ 막대 그림자가 짧을 때 — 빛의 세기 예 1,250","㉡ 막대 그림자가 길 때 — 빛의 세기 예 870"],"title":"솔빛반 신문 ③ 우리 모둠 손전등 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#13','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C8',2,'blank','auto','「겨울에는 태양의 남중 고도가 낮아 일정한 면적의 지표면이 받는 태양 에너지양이 (    ) 춥습니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC6-2-u1-X19','SC6-2-u1-X17']::text[],false,'{"seq":13,"concept":"SC6-2-u1-C8","difficulty":2,"kind":"blank","stem":"「겨울에는 태양의 남중 고도가 낮아 일정한 면적의 지표면이 받는 태양 에너지양이 (    ) 춥습니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"적어","correct":true},{"t":"많아","mis":"SC6-2-u1-X19"},{"t":"같아","mis":"SC6-2-u1-X17"},{"t":"없어져","mis":"SC6-2-u1-X17"}],"explanation":["겨울은 낮게 떠요.","받는 양이 줄어요.","적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#14','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C9',2,'error','auto','솔빛반 신문 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-2-u1-X20','SC6-2-u1-X22']::text[],false,'{"seq":14,"concept":"SC6-2-u1-C9","difficulty":2,"kind":"error","stem":"솔빛반 신문 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시하 — 「기울인 채 결과가 다른 건 거리가 달라서야.」","correct":true,"mis_target":"SC6-2-u1-X20"},{"t":"준우 — 「기울인 채일 때만 그림자 길이가 달라졌어.」","mis":"SC6-2-u1-X22"},{"t":"나윤 — 「거리는 30 cm로 같게 했어.」","mis":"SC6-2-u1-X22"}],"explanation":["거리는 바꾸지 않았어요.","기울기만 달라요.","시하가 잘못 말했어요."],"asset":{"type":"passage","lines":["전등과 지구본 사이 거리 — 30 cm로 늘 같게 했다.","자전축을 세운 채 — 가·나·다·라 모두 그림자 예 1.5 cm","자전축을 기울인 채 — 가 1.5 · 나 0.9 · 다 1.5 · 라 3.2(cm, 예)"],"title":"솔빛반 신문 ④ 우리 모둠 지구본 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#15','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C10',2,'error','auto','솔빛반 신문 ⑦에 친구들이 댓글을 달았어요. 바르지 않은 댓글을 쓴 친구는 누구인가요?',ARRAY['SC6-2-u1-X23']::text[],false,'{"seq":15,"concept":"SC6-2-u1-C10","difficulty":2,"kind":"error","stem":"솔빛반 신문 ⑦에 친구들이 댓글을 달았어요. 바르지 않은 댓글을 쓴 친구는 누구인가요?","options":[{"t":"하진 — 「꾸밈이 심심하니 다시 만들어.」","correct":true,"mis_target":"SC6-2-u1-X23"},{"t":"예서 — 「낮이 짧다는 정보를 운영 시간과 잘 이었네.」","mis":"SC6-2-u1-X23"},{"t":"은호 — 「옷차림 안내가 친절해.」","mis":"SC6-2-u1-X23"}],"explanation":["잘한 점을 칭찬해요.","꾸밈 평가는 아니에요.","하진의 댓글이 바르지 않아요."],"asset":{"type":"passage","lines":["솔빛 겨울 빙어 축제 — 1월 ○일~○일, ○○ 저수지","과학 정보 — 남중 고도가 낮고 낮의 길이가 짧으며 기온이 낮다.","안내 — 따뜻한 옷을 입고 오세요. 축제는 해가 지기 전에 마칩니다."],"title":"솔빛반 신문 ⑦ 우리 모둠 축제 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#16','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C11',2,'sa','auto','솔빛반 신문 ⑧처럼 태양을 따라 움직이는 발전기를 무엇이라고 하나요? (□□□ 태양광 발전기)','{}'::text[],false,'{"seq":16,"concept":"SC6-2-u1-C11","difficulty":2,"kind":"sa","stem":"솔빛반 신문 ⑧처럼 태양을 따라 움직이는 발전기를 무엇이라고 하나요? (□□□ 태양광 발전기)","answer":["추적형","추적형 태양광 발전기"],"explanation":["태양을 쫓아가요.","세 글자예요.","추적형이에요."],"mis":"SC6-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#17','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C3',3,'ox','auto','솔빛반 신문 ①에서 오후 3시 30분의 그림자가 오전 9시 30분보다 긴 것은 그때 태양 고도가 더 낮기 때문이에요.',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":17,"concept":"SC6-2-u1-C3","difficulty":3,"kind":"ox","stem":"솔빛반 신문 ①에서 오후 3시 30분의 그림자가 오전 9시 30분보다 긴 것은 그때 태양 고도가 더 낮기 때문이에요.","answer":"O","reason_options":[{"t":"15시 30분의 태양 고도(25°)가 9시 30분(28°)보다 낮기 때문에","correct":true},{"t":"15시 30분의 태양 고도가 더 높기 때문에","mis":"SC6-2-u1-X07"}],"mis":"SC6-2-u1-X07","explanation":["두 시각의 태양 고도를 견줘요.","25가 28보다 작아요.","낮으면 그림자가 길어요."],"asset":{"type":"passage","lines":["시각 — 9:30 · 10:30 · 11:30 · 12:30 · 13:30 · 14:30 · 15:30","태양 고도(°) — 28 · 36 · 41 · 43 · 40 · 34 · 25","그림자 길이(cm) — 18.8 · 13.8 · 11.5 · 10.7 · 11.9 · 14.8 · 21.4","기온(°C) — 15.2 · 17.0 · 18.6 · 19.8 · 20.6 · 20.9 · 20.4"],"title":"솔빛반 신문 ① 가을날 운동장 관찰(막대기 10 cm)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#18','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C6',3,'ox','auto','계절별로 같은 시각에 잰 그림자 길이 그래프는 태양의 남중 고도 그래프와 모양이 반대예요.',ARRAY['SC6-2-u1-X07']::text[],false,'{"seq":18,"concept":"SC6-2-u1-C6","difficulty":3,"kind":"ox","stem":"계절별로 같은 시각에 잰 그림자 길이 그래프는 태양의 남중 고도 그래프와 모양이 반대예요.","answer":"O","reason_options":[{"t":"남중 고도가 높을수록 그림자가 짧아지기 때문에","correct":true},{"t":"남중 고도가 높을수록 그림자도 길어지기 때문에","mis":"SC6-2-u1-X07"}],"mis":"SC6-2-u1-X07","explanation":["높으면 짧아요.","거꾸로 움직여요.","모양이 반대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#19','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C7',3,'ox','auto','한낮의 운동장에서 그늘이 아닌 곳이 아침보다 더 따뜻한 것은 한낮의 태양 고도가 더 높기 때문이에요.',ARRAY['SC6-2-u1-X17']::text[],false,'{"seq":19,"concept":"SC6-2-u1-C7","difficulty":3,"kind":"ox","stem":"한낮의 운동장에서 그늘이 아닌 곳이 아침보다 더 따뜻한 것은 한낮의 태양 고도가 더 높기 때문이에요.","answer":"O","reason_options":[{"t":"태양 고도가 높을수록 일정한 면적의 지표면이 받는 태양 에너지양이 많기 때문에","correct":true},{"t":"한낮에는 태양이 지구와 더 가까워지기 때문에","mis":"SC6-2-u1-X17"}],"mis":"SC6-2-u1-X17","explanation":["아침과 한낮의 태양 고도를 견줘요.","한낮이 높아요.","많이 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#20','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C9',3,'ox','auto','북반구가 여름일 때 지구와 태양 사이의 거리는 겨울일 때보다 오히려 더 멀어요.',ARRAY['SC6-2-u1-X20']::text[],false,'{"seq":20,"concept":"SC6-2-u1-C9","difficulty":3,"kind":"ox","stem":"북반구가 여름일 때 지구와 태양 사이의 거리는 겨울일 때보다 오히려 더 멀어요.","answer":"O","reason_options":[{"t":"거리는 계절에 거의 영향이 없고 여름에 오히려 조금 더 멀기 때문에","correct":true},{"t":"여름에는 지구가 태양에 가장 가까워지기 때문에","mis":"SC6-2-u1-X20"}],"mis":"SC6-2-u1-X20","explanation":["선생님 말을 떠올려요.","여름이 더 멀어요.","맞는 말이에요."],"asset":{"type":"passage","lines":["하람 — 「여름에 더운 건 지구가 태양에 가까워지기 때문이야.」","도윤 — 「④ 실험에서 거리는 늘 같았는데도 그림자가 달라졌어.」","선생님 — 북반구는 겨울보다 여름에 태양과 오히려 더 멀어요."],"title":"솔빛반 신문 ⑤ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#21','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C2',3,'ox','auto','이쑤시개 측정기는 이쑤시개 그림자가 보이지 않도록 조절했을 때의 각을 읽어요.',ARRAY['SC6-2-u1-X05']::text[],false,'{"seq":21,"concept":"SC6-2-u1-C2","difficulty":3,"kind":"ox","stem":"이쑤시개 측정기는 이쑤시개 그림자가 보이지 않도록 조절했을 때의 각을 읽어요.","answer":"O","reason_options":[{"t":"그림자가 사라질 때 측정기가 태양 빛과 나란해져 그때의 각이 태양 고도이기 때문에","correct":true},{"t":"그림자가 가장 길 때 각을 읽어야 하기 때문에","mis":"SC6-2-u1-X05"}],"mis":"SC6-2-u1-X05","explanation":["그림자를 없애요.","태양 빛과 나란해져요.","그때 각을 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#22','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C10',3,'ox','auto','여름 축제 안내에 「태양의 남중 고도가 높아 색안경을 준비하세요」라고 쓴 것은 과학 정보를 안내와 알맞게 이은 것이에요.',ARRAY['SC6-2-u1-X13']::text[],false,'{"seq":22,"concept":"SC6-2-u1-C10","difficulty":3,"kind":"ox","stem":"여름 축제 안내에 「태양의 남중 고도가 높아 색안경을 준비하세요」라고 쓴 것은 과학 정보를 안내와 알맞게 이은 것이에요.","answer":"O","reason_options":[{"t":"남중 고도가 높아 태양 빛이 강하므로 눈을 보호하는 안내가 알맞기 때문에","correct":true},{"t":"여름에는 남중 고도가 낮아 햇빛이 약하기 때문에","mis":"SC6-2-u1-X13"}],"mis":"SC6-2-u1-X13","explanation":["여름 남중 고도는 높아요.","햇빛이 강해요.","알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#23','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C11',4,'mc','auto','솔빛반 신문 ⑦과 ⑧을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SC6-2-u1-X23','SC6-2-u1-X24','SC6-2-u1-X13']::text[],false,'{"seq":23,"concept":"SC6-2-u1-C11","difficulty":4,"kind":"mc","stem":"솔빛반 신문 ⑦과 ⑧을 함께 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"계절과 하루에 따라 태양 고도가 달라진다는 사실을 알면 축제 안내와 발전소 운영처럼 생활에 활용할 수 있다","correct":true},{"t":"과학 정보는 교과서에서만 쓰인다","mis":"SC6-2-u1-X23"},{"t":"발전소는 새로운 기술이라서 좋은 것이다","mis":"SC6-2-u1-X24"},{"t":"겨울 축제는 남중 고도가 높아 해가 늦게 진다","mis":"SC6-2-u1-X13"}],"explanation":["⑦은 계절 정보를 썼어요.","⑧은 태양 고도 변화를 썼어요.","생활에 활용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#24','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C9',4,'essay','teacher','솔빛반 신문 ④의 두 결과를 견주어 계절의 변화가 생기는 까닭을 쓰고, 솔빛반 신문 ⑤의 하람에게 바로잡아 줄 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-2-u1-C9","difficulty":4,"kind":"essay","stem":"솔빛반 신문 ④의 두 결과를 견주어 계절의 변화가 생기는 까닭을 쓰고, 솔빛반 신문 ⑤의 하람에게 바로잡아 줄 말을 쓰세요.","answer_guide":{"answer":"예: 자전축을 세운 채 공전하면 네 위치의 그림자 길이가 모두 1.5 cm로 같아 남중 고도가 달라지지 않는다. 기울인 채 공전하면 위치에 따라 0.9 cm에서 3.2 cm까지 그림자 길이가 달라져 남중 고도가 달라진다. 실제 지구는 자전축이 기울어진 채 태양 주위를 공전하므로 계절이 생긴다. 하람아, 실험에서 거리는 늘 30 cm였는데도 그림자가 달라졌고, 북반구는 여름에 태양과 오히려 더 멀어. 여름에 더운 것은 태양과 가까워서가 아니라 남중 고도가 높아 태양 에너지양이 많기 때문이야.","scoring_points":["두 결과를 견주었는가","기울어진 채 공전해서 계절이 생긴다고 썼는가","거리 대신 남중 고도로 바로잡았는가"]},"explanation":["두 줄을 견줘요.","원인을 써요.","하람에게 근거를 들어요."],"asset":{"type":"passage","lines":["하람 — 「여름에 더운 건 지구가 태양에 가까워지기 때문이야.」","도윤 — 「④ 실험에서 거리는 늘 같았는데도 그림자가 달라졌어.」","선생님 — 북반구는 겨울보다 여름에 태양과 오히려 더 멀어요."],"title":"솔빛반 신문 ⑤ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_2_sci_u1_review_d#25','sci',6,2,'u1','','g6_2_sci_u1_review_d','unit_review','SC6-2-u1-C5',4,'essay','teacher','하루 동안 태양 고도·그림자 길이·기온을 재어 꺾은선그래프로 나타내는 계획을 세우세요. 측정 장소와 방법, 측정 간격, 그래프를 그리는 방법, 안전 수칙을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-2-u1-C5","difficulty":4,"kind":"essay","stem":"하루 동안 태양 고도·그림자 길이·기온을 재어 꺾은선그래프로 나타내는 계획을 세우세요. 측정 장소와 방법, 측정 간격, 그래프를 그리는 방법, 안전 수칙을 쓰세요.","answer_guide":{"answer":"예: 태양 빛이 잘 드는 평평한 운동장에 태양 고도 측정기를 놓고, 실을 그림자 끝에 맞추어 태양 고도와 그림자 길이를 잰다. 같은 시각에 그늘지고 지표면에서 1.5 m 정도 높이에서 기온을 잰다. 오전 9시 30분부터 한 시간 간격으로 12시 30분을 포함해 잰다. 가로축에 측정 시각을 일정한 간격으로 쓰고 세 가지를 다른 색 꺾은선그래프로 그린 뒤 가로축을 맞춰 겹친다. 태양을 직접 보지 않고 모자를 쓰며 활동 뒤 손을 씻는다.","scoring_points":["측정 장소와 재는 방법을 썼는가","일정한 측정 간격과 그래프 그리는 방법을 썼는가","안전 수칙을 썼는가"]},"explanation":["어디서 어떻게 재나요.","간격과 그래프예요.","안전을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
